 readonly=\\"1\\"/>\\n                                        <span class=\\"ms-2\\">horas/día</span>\\n                                    </div>\\n                                </group>\\n                                <group>\\n                                    <label for=\\"hours_per_week\\" string=\\"Total\\"/>\\n                                    <div class=\\"d-flex\\">\\n                                        <field name=\\"hours_per_week\\" nolabel=\\"1\\" style=\\"width: 6ch;\\" widget=\\"float_time\\" readonly=\\"1\\"/>\\n                                        <span class=\\"ms-2\\">horas/semana</span>\\n                                    </div>\\n                                </group>\\n                            </group>\\n                            <field name=\\"attendance_ids\\" widget=\\"section_one2many\\"/>\\n                        </page>\\n                        <page string=\\"Horas laborales de la semana 1\\" name=\\"working_hours\\" invisible=\\"flexible_hours or not two_weeks_calendar\\">\\n                            <field name=\\"two_weeks_explanation\\"/>\\n                            <group>\\n                                <group>\\n                                    <label for=\\"hours_per_day\\" string=\\"Promedio\\"/>\\n                                    <div class=\\"d-flex\\">\\n                                        <field name=\\"hours_per_day\\" nolabel=\\"1\\" style=\\"width: 6ch;\\" widget=\\"float_time\\" readonly=\\"1\\"/>\\n                                        <span class=\\"ms-2\\">horas/día</span>\\n                                    </div>\\n                                </group>\\n                                <group>\\n                                    <label for=\\"hours_per_week\\" string=\\"Total\\"/>\\n                                    <div class=\\"d-flex\\">\\n                                        <field name=\\"hours_per_week\\" nolabel=\\"1\\" style=\\"width: 6ch;\\" widget=\\"float_time\\" readonly=\\"1\\"/>\\n                                        <span class=\\"ms-2\\">horas/semana</span>\\n                                    </div>\\n                                </group>\\n                            </group>\\n                            <field name=\\"attendance_ids_1st_week\\" widget=\\"section_one2many\\" context=\\"{'default_week_type':'0'}\\"/>\\n                        </page>\\n                        <page string=\\"Horas laborales de la semana 2\\" name=\\"working_hours\\" invisible=\\"flexible_hours or not two_weeks_calendar\\">\\n                            <field name=\\"two_weeks_explanation\\"/>\\n                            <group>\\n                                <group>\\n                                    <label for=\\"hours_per_day\\" string=\\"Promedio\\"/>\\n                                    <div class=\\"d-flex\\">\\n                                        <field name=\\"hours_per_day\\" nolabel=\\"1\\" style=\\"width: 6ch;\\" widget=\\"float_time\\" readonly=\\"1\\"/>\\n                                        <span class=\\"ms-2\\">horas/día</span>\\n                                    </div>\\n                                </group>\\n                                <group>\\n                                    <label for=\\"hours_per_week\\" string=\\"Total\\"/>\\n                                    <div class=\\"d-flex\\">\\n                                        <field name=\\"hours_per_week\\" nolabel=\\"1\\" style=\\"width: 6ch;\\" widget=\\"float_time\\" readonly=\\"1\\"/>\\n                                        <span class=\\"ms-2\\">horas/semana</span>\\n                                    </div>\\n                                </group>\\n                            </group>\\n                            <field name=\\"attendance_ids_2nd_week\\" widget=\\"section_one2many\\" context=\\"{'default_week_type':'1'}\\"/>\\n                        </page>\\n                    </notebook>\\n   