en()\\"/>\\n                            <textarea class=\\"form-control\\" name=\\"feedback\\" rows=\\"8\\" t-att-value=\\"rating.feedback\\"/>\\n                            <button type=\\"submit\\" class=\\"btn btn-primary mt-4\\" style=\\"margin-top:8px;\\">Send Feedback</button>\\n                        </form>\\n                        <div class=\\"oe_structure\\" id=\\"oe_structure_rate_submit_footer\\"/>\\n                    </div>\\n                </div>\\n            </t>\\n        </t>", "es_ES": "<t name=\\"Rate our Services\\" t-name=\\"rating.rating_external_page_submit\\">\\n            <t t-call=\\"web.frontend_layout\\">\\n                <div class=\\"container mb-5 mt-4 o_rating_page_submit\\">\\n                    <div class=\\"oe_structure\\" id=\\"oe_structure_rate_submit_header\\"/>\\n                    <div class=\\"row text-center justify-content-center\\">\\n                        <h1 class=\\"col-12 mt-5\\">¡Gracias por calificar nuestros servicios!</h1>\\n                        <form class=\\"col-md-6\\" t-attf-action=\\"/rate/#{token}/submit_feedback\\" method=\\"post\\">\\n                            <div class=\\"btn-group row flex-nowrap justify-content-center w-100 mt-5\\" role=\\"group\\" data-bs-toggle=\\"buttons\\">\\n                                <t t-foreach=\\"rate_names\\" t-as=\\"rate_name\\">\\n                                    <input type=\\"radio\\" name=\\"rate\\" class=\\"btn-check\\" t-attf-id=\\"rate_{{rate_name}}\\" t-att-value=\\"rate_name\\" t-att-checked=\\"rate == rate_name\\"/>\\n                                    <label t-attf-class=\\"col p-4 btn o_rating_label shadow-none transition-base {{rate == rate_name and 'active' or ''}}\\" t-att-for=\\"'rate_%s' % (rate_name)\\">\\n                                        <img t-attf-src=\\"/rating/static/src/img/rating_#{rate_name}.svg\\" t-att-alt=\\"rate_name_value\\" t-att-title=\\"rate_name_value\\" t-attf-class=\\"o_{{rate_name_value.lower()}}\\"/>\\n                                    </label>\\n                                </t>\\n                            </div>\\n                            <p class=\\"mt-5\\">\\n                                No dude en escribir un comentario en el que describa su experiencia:\\n                            </p>\\n                            <input type=\\"hidden\\" name=\\"csrf_token\\" t-att-value=\\"request.csrf_token()\\"/>\\n                            <textarea class=\\"form-control\\" name=\\"feedback\\" rows=\\"8\\" t-att-value=\\"rating.feedback\\"/>\\n                            <button type=\\"submit\\" class=\\"btn btn-primary mt-4\\" style=\\"margin-top:8px;\\">Enviar comentarios</button>\\n                        </form>\\n                        <div class=\\"oe_structure\\" id=\\"oe_structure_rate_submit_footer\\"/>\\n                    </div>\\n                </div>\\n            </t>\\n        </t>"}	<?xml version="1.0"?>\n<t name="Rate our Services" t-name="rating.rating_external_page_submit">\n            <t t-call="web.frontend_layout">\n                <div class="container mb-5 mt-4 o_rating_page_submit">\n                    <div class="oe_structure" id="oe_structure_rate_submit_header"/>\n                    <div class="row text-center justify-content-center">\n                        <h1 class="col-12 mt-5">Thank you for rating our services!</h1>\n                        <form class="col-md-6" t-attf-action="/rate/#{token}/submit_feedback" method="post">\n                            <div class="btn-group row flex-nowrap justify-content-center w-100 mt-5" role="group" data-bs-toggle="buttons">\n                                <t t-foreach="rate_names" t-as="rate_name">\n                                    <input type="radio" name="rate" class="btn-check" t-attf-id="rate_{{rate_name}}" t-att-value="rate_name" t-att-checked="rate == rate_name"/>\n                                    <label t-attf-class="col p-4 btn o_rating_label shadow-none transition-base {{rate == rate_name and 'active' or ''}}" t-att-for="'rate_%s' % (rate_name)">\n                                        <img t-attf-src="/rating/static/src/img/rating_#{rate_name}.svg" t-att-alt="rate_name_value" t-att-title="rate_name_value" t-attf-class="o_{{rate_name_value.lower()}}"/>\n                                    </label>\n                                </t>\n                            </div>\n                            <p class="mt-5">\n                                Feel free to share feedback on your experience:\n                            </p>\n                            <input type="hidden" name="csrf_token" t-att-value="request.csrf_token()"/>\n                            <textarea class="form-control" name="feedback" rows="8" t-att-value="rating.feedback"/>\n                            <button type="submit" class="btn btn-primary mt-4" style="margin-top:8px;">Send Feedback</button>\n                        </form>\n                        <div class="oe_structure" id="oe_structure_rate_submit_footer"/>\n                    </div>\n                </div>\n            </t>\n        </t>\n	f	t	2026-11-20 12:39:41.760915	2026-11-20 12:39:41.760915	f	\N	\N	\N	\N	\N	\N	\N	\N	\N	f	f
256	16	\N	1	1	Barcode Nomenclatures	barcode.nomenclature	\N	form	barcodes/views/barcodes_view.xml	primary	{"en_US": "<form string=\\"Barcode Nomenclature\\">\\n                    <sheet>\\n                        <group name=\\"general_attributes\\" col=\\"4\\">\\n                            <field name=\\"name\\"/>\\n                            <field name=\\"upc_ean_conv\\"/>\\n                        </group>\\n                        <div>\\n                            <p>\\n                                <i>Barcodes Nomenclatures</i> define how barcodes are recognized and categorized.\\n                                When a barcode is scanned it is associated to the <i>first</i> rule with a matching\\n                                pattern. The pattern syntax is that of regular expression, and a barcode is matched\\n                                if the regular expression matches a prefix of the barcode.\\n                            </p><p>\\n                                Patterns can also define how numerical values, such as weight or price, can be\\n                                encoded into the barcode. They are indicated by <code>{NNN}</code> where the N's\\n                                define where the number's digits are encoded. Floats are also supported with the\\n                                decimals indicated with D's, such as <code>{NNNDD}</code>. In these cases,\\n                                the barcode field on the associated records <i>must</i> show these digits as\\n                                zeroes.\\n                            </p>\\n                        </div>\\n                        <field name=\\"rule_ids\\">\\n                            <list string=\\"Tables\\">\\n                                <field name=\\"sequence\\" widget=\\"handle\\"/>\\n                                <field name=\\"name\\"/>\\n                                <field name=\\"type\\"/>\\n                                <field name=\\"encoding\\"/>\\n                                <field name=\\"pattern\\"/>\\n                            </list>\\n                        </field>\\n                    </sheet>\\n                </form>", "es_ES": "<form string=\\"Nomenclatura de código de barras\\">\\n                    <sheet>\\n                        <group name=\\"general_attributes\\" col=\\"4\\">\\n                            <field name=\\"name\\"/>\\n                            <field name=\\"upc_ean_conv\\"/>\\n                        </group>\\n                        <div>\\n                            <p>\\n                                Las <i>nomenclaturas de códigos de barras</i> definen cómo se reconocen y categorizan\\nlos códigos de barras. Cuando se escanea un código de barras se asocia a la <i>primera</i>\\nregla con un patrón coincidente. La sintaxis de los patrones es la de una expresión\\nregular, y un código de barras se reconoce si la expresión regular coincide con un\\nprefijo del código de barras.\\n                            </p><p>\\n                                Los patrones también pueden definir el modo en que los valores numéricos, como el peso o el precio, pueden\\n                                codificarse en el código de barras. Estos se indican con el parámetro <code>{NNN}</code> donde las N\\n                                definen dónde se codifican los dígitos del número. También se admiten valores flotantes con los\\n                                decimales indicados con D, como <code>{NNNDD}</code>. En estos casos,\\n                                el campo de código de barras de los registros asociados <i>debe</i> mostrar estos dígitos como\\n                                ceros.\\n                            </p>\\n                        </div>\\n                        <field name=\\"rule_ids\\">\\n                            <list string=\\"Tablas\\">\\n                                <field name=\\"sequence\\" widget=\\"handle\\"/>\\n                                <field name=\\"name\\"/>\\n                                <field name=\\"type\\"/>\\n                                <field name=\\"encoding\\"/>\\n                                <field name=\\"pattern\\"/>\\n                            </list>\\n                        </field>\\n                    </sheet>\\n                </form>"}	<?xml version="1.0"?>\n<form string="Barcode Nomenclature">\n                    <sheet>\n                        <group name="general_attributes" col="4">\n                            <field name="name"/>\n                            <field name="upc_ean_conv"/>\n                        </group>\n                        <div>\n                            <p>\n                                <i>Barcodes Nomenclatures</i> define how barcodes are recognized and categorized.\n                                When a barcode is scanned it is associated to the <i>first</i> rule with a matching\n                                pattern. The pattern syntax is that of regular expression, and a barcode is matched\n                                if the regular expression matches a prefix of the barcode.\n                            </p><p>\n                                Patterns can also define how numerical values, such as weight or price, can be\n                                encoded into the barcode. They are indicated by <code>{NNN}</code> where the N's\n                                define where the number's digits are encoded. Floats are also supported with the\n                                decimals indicated with D's, such as <code>{NNNDD}</code>. In these cases,\n                                the barcode field on the associated records <i>must</i> show these digits as\n                                zeroes.\n                            </p>\n                        </div>\n                        <field name="rule_ids">\n                            <list string="Tables">\n                          