uct_variants[product]\\"/>\\n            <t t-if=\\"variant and variant.with_context(bin_size=True).image_128\\" t-set=\\"all_images_list\\" t-value=\\"variant._get_images()\\"/>\\n            <t t-else=\\"\\" t-set=\\"all_images_list\\" t-value=\\"product._get_images()\\"/>\\n            <!--\\n                Image holders are records of different types (`product.template`, `product.product`\\n                or `product.image`) and are returned as a list.\\n             -->\\n            <t t-set=\\"primary_image_holder\\" t-value=\\"(all_images_list[:1]+[product])[0]\\"/>\\n            <t t-set=\\"secondary_image_holder\\" t-value=\\"(all_images_list[1:2]+[False])[0]\\"/>\\n\\n            <a t-att-href=\\"product_href\\" t-attf-class=\\"oe_product_image_link position-relative {{secondary_image_holder and 'oe_product_image_link_has_secondary'}}\\" contenteditable=\\"false\\" t-att-title=\\"product.name\\">\\n                <!-- Primary image -->\\n                <span t-field=\\"primary_image_holder.image_1920\\" t-options=\\"{'widget': 'image', 'preview_image': 'image_1024', 'class': 'oe_product_image_img h-100 w-100'}\\" class=\\"oe_product_image_img_wrapper oe_product_image_img_wrapper_primary d-flex h-100 justify-content-center align-items-center\\"/>\\n\\n                <!-- Secondary image -->\\n                <span t-if=\\"secondary_image_holder\\" t-field=\\"secondary_image_holder.image_1920\\" t-options=\\"{'widget': 'image', 'preview_image': 'image_1024', 'class': 'oe_product_image_img_secondary h-100 w-100'}\\" class=\\"oe_product_image_img_wrapper oe_product_image_img_wrapper_secondary h-100 justify-content-center align-items-center\\"/>\\n\\n                <!-- Ribbon -->\\n                <t t-if=\\"show_ribbons\\">\\n                    <t t-set=\\"bg_color\\" t-value=\\"ribbon.bg_color\\"/>\\n                    <t t-set=\\"text_color\\" t-value=\\"ribbon.text_color\\"/>\\n                    <span t-att-data-ribbon-id=\\"ribbon.id\\" t-attf-class=\\"o_ribbons o_not_editable #{ribbon._get_css_classes()}\\" t-attf-style=\\"#{text_color and ('color: %s;' % text_color)} #{bg_color and 'background-color:' + bg_color}\\" t-out=\\"ribbon.name or ''\\"/>\\n                </t>\\n            </a>\\n        </div>\\n        <div class=\\"o_wsale_product_information flex-grow-1 flex-shrink-1\\">\\n            <div class=\\"o_wsale_product_info_attributes_wrapper\\">\\n                <!-- Variations/Attributes -->\\n                <t t-if=\\"product_ptavs_data\\" t-call=\\"website_sale.product_variant_preview\\"/>\\n\\n                <!-- Information -->\\n                <div class=\\"o_wsale_product_information_text\\">\\n                    <!-- Product Name -->\\n                    <h2 class=\\"o_wsale_products_item_title text-break\\">\\n                        <a class=\\"text-decoration-none\\" t-att-href=\\"product_href\\">\\n                            <span t-field=\\"product.name\\"/>\\n                            <t t-if=\\"product_variant\\" t-set=\\"combination_name\\" t-value=\\"product_variant.product_template_attribute_value_ids._get_combination_name()\\"/>\\n                            <span t-if=\\"combination_name\\" t-out=\\"'('+combination_name+')'\\"/>\\n                        </a>\\n                        <a t-if=\\"not product.website_published\\" role=\\"button\\" t-att-href=\\"product_href\\" class=\\"btn btn-sm btn-danger\\" title=\\"This product is unpublished.\\">\\n                            Unpublished\\n                        </a>\\n                    </h2>\\n                    <!-- Description -->\\n                    <t t-call=\\"website_sale.product_tile_element_visibility\\">\\n                        <t t-set=\\"visible_element_class\\" t-value=\\"'o_wsale_products_opt_has_description'\\"/>\\n\\n                        <div class=\\"oe_subdescription_wrapper\\">\\n                            <div class=\\"oe_subdescription text-muted small\\" contenteditable=\\"false\\">\\n                                <div t-field=\\"product.description_sale\\"/>\\n                            </div>\\n                        </div>\\n                    </t>\\n                    <!-- Rating -->\\n                    <t t-if=\\"is_view_active('website_sale.product_comment')\\" t-call=\\"website_sale.product_tile_element_visibility\\">\\n                        <t t-set=\\"visible_element_class\\" t-value=\\"'o_wsale_products_opt_has_rating'\\"/>\\n\\n                        <div class=\\"o_wsale_product_rating_wrapper\\">\\n                            <t t-call=\\"portal_rating.rating_widget_stars_static\\">\\n                                <!-- sudo: product.product - visitor can access product average rating -->\\n                                <t t-set=\\"rating_avg\\" t-value=\\"product.sudo().rating_avg\\"/>\\n                                <t t-set=\\"rating_count\\" t-value=\\"product.rating_count\\"/>\\n                            </t>\\n                        </div>\\n                    </t>\\n                    <t t-if=\\"product_extra_information\\" t-out=\\"product_extra_information\\"/>\\n                </div>\\n            </div>\\n            <div class=\\"o_wsale_product_sub justify-content-between gap-2\\">\\n                <!-- Price(s) -->\\n                <t t-if=\\"product_price\\" t-out=\\"product_price\\"/>\\n                <t t-else=\\"\\">\\n                    <t t-set=\\"template_price_vals\\" t-value=\\"get_product_prices(product)\\"/>\\n                    <div class=\\"product_price\\" aria-label=\\"Price information\\">\\n                        <span class=\\"mb-0 fw-bold\\" aria-label=\\"Sale price\\" t-if=\\"template_price_vals['price_reduce'] or not website.prevent_zero_price_sale\\" t-out=\\"template_price_vals['price_reduce']\\" t-options=\\"{'widget': 'monetary', 'display_currency': website.currency_id}\\"/>\\n                        <t t-if=\\"'base_price' in template_price_vals and (template_price_vals['base_price'] &gt; template_price_vals['price_reduce']) and (template_price_vals['price_reduce'] or not website.prevent_zero_price_sale)\\" name=\\"product_base_price\\">\\n                            <del aria-label=\\"Original price\\" t-attf-class=\\"text-muted me-1 mb-0\\" style=\\"white-space: nowrap;\\">\\n                                <small t-esc=\\"template_price_vals['base_price']\\" t-options=\\"{'widget': 'monetary', 'display_currency': website.currency_id}\\"/>\\n                            </del>\\n                        </t>\\n                    </div>\\n                </t>\\n                <!-- Actions -->\\n                <div class=\\"o_wsale_product_btn\\">\\n                    <t t-if=\\"product_actions\\" t-out=\\"product_actions\\"/>\\n                    <t t-else=\\"\\" t-call=\\"website_sale.shop_product_buttons\\"/>\\n                </div>\\n            </div>\\n            <!-- Extra actions (wishlist remove, ...) -->\\n            <t t-if=\\"extra_actions\\" t-out=\\"extra_actions\\"/>\\n        </div>\\n    </form>\\n</t>", "es_ES": "<t name=\\"Products item\\" t-name=\\"website_sale.products_item\\">\\n    <!-- Parameters:\\n        - show_variations: Whether to show the variant preview on the tile.\\n        - show_ribbons: Whether to show the ribbons.\\n        - product: `product.template` record.\\n        - product_variant: `product.product` record.\\n    -->\\n    <t t-set=\\"show_variations\\" t-value=\\"True if show_variations is None else show_variations\\"/>\\n    <t t-set=\\"show_ribbons\\" t-value=\\"True if show_ribbons is None else show_ribbons\\"/>\\n\\n    <!-- Variations/Attributes -->\\n    <t t-if=\\"show_variations\\">\\n        <t t-set=\\"product_ptavs_data\\" t-value=\\"previewed_attribute_values[product.id]\\"/>\\n        <t t-if=\\"product_ptavs_data\\">\\n            <t t-set=\\"product_ptavs\\" t-value=\\"product_ptavs_data.get('ptavs_data')\\"/>\\n            <t t-if=\\"product_ptavs[0]['