px 16px 0px;\\"/>\\n                        </td></tr>\\n                    </table>\\n                </td>\\n            </tr>\\n            <!-- CONTENT -->\\n            <tr>\\n                <td align=\\"center\\" style=\\"min-width: 590px;\\">\\n                    <table border=\\"0\\" cellpadding=\\"0\\" cellspacing=\\"0\\" width=\\"590\\" style=\\"min-width: 590px; background-color: white; padding: 0px 8px 0px 8px; border-collapse:separate;\\">\\n                        <tr><td valign=\\"top\\" style=\\"font-size: 13px;\\">\\n                            <div>\\n                                Dear <t t-out=\\"object.name or ''\\">Marc Demo</t>,<br/><br/>\\n                                A password reset was requested for the account linked to this email.\\n                                You may change your password by following this link which will remain valid during <t t-out=\\"user.env['ir.config_parameter'].sudo().get_param('auth_signup.reset_password.validity.hours',4)\\"/> hours:<br/>\\n                                <div style=\\"margin: 16px 0px 16px 0px;\\">\\n                                    <a t-att-href=\\"object.partner_id._get_signup_url()\\" t-attf-style=\\"background-color: {{object.company_id.email_secondary_color or '#875A7B'}}; padding: 8px 16px 8px 16px; text-decoration: none; color: {{object.company_id.email_primary_color or '#FFFFFF'}}; border-radius: 5px; font-size:13px;\\">\\n                                        Change password\\n                                    </a>\\n                                </div>\\n                                If you do not expect this, you can safely ignore this email.<br/><br/>\\n                                Thanks,\\n                                <t t-if=\\"user.signature\\">\\n                                    <br/>\\n                                    <t t-out=\\"user.signature\\">--<br/>Mitchell Admin</t>\\n                                </t>\\n                            </div>\\n                        </td></tr>\\n                        <tr><td style=\\"text-align:center;\\">\\n                          <hr width=\\"100%\\" style=\\"background-color:rgb(204,204,204);border:medium none;clear:both;display:block;font-size:0px;min-height:1px;line-height:0; margin: 16px 0px 16px 0px;\\"/>\\n                        </td></tr>\\n                    </table>\\n                </td>\\n            </tr>\\n            <!-- FOOTER -->\\n            <tr>\\n                <td align=\\"center\\" style=\\"min-width: 590px;\\">\\n                    <table border=\\"0\\" cellpadding=\\"0\\" cellspacing=\\"0\\" width=\\"590\\" style=\\"min-width: 590px; background-color: white; font-size: 11px; padding: 0px 8px 0px 8px; border-collapse:separate;\\">\\n                        <tr><td valign=\\"middle\\" align=\\"left\\">\\n                            <t t-out=\\"object.company_id.name or ''\\">YourCompany</t>\\n                        </td></tr>\\n                        <tr><td valign=\\"middle\\" align=\\"left\\" style=\\"opacity: 0.7;\\">\\n                            <t t-out=\\"object.company_id.phone or ''\\">+1 650-123-4567</t>\\n\\n                            <t t-if=\\"object.company_id.email\\">\\n                                | <a t-att-href=\\"'mailto:%s' % object.company_id.email\\" style=\\"text-decoration:none; color: #454748;\\" t-out=\\"object.company_id.email\\">info@yourcompany.com</a>\\n                            </t>\\n                            <t t-if=\\"object.company_id.website\\">\\n                                | <a t-att-href=\\"'%s' % object.company_id.website\\" style=\\"text-decoration:none; color: #454748;\\" t-out=\\"object.company_id.website\\">http://www.example.com</a>\\n                            </t>\\n                        </td></tr>\\n                    </table>\\n                </td>\\n            </tr>\\n        </tbody>\\n        </table>\\n        </td></tr>\\n        <!-- POWERED BY -->\\n     