nbr_reordering_rules\\" widget=\\"statinfo\\"/>\\n                            </button>\\n                            <button type=\\"object\\" name=\\"action_view_stock_move_lines\\" invisible=\\"type != 'consu'\\" class=\\"oe_stat_button\\" icon=\\"fa-exchange\\" groups=\\"stock.group_stock_user\\">\\n                                <div class=\\"d-flex flex-column\\">\\n                                    <div class=\\"o_field_widget o_stat_info align-items-baseline flex-row gap-1 me-1\\">\\n                                        <span class=\\"o_stat_text\\">Entrada:</span>\\n                                        <span class=\\"o_stat_value\\"><field name=\\"nbr_moves_in\\"/></span>\\n                                    </div>\\n                                    <div class=\\"o_field_widget o_stat_info align-items-baseline flex-row gap-1 me-1\\">\\n                                        <span class=\\"o_stat_text\\">Salida:</span>\\n                                        <span class=\\"o_stat_value\\"><field name=\\"nbr_moves_out\\"/></span>\\n                                    </div>\\n                                </div>\\n                            </button>\\n                            <button type=\\"object\\" name=\\"action_open_product_lot\\" invisible=\\"tracking == 'none'\\" class=\\"oe_stat_button\\" icon=\\"fa-bars\\" groups=\\"stock.group_production_lot\\">\\n                                <div class=\\"o_stat_info\\">\\n                                    <span class=\\"o_stat_text\\">Números de lote o serie</span>\\n                                </div>\\n                            </button>\\n                            <button type=\\"object\\" name=\\"action_view_related_putaway_rules\\" class=\\"oe_stat_button\\" icon=\\"fa-random\\" groups=\\"stock.group_stock_multi_locations\\" invisible=\\"type == 'service'\\" context=\\"{                                     'invisible_handle': True,                                     'single_product': product_variant_count == 1,                                 }\\">\\n                                    <div class=\\"o_stat_info\\">\\n                                        <span class=\\"o_stat_text\\">Reglas de almacenamiento</span>\\n                                    </div>\\n                             </button>\\n                             <button type=\\"object\\" name=\\"action_view_storage_category_capacity\\" groups=\\"stock.group_stock_multi_locations\\" invisible=\\"type == 'service'\\" class=\\"oe_stat_button\\" icon=\\"fa-cubes\\">\\n                                <div class=\\"o_stat_info\\">\\n                                    <span class=\\"o_stat_text\\">Capacidades de almacenamiento</span>\\n                                </div>\\n                            </button>\\n                        </t>\\n                    </button>\\n\\n                    <xpath expr=\\"//label[@for='weight']\\" position=\\"before\\">\\n                        <field name=\\"responsible_id\\" domain=\\"[('share', '=', False)]\\" widget=\\"many2one_avatar_user\\" groups=\\"stock.group_stock_user\\"/>\\n                    </xpath>\\n                </data>"}	<?xml version="1.0"?>\n<data>\n                    <button name="action_open_documents" position="before">\n                        <t groups="stock.group_stock_user">\n                            <field name="tracking" invisible="1"/>\n                            <field name="show_on_hand_qty_status_button" invisible="1"/>\n                            <field name="show_forecasted_qty_status_button" invisible="1"/>\n                            <button type="object" name="action_product_tmpl_forecast_report" invisible="not show_forecasted_qty_status_button" context="{'default_product_tmpl_id': id}" class="oe_stat_button" icon="fa-area-chart">\n                                <div class="d-flex flex-row gap-1 ms-1">\n                                    <div class="o_field_widget o_stat_info flex-column align-items-end gap-1">\n                                        <span class="o_stat_value">\n                                            <field name="qty_available" widget="statinfo" nolabel="1"/>\n                                        </span>\n                                        <span class="o_stat_value" invisible="virtual_available != 0">\n                                            <field name="virtual_available" nolabel="1"/>\n                                        </span>\n                                        <span class="o_stat_value text-info" invisible="virtual_available &lt;= 0">\n                                            <field name="virtual_available" nolabel="1"/>\n                                        </span>\n                                        <span class="o_stat_value text-danger" invisible="virtual_available &gt;= 0">\n                                            <field name="virtual_available" nolabel="1"/>\n                                        </span>\n                                    </div>\n                                    <div class="o_field_widget o_stat_info flex-column align-items-start gap-1">\n                                        <span class="o_stat_value">\n                                            <field name="uom_name" widget="statinfo" nolabel="1" groups="uom.group_uom"/>\n                                            <span groups="!uom.group_uom">On Hand</span>\n                                        </span>\n                                        <span class="o_stat_value text-muted">\n                                            Forecasted\n                                        </span>\n                                    </div>\n                                </div>\n                            </button>\n                        </t>\n                    </button>\n                    <button name="action_open_documents" position="after">\n                        <t groups="stock.group_stock_user">\n                            <button type="object" name="action_view_orderpoints" invisible="not is_storable or nbr_reordering_rules != 1" class="oe_stat_button" icon="fa-refresh">\n                                <div class="d-flex flex-column">\n                                    <div class="o_field_widget o_stat_info align-items-baseline flex-row gap-1 me-1">\n                                        <span class="o_stat_text">Min:</span>\n                                        <span class="o_stat_value"><field name="reordering_min_qty"/></span>\n                                    </div>\n                                    <div class="o_field_widget o_stat_info align-items-baseline flex-row gap-1 me-1">\n                                        <span class="o_stat_text">Max:</span>\n                                        <span class="o_stat_value"><field name="reordering_max_qty"/></span>\n                                    </div>\n                                </div>\n                            </button>\n                            <button type="object" name="action_view_orderpoints" invisible="not is_storable or nbr_reordering_rules == 1" class="oe_stat_button" icon="fa-refresh">\n                                <field name="nbr_reordering_rules" widget="statinfo"/>\n                            </button>\n                            <button type="object" name="action_view_stock_move_lines" invisible="type != 'consu'" class="oe_stat_button" icon="fa-exchange" groups="stock.group_stock_user">\n                                <div class="d-flex flex-column">\n                                    <div class="o_field_widget o_stat_info align-items-baseline flex-row gap-1 me-1">\n                                        <span class="o_stat_text">In:</span>\n                                        <span class="o_stat_value"><field name="nbr_moves_in"/></span>\n                                    </div>\n                                    <div class="o_field_widget o_stat_info align-items-baseline flex-row gap-1 me-1">\n                                        <span class="o_stat_text">Out:</span>\n                                        <span class="o_stat_value"><field name="nbr_moves_out"/></span>\n                                    </div>\n                                </div>\n                            </button>\n                            <button type="object" name="action_open_product_lot" invisible="tracking == 'none'" class="oe_stat_button" icon="fa-bars" groups="stock.group_production_lot">\n                                <div class="o_stat_info">\n                                    <span class="o_stat_text">Lot/Serial Numbers</span>\n                                </div>\n                            </button>\n                            <button type="object" name="action_view_related_putaway_rules" class="oe_stat_button" icon="fa-random" groups="stock.group_stock_multi_locations" invisible="type == 'service'" context="{                                     'invisible_handle': True,                                     'single_product': product_variant_count == 1,                                 }">\n                                    <div class="o_stat_info">\n                                        <span class="o_stat_text">Putaway Rules</span>\n                                    </div>\n                             </button>\n                             <button type="object" name="action_view_storage_category_capacity" groups="stock.group_stock_multi_locations" invisible="type == 'service'" class="oe_stat_button" icon="fa-cubes">\n                                <div class="o_stat_info">\n                                    <span class="o_stat_text">Storage Capacities</span>\n                                </div>\n                            </button>\n                        </t>\n                    </button>\n\n                    <xpath expr="//label[@for='weight']" position="before">\n                        <field name="responsible_id" domain="[('share', '=', False)]" widget="many2one_avatar_user" groups="stock.group_stock_user"/>\n                    </xpath>\n                </data>\n            	f	t	2026-11-17 08:00:00.870439	2026-11-20 12:35:53.984544	f	\N	\N	\N	\N	\N	\N	\N	\N	\N	f	\N
2554	16	\N	1	1	website_sale.sidebar_dropzone_at_bottom	\N	website_sale.sidebar_dropzone_at_bottom	qweb	website_sale/views/templates.xml	primary	{"en_US": "<t t-name=\\"website_sale.sidebar_dropzone_at_bottom\\">\\n        <div id=\\"oe_structure_website_sale_sidebar_bottom\\" class=\\"oe_structure\\">\\n            <section class=\\"s_text_block oe_unmovable oe_unremovable\\" data-snippet=\\"s_text_block\\" data-name=\\"Text\\">\\n                <p/>\\n            </section>\\n        </div>\\n    </t>"}	<?xml version="1.0"?>\n<t t-name="website_sale.sidebar_dropzone_at_bottom">\n        <div id="oe_structure_website_sale_sidebar_bottom" class="oe_structure">\n            <section class="s_text_block oe_unmovable oe_unremovable" data-snippet="s_text_block" data-name="Text">\n                <p/>\n            </section>\n        </div>\n    </t>\n\n    	f	t	2026-11-20 12:39:46.036801	2026-11-20 12:39:46.036801	f	\N	\N	\N	\N	\N	\N	\N	\N	\N	f	f
2552	16	\N	1	1	Products	\N	website_sale.products	qweb	website_sale/views/templates.xml	primary	{"en_US": "<t name=\\"Products\\" t-name=\\"website_sale.products\\">\\n        <t t-call=\\"website.layout\\">\\n            <t t-set=\\"additional_title\\" t-value=\\"category.name\\"/>\\n            <t t-set=\\"grid_block_name\\">Grid</t>\\n            <t t-set=\\"product_block_name\\">Product</t>\\n\\n            <!-- Qweb variable defining the class suffix for navbar items.\\n                 Change accordingly to the derired visual result (eg. `primary`, `dark`...)-->\\n            <t t-set=\\"navClass\\" t-valuef=\\"light\\"/>\\n\\n            <!-- Check for active options: the stored value may be used in sub-templates too  -->\\n            <t t-set=\\"opt_wsale_fullwidth\\" t-value=\\"website.shop_page_container == 'fluid'\\"/>\\n            <t t-set=\\"opt_wsale_categories\\" t-value=\\"is_view_active('website_sale.products_categories')\\"/>\\n            <t t-set=\\"opt_wsale_attributes\\" t-value=\\"is_view_active('website_sale.products_attributes')\\"/>\\n            <t t-set=\\"opt_wsale_filter_price\\" t-value=\\"is_view_active('website_sale.filter_products_price')\\"/>\\n            <t t-set=\\"opt_wsale_filter_tags\\" t-value=\\"is_view_active('website_sale.filter_products_tags')\\"/>\\n            <t t-set=\\"opt_wsale_design_grid\\" t-value=\\"'o_wsale_products_opt_design_grid' in website.shop_opt_products_design_classes\\"/>\\n\\n            <t t-set=\\"opt_wsale_categories_top\\" t-value=\\"is_view_active('website_sale.products_categories_top')\\"/>\\n            <t t-set=\\"opt_wsale_attributes_top\\" t-value=\\"is_view_active('website_sale.products_attributes_top')\\"/>\\n            <t t-set=\\"opt_wsale_floating_bar\\" t-value=\\"is_view_active('website_sale.floating_bar')\\"/>\\n\\n            <t t-set=\\"opt_wsale_show_shop_title\\" t-value=\\"is_view_active('website_sale.products_shop_title')\\"/>\\n            <t t-set=\\"opt_wsale_shop_title_align\\" t-value=\\"is_view_active('website_sale.products_shop_title_align')\\"/>\\n\\n            <t t-set=\\"opt_wsale_show_category_title\\" t-value=\\"bool(category) and category.show_category_title\\"/>\\n            <t t-set=\\"opt_wsale_show_category_description\\" t-value=\\"bool(category) and category.show_category_description\\"/>\\n            <t t-set=\\"opt_wsale_category_align\\" t-value=\\"bool(category) and category.align_category_content\\"/>\\n\\n            <t t-set=\\"website_sale_pricelists\\" t-value=\\"website.get_pricelist_available(show_visible=True)\\"/>\\n            <t t-set=\\"website_sale_sortable\\" t-value=\\"website._get_product_sort_mapping()\\"/>\\n\\n            <t t-set=\\"hasLeftColumn\\" t-value=\\"opt_wsale_categories or opt_wsale_attributes\\"/>\\n\\n            <t t-set=\\"isFilteringByPrice\\" t-if=\\"opt_wsale_filter_price\\" t-value=\\"float_round(available_min_price, 2) != float_round(min_price, 2) or float_round(available_max_price, 2) != float_round(max_price, 2)\\"/>\\n            <t t-set=\\"hasPricelistDropdown\\" t-value=\\"website_sale_pricelists and len(website_sale_pricelists)&gt;1\\"/>\\n            <t t-set=\\"isSortingBy\\" t-value=\\"[sort for sort in website_sale_sortable if sort[0]==request.params.get('order', '')]\\"/>\\n\\n            <t t-set=\\"wsale_has_filters_btn\\" t-value=\\"opt_wsale_categories or opt_wsale_attributes or opt_wsale_attributes_top\\"/>\\n            <t t-set=\\"wsale_has_filters_btn_lg\\" t-value=\\"opt_wsale_attributes_top\\"/>\\n\\n            <div id=\\"wrap\\" class=\\"js_sale o_wsale_products_page\\">\\n                <div class=\\"oe_structure oe_empty oe_structure_not_nearest\\" id=\\"oe_structure_website_sale_products_1\\"/>\\n                <div id=\\"o_wsale_container\\" t-attf-class=\\"oe_website_sale                         {{opt_wsale_fullwidth and 'container-fluid o_wsale_page_fluid' or 'o_wsale_page_contained container'}}                         {{opt_wsale_categories_top and 'o_wsale_has_filmstrip'}}                         {{opt_wsale_floating_bar and 'o_wsale_has_floating_bar'}}                         {{hasLeftColumn and 'o_wsale_has_sidebar'}}                         {{editionPreviews and 'o_wsale_edit_preview_enabled'}}                         {{opt_wsale_design_grid and 'o_wsale_uses_grid_design'}}\\" t-att-data-ppg=\\"ppg\\" t-att-data-ppr=\\"ppr\\" t-att-data-default-sort=\\"website.shop_default_sort\\">\\n                    <div class=\\"row o_wsale_products_main_row flex-nowrap\\">\\n                        <aside t-if=\\"hasLeftColumn\\" id=\\"products_grid_before\\" class=\\"d-none d-lg-block position-sticky align-self-start col clearfix pt-2\\">\\n                            <t t-call=\\"website_sale.sidebar_dropzone_at_top\\"/>\\n                            <div class=\\"o_wsale_products_grid_before_rail vh-100 ms-n2 px-lg-2 ps-2 overflow-y-scroll\\">\\n                                <t t-set=\\"is_sidebar_collapsible\\" t-value=\\"is_view_active('website_sale.products_categories_list_collapsible')\\"/>\\n                                <div t-if=\\"opt_wsale_categories\\" t-att-class=\\"'products_categories'                                                 + (' accordion accordion-flush' if is_sidebar_collapsible else ' mb-3')\\">\\n                                    <t t-call=\\"website_sale.products_categories_list\\"/>\\n                                </div>\\n                                <t t-set=\\"show_price_filter\\" t-value=\\"opt_wsale_filter_price and opt_wsale_attributes\\"/>\\n                                <div t-if=\\"attrib_values or tags or (                                         show_price_filter and isFilteringByPrice                                     )\\" class=\\"py-3 border-bottom\\">\\n                                    <a t-att-href=\\"keep(attribute_values=0, tags=0, min_price=0, max_price=0)\\" t-attf-class=\\"btn btn-{{navClass}} d-flex align-items-center py-1\\" title=\\"Clear Filters\\">\\n                                        <small class=\\"mx-auto\\"><b>Clear Filters</b></small>\\n                                        <i class=\\"oi oi-close\\" role=\\"presentation\\"/>\\n                                    </a>\\n                                </div>\\n                                <div t-attf-class=\\"products_attributes_filters d-empty-none {{opt_wsale_categories and 'border-top'}} {{'pt-3' if not is_sidebar_collapsible else ''}}\\"/>\\n                                <t t-if=\\"show_price_filter\\" t-call=\\"website_sale.filter_products_price\\">\\n                                    <t t-set=\\"_classes\\" t-valuef=\\"{{is_sidebar_collapsible and 'accordion accordion-flush'}} {{is_sidebar_collapsible and (opt_wsale_categories or len(attributes) &gt; 0) and 'border-top'}}\\"/>\\n                                </t>\\n                                <t t-call=\\"website_sale.sidebar_dropzone_at_bottom\\"/>\\n                            </div>\\n                        </aside>\\n                        <div id=\\"products_grid\\" class=\\"col\\">\\n                            <t t-set=\\"_header_has_content\\" t-value=\\"category or opt_wsale_categories_top or (not opt_wsale_floating_bar and (opt_wsale_attributes_top or is_view_active('website_sale.search') or is_view_active('website_sale.sort') or hasPricelistDropdown))\\"/>\\n\\n                            <header id=\\"o_wsale_products_header\\" t-att-data-category-id=\\"category.id\\" t-att-data-category-name=\\"category.name\\" t-attf-class=\\"d-flex flex-column gap-2                                     {{_header_has_content and 'pt-4 pb-3' or opt_wsale_design_grid and 'py-3'}}                                     {{category and 'o_wsale_products_header_is_category' or 'o_wsale_products_header_is_shop'}}                                     {{opt_wsale_show_category_title and 'o_wsale_products_header_show_category_title'}}                                     {{opt_wsale_show_category_description and 'o_wsale_products_header_show_category_description'}}                                     {{opt_wsale_category_align and 'o_wsale_products_header_category_center_content'}}                                     {{opt_wsale_show_shop_title and 'o_wsale_products_header_show_shop_title'}}                                     {{opt_wsale_shop_title_align and 'o_wsale_products_header_shop_center_content'}}\\">\\n                                <t t-if=\\"category and not search\\" t-call=\\"website_sale.products_breadcrumb\\">\\n                                    <t t-set=\\"_classes\\" t-valuef=\\"w-100 p-0 mb-0 small {{not opt_wsale_show_category_title and 'mb-2 mb-lg-0'}}\\"/>\\n                                </t>\\n                                <h1 t-if=\\"category or search\\" t-attf-class=\\"o_wsale_category_title d-flex gap-1 align-items-center mb-0 lh-lg {{search and bool(category) and 'mb-2'}} {{search and 'o_wsale_category_title_is_search base-fs font-sans-serif' or 'fs-3'}}\\">\\n                                    <t t-if=\\"search and category\\">\\n                                        <span class=\\"text-muted\\">Searching</span>\\n                                        <span class=\\"badge text-bg-info fw-normal base-fs\\">\\n                                            <t t-out=\\"search\\"/>\\n                                            <a title=\\"Clear search for this category\\" t-att-href=\\"keep(search=0)\\" class=\\"link-info\\">\\n                                                <i class=\\"oi oi-close\\" role=\\"img\\"/>\\n                                            </a>\\n                                        </span>\\n                                        <span class=\\"text-muted\\">in</span>\\n                                        <span class=\\"badge text-bg-primary fw-normal base-fs\\">\\n                                            <t t-out=\\"category.name\\"/>\\n                                            <a title=\\"Search globally\\" t-att-href=\\"keep(shop_path, search=search)\\">\\n                                                <i class=\\"oi oi-close\\" role=\\"img\\"/>\\n                                            </a>\\n                                        </span>\\n                                    </t>\\n                                    <span t-elif=\\"search\\">\\n                                        <span class=\\"text-muted\\">Search results for </span>'<strong t-out=\\"search\\"/>' <small t-if=\\"search_count\\" class=\\"text-muted\\"> (<t t-out=\\"search_count\\"/>)</small>\\n                                    </span>\\n                                    <t t-elif=\\"category\\">\\n                                        <span t-field=\\"category.name\\"/>\\n                                    </t>\\n                                </h1>\\n                                <h1 class=\\"o_wsale_shop_title h4-fs\\" t-if=\\"not category and not search\\">\\n                                    All products\\n                                </h1>\\n                                <t t-if=\\"category\\">\\n                                    <t t-set=\\"editor_msg\\">\\n                                        Drag building blocks here to customize the header for\\n                                        \\"<t t-out=\\"category.name\\"/>\\" category.\\n                                    </t>\\n                                    <div id=\\"category_header\\" class=\\"o_wsale_category_description\\" t-att-data-editor-message=\\"editor_msg\\" t-field=\\"category.website_description\\"/>\\n                                </t>\\n                                <t t-else=\\"\\">\\n                                    <t t-set=\\"editor_msg\\">\\n                                        Drag building blocks here to customize the header for the shop page.\\n                                    </t>\\n                                    <div id=\\"oe_structure_products_header_shop\\" class=\\"oe_structure oe_empty\\" t-att-data-editor-message=\\"editor_msg\\"/>\\n                                </t>\\n                                <t t-if=\\"opt_wsale_categories_top and category_entries\\" t-call=\\"website_sale.filmstrip_categories\\" entries=\\"category_entries\\"/>\\n                                <div t-if=\\"not opt_wsale_floating_bar\\" class=\\"products_header btn-toolbar flex-nowrap align-items-center justify-content-between gap-1 gap-lg-2 gap-xl-3\\">\\n                                    <t t-if=\\"is_view_active('website_sale.search')\\">\\n                                        <t t-set=\\"_has_all_sibligns\\" t-value=\\"hasPricelistDropdown and is_view_active('website_sale.sort') and wsale_has_filters_btn\\"/>\\n                                        <!-- Desktop Search button -->\\n                                        <div t-attf-class=\\"o_wsale_products_header_search_form_container {{ _has_all_sibligns and 'd-none d-sm-inline-block'}} col-xl-5 me-auto {{not hasLeftColumn and 'col-xl-6'}}\\">\\n                                            <t t-set=\\"search_term\\">Search in</t>\\n                                            <t t-if=\\"category\\" t-set=\\"placeholder\\" t-valuef=\\"{{ search_term }} {{ category.name }}\\"/>\\n                                            <t t-call=\\"website_sale.search\\" placeholder=\\"placeholder\\" search=\\"original_search or search\\"/>\\n                                        </div>\\n                                        <!-- Mobile Search button -->\\n                                        <a t-attf-class=\\"btn o_not_editable {{_has_all_sibligns and 'd-inline-block d-sm-none' or 'd-none'}} me-auto btn-{{navClass}}\\" data-bs-target=\\"#o_wsale_search_modal\\" data-bs-toggle=\\"modal\\" role=\\"button\\" title=\\"Search Products\\" href=\\"#\\">\\n                                            <i class=\\"oi oi-search\\" role=\\"img\\"/>\\n                                        </a>\\n                                    </t>\\n                                    <t t-if=\\"hasPricelistDropdown\\" t-call=\\"website_sale.pricelist_list\\"/>\\n                                    <t t-if=\\"is_view_active('website_sale.sort')\\" t-call=\\"website_sale.sort\\"/>\\n                                    <button t-if=\\"wsale_has_filters_btn\\" t-attf-class=\\"btn btn-{{navClass}} position-relative {{not wsale_has_filters_btn_lg and 'd-lg-none'}} {{not is_view_active('website_sale.search') and 'ms-auto'}} text-nowrap\\" title=\\"Filters\\" data-bs-toggle=\\"offcanvas\\" data-bs-target=\\"#o_wsale_offcanvas\\">\\n                                        <i class=\\"oi oi-settings-adjust\\" role=\\"img\\"/>\\n                                        <small t-attf-class=\\"ms-1 {{(hasPricelistDropdown and is_view_active('website_sale.search') and is_view_active('website_sale.sort')) and 'd-none d-md-inline-block'}}\\">Filters</small>\\n                                        <span t-if=\\"isFilteringByPrice or attrib_set or tags\\" t-attf-class=\\"position-absolute top-0 start-100 translate-middle border border-{{navClass}} rounded-circle bg-danger p-1\\">\\n                                            <span class=\\"visually-hidden\\">filters active</span>\\n                                        </span>\\n                                    </button>\\n                                </div>\\n                                <div t-if=\\"original_search and products\\" class=\\"alert alert-warning mt8\\">\\n                                    No results found for '<span t-out=\\"original_search\\"/>'. Showing results for '<span t-out=\\"search\\"/>'.\\n                                </div>\\n                            </header>\\n\\n                            <div t-if=\\"products\\" class=\\"o_wsale_products_grid_table_wrapper\\">\\n                                <t t-set=\\"grid_md_allow_custom_cols\\" t-value=\\"hasLeftColumn\\"/>\\n                                <t t-set=\\"grid_md_use_3col\\" t-value=\\"(not hasLeftColumn and ppr == 4) or (opt_wsale_fullwidth and ppr &gt; 3)\\"/>\\n\\n                                <section id=\\"o_wsale_products_grid\\" t-attf-class=\\"o_wsale_products_grid_table grid                                         {{grid_md_allow_custom_cols and 'o_wsale_products_grid_table_md'}}                                         {{website.shop_opt_products_design_classes}}\\" t-attf-style=\\"--o-wsale-ppr: {{ppr}}; --o-wsale-ppg: {{ppg}}; --o-wsale-products-grid-gap: {{gap}};\\" t-att-data-name=\\"grid_block_name\\">\\n                                    <t t-foreach=\\"bins\\" t-as=\\"tr_product\\">\\n                                        <t t-foreach=\\"tr_product\\" t-as=\\"td_product\\">\\n                                            <t t-if=\\"td_product\\">\\n                                                <t t-set=\\"col_height\\" t-value=\\"td_product['y']\\"/>\\n                                                <t t-set=\\"col_width\\" t-value=\\"12 // ppr * td_product['x']\\"/>\\n                                                <t t-set=\\"col_class\\" t-valuef=\\"g-col-6\\"/>\\n                                                <t t-set=\\"col_class_lg\\" t-value=\\"'g-col-lg-' + str(col_width)\\"/>\\n                                                <t t-set=\\"col_class_md\\" t-value=\\"grid_md_allow_custom_cols and ('g-col-md-' + str(col_width)) or grid_md_use_3col and 'g-col-md-4' or 'g-col-md-6'\\"/>\\n                                                <t t-set=\\"col_is_stretched\\" t-value=\\"(td_product['x'] &gt;= td_product['y'] * 2)\\"/>\\n                                                <t t-set=\\"col_is_custom_portrait\\" t-value=\\"not col_is_stretched and (col_height &gt; td_product['x'])\\"/>\\n                                                <t t-set=\\"product\\" t-value=\\"td_product['product']\\"/>\\n                                                <t t-set=\\"template_price_vals\\" t-value=\\"get_product_prices(product)\\"/>\\n                                                <t t-set=\\"ribbon\\" t-value=\\"product._get_ribbon(                                                         price_vals=template_price_vals,                                                         auto_assign_ribbons=auto_assign_ribbons,                                                         variant=product_variants[product],                                                     )\\"/>\\n                                                <div t-attf-class=\\"oe_product {{col_is_custom_portrait and 'oe_product_custom_portrait'}} {{col_class}} {{col_class_md}} {{col_class_lg}} {{col_is_stretched and 'oe_product_size_stretch'}}\\" t-attf-style=\\"--o-wsale-products-grid-product-col-height: {{col_height}};\\" t-att-data-colspan=\\"td_product['x'] != 1 and td_product['x']\\" t-att-data-rowspan=\\"td_product['y'] != 1 and td_product['y']\\" t-att-data-name=\\"product_block_name\\">\\n                                                    <div t-attf-class=\\"o_wsale_product_grid_wrapper position-relative h-100 o_wsale_product_grid_wrapper_#{td_product['x']}_#{td_product['y']}\\">\\n                                                        <t t-call=\\"website_sale.products_item\\">\\n                                                            <t t-set=\\"design_field\\" t-value=\\"website.shop_opt_products_design_classes\\"/>\\n                                                            <t t-set=\\"product_href\\" t-value=\\"product._get_product_url(category, product_query_params, grouped_attributes_values)\\"/>\\n                                                        </t>\\n                                                    </div>\\n                                                </div>\\n                                            </t>\\n                                        </t>\\n                                    </t>\\n                                </section>\\n                            </div>\\n                            <div t-else=\\"\\" class=\\"text-center text-muted mt128 mb256\\">\\n                                <t t-if=\\"not search\\">\\n                                    <div class=\\"mt-5 mb-3\\"><t t-call=\\"website.empty_search_svg\\"/></div>\\n                                    <h3 class=\\"mt8\\" style=\\"text-align: center;\\">\\n                                        No product defined\\n                                    </h3>\\n                                    <p t-if=\\"category\\" style=\\"text-align: center;\\">\\n                                        No product defined in this category.\\n                                    </p>\\n                                </t>\\n                                <t t-else=\\"\\">\\n                                    <div class=\\"mt-5 mb-3\\"><t t-call=\\"website.empty_search_svg\\"/></div>\\n                                    <h3 class=\\"mt8\\" style=\\"text-align: center;\\">No results</h3>\\n                                    <p style=\\"text-align: center;\\">\\n                                        No results for \\"<strong t-out=\\"search\\"/>\\"<t t-if=\\"category\\"> in category \\"<strong t-out=\\"category.display_name\\"/>\\"</t>.\\n                                    </p>\\n                                    <p style=\\"text-align: center;\\">\\n                                        <a t-if=\\"category\\" t-att-href=\\"keep(shop_path, search=search)\\" t-attf-title=\\"Search {{search}} globally\\" class=\\"d-block pb-5\\">\\n                                            Search globally\\n                                        </a>\\n                                    </p>\\n                                </t>\\n                                <div t-ignore=\\"true\\" groups=\\"sales_team.group_sale_manager\\" class=\\"alert alert-info d-inline-block mx-auto text-center\\">\\n                                    Click <i>'New'</i> in the top-right corner to create your first product.\\n                                </div>\\n                            </div>\\n                            <div id=\\"o_wsale_pager\\" t-attf-class=\\"products_pager d-flex justify-content-center {{opt_wsale_design_grid and 'py-4' or 'py-5 pb-4'}}\\">\\n                                <t t-call=\\"website.pager\\"/>\\n                            </div>\\n                            <t t-if=\\"category\\">\\n                                <t t-set=\\"footer_editor_message\\">\\n                                    Drag building blocks here to customize the footer for\\n                                    \\"<t t-out=\\"category.name\\"/>\\" category.\\n                                </t>\\n                                <div class=\\"mb16\\" id=\\"category_footer\\" t-att-data-editor-message=\\"footer_editor_message\\" t-field=\\"category.website_footer\\"/>\\n                            </t>\\n                        </div>\\n                    </div>\\n\\n                    <t t-call=\\"website_sale.o_wsale_offcanvas\\"/>\\n                </div>\\n                <div class=\\"oe_structure oe_empty oe_structure_not_nearest\\" id=\\"oe_structure_website_sale_products_2\\"/>\\n            </div>\\n            <div t-if=\\"is_view_active('website_sale.search')\\" id=\\"o_wsale_search_modal\\" class=\\"modal fade css_editable_mode_hidden\\" aria-hidden=\\"true\\" tabindex=\\"-1\\">\\n                <div class=\\"modal-dialog modal-lg pt-5\\">\\n                    <div class=\\"modal-content mt-5 bg-transparent border-0\\">\\n                        <div class=\\"o_container_small\\">\\n                            <t t-call=\\"website.website_search_box_input\\">\\n                                <t t-set=\\"default_style\\" t-valuef=\\"true\\"/>\\n                                <t t-set=\\"search_type\\" t-valuef=\\"products\\"/>\\n                                <t t-set=\\"_classes\\" t-valuef=\\"input-group rounded o_cc o_cc1 mb-1\\"/>\\n                                <t t-set=\\"_input_classes\\" t-valuef=\\"border-0 p-3\\"/>\\n                                <t t-set=\\"_submit_classes\\" t-valuef=\\"px-4\\"/>\\n                                <t t-set=\\"search_term\\">Search in</t>\\n                                <t t-if=\\"category\\" t-set=\\"placeholder\\" t-valuef=\\"{{ search_term }} {{ category.name }}\\"/>\\n                            </t>\\n                        </div>\\n                    </div>\\n                </div>\\n            </div>\\n        </t>\\n    </t>", "es_ES": "<t name=\\"Products\\" t-name=\\"website_sale.products\\">\\n        <t t-call=\\"website.layout\\">\\n            <t t-set=\\"additional_title\\" t-value=\\"category.name\\"/>\\n            <t t-set=\\"grid_block_name\\">Cuadrícula</t>\\n            <t t-set=\\"product_block_name\\">Producto</t>\\n\\n            <!-- Qweb variable defining the class suffix for navbar items.\\n                 Change accordingly to the derired visual result (eg. `primary`, `dark`...)-->\\n            <t t-set=\\"navClass\\" t-valuef=\\"light\\"/>\\n\\n            <!-- Check for active options: the stored value may be used in sub-templates too  -->\\n            <t t-set=\\"opt_wsale_fullwidth\\" t-value=\\"website.shop_page_container == 'fluid'\\"/>\\n            <t t-set=\\"opt_wsale_categories\\" t-value=\\"is_view_active('website_sale.products_categories')\\"/>\\n            <t t-set=\\"opt_wsale_attributes\\" t-value=\\"is_view_active('website_sale.products_attributes')\\"/>\\n            <t t-set=\\"opt_wsale_filter_price\\" t-value=\\"is_view_active('website_sale.filter_products_price')\\"/>\\n            <t t-set=\\"opt_wsale_filter_tags\\" t-value=\\"is_view_active('website_sale.filter_products_tags')\\"/>\\n            <t t-set=\\"opt_wsale_design_grid\\" t-value=\\"'o_wsale_products_opt_design_grid' in website.shop_opt_products_design_classes\\"/>\\n\\n            <t t-set=\\"opt_wsale_categories_top\\" t-value=\\"is_view_active('website_sale.products_categories_top')\\"/>\\n            <t t-set=\\"opt_wsale_attributes_top\\" t-value=\\"is_view_active('website_sale.products_attributes_top')\\"/>\\n            <t t-set=\\"opt_wsale_floating_bar\\" t-value=\\"is_view_active('website_sale.floating_bar')\\"/>\\n\\n            <t t-set=\\"opt_wsale_show_shop_title\\" t-value=\\"is_view_active('website_sale.products_shop_title')\\"/>\\n            <t t-set=\\"opt_wsale_shop_title_align\\" t-value=\\"is_view_active('website_sale.products_shop_title_align')\\"/>\\n\\n            <t t-set=\\"opt_wsale_show_category_title\\" t-value=\\"bool(category) and category.show_category_title\\"/>\\n            <t t-set=\\"opt_wsale_show_category_description\\" t-value=\\"bool(category) and category.show_category_description\\"/>\\n            <t t-set=\\"opt_wsale_category_align\\" t-value=\\"bool(category) and category.align_category_content\\"/>\\n\\n            <t t-set=\\"website_sale_pricelists\\" t-value=\\"website.get_pricelist_available(show_visible=True)\\"/>\\n            <t t-set=\\"website_sale_sortable\\" t-value=\\"website._get_product_sort_mapping()\\"/>\\n\\n            <t t-set=\\"hasLeftColumn\\" t-value=\\"opt_wsale_categories or opt_wsale_attributes\\"/>\\n\\n            <t t-set=\\"isFilteringByPrice\\" t-if=\\"opt_wsale_filter_price\\" t-value=\\"float_round(available_min_price, 2) != float_round(min_price, 2) or float_round(available_max_price, 2) != float_round(max_price, 2)\\"/>\\n            <t t-set=\\"hasPricelistDropdown\\" t-value=\\"website_sale_pricelists and len(website_sale_pricelists)&gt;1\\"/>\\n            <t t-set=\\"isSortingBy\\" t-value=\\"[sort for sort in website_sale_sortable if sort[0]==request.params.get('order', '')]\\"/>\\n\\n            <t t-set=\\"wsale_has_filters_btn\\" t-value=\\"opt_wsale_categories or opt_wsale_attributes or opt_wsale_attributes_top\\"/>\\n            <t t-set=\\"wsale_has_filters_btn_lg\\" t-value=\\"opt_wsale_attributes_top\\"/>\\n\\n            <div id=\\"wrap\\" class=\\"js_sale o_wsale_products_page\\">\\n                <div class=\\"oe_structure oe_empty oe_structure_not_nearest\\" id=\\"oe_structure_website_sale_products_1\\"/>\\n                <div id=\\"o_wsale_container\\" t-attf-class=\\"oe_website_sale                         {{opt_wsale_fullwidth and 'container-fluid o_wsale_page_fluid' or 'o_wsale_page_contained container'}}                         {{opt_wsale_categories_top and 'o_wsale_has_filmstrip'}}                         {{opt_wsale_floating_bar and 'o_wsale_has_floating_bar'}}                         {{hasLeftColumn and 'o_wsale_has_sidebar'}}                         {{editionPreviews and 'o_wsale_edit_preview_enabled'}}                         {{opt_wsale_design_grid and 'o_wsale_uses_grid_design'}}\\" t-att-data-ppg=\\"ppg\\" t-att-data-ppr=\\"ppr\\" t-att-data-default-sort=\\"website.shop_default_sort\\">\\n                    <div class=\\"row o_wsale_products_main_row flex-nowrap\\">\\n                        <aside t-if=\\"hasLeftColumn\\" id=\\"products_grid_before\\" class=\\"d-none d-lg-block position-sticky align-self-start col clearfix pt-2\\">\\n                            <t t-call=\\"website_sale.sidebar_dropzone_at_top\\"/>\\n                            <div class=\\"o_wsale_products_grid_before_rail vh-100 ms-n2 px-lg-2 ps-2 overflow-y-scroll\\">\\n                                <t t-set=\\"is_sidebar_collapsible\\" t-value=\\"is_view_active('website_sale.products_categories_list_collapsible')\\"/>\\n                                <div t-if=\\"opt_wsale_categories\\" t-att-class=\\"'products_categories'                                                 + (' accordion accordion-flush' if is_sidebar_collapsible else ' mb-3')\\">\\n                                    <t t-call=\\"website_sale.products_categories_list\\"/>\\n                                </div>\\n                                <t t-set=\\"show_price_filter\\" t-value=\\"opt_wsale_filter_price and opt_wsale_attributes\\"/>\\n                                <div t-if=\\"attrib_values or tags or (                                         show_price_filter and isFilteringByPrice                                     )\\" class=\\"py-3 border-bottom\\">\\n                                    <a t-att-href=\\"keep(attribute_values=0, tags=0, min_price=0, max_price=0)\\" t-attf-class=\\"btn btn-{{navClass}} d-flex align-items-center py-1\\" title=\\"Eliminar filtros\\">\\n                                        <small class=\\"mx-auto\\"><b>Borrar filtros</b></small>\\n                                        <i class=\\"oi oi-close\\" role=\\"presentation\\"/>\\n                                    </a>\\n                                </div>\\n                                <div t-attf-class=\\"products_attributes_filters d-empty-none {{opt_wsale_categories and 'border-top'}} {{'pt-3' if not is_sidebar_collapsible else ''}}\\"/>\\n                                <t t-if=\\"show_price_filter\\" t-call=\\"website_sale.filter_products_price\\">\\n                                    <t t-set=\\"_classes\\" t-valuef=\\"{{is_sidebar_collapsible and 'accordion accordion-flush'}} {{is_sidebar_collapsible and (opt_wsale_categories or len(attributes) &gt; 0) and 'border-top'}}\\"/>\\n                                </t>\\n                                <t t-call=\\"website_sale.sidebar_dropzone_at_bottom\\"/>\\n                            </div>\\n                        </aside>\\n                        <div id=\\"products_grid\\" class=\\"col\\">\\n                            <t t-set=\\"_header_has_content\\" t-value=\\"category or opt_wsale_categories_top or (not opt_wsale_floating_bar and (opt_wsale_attributes_top or is_view_active('website_sale.search') or is_view_active('website_sale.sort') or hasPricelistDropdown))\\"/>\\n\\n                            <header id=\\"o_wsale_products_header\\" t-att-data-category-id=\\"category.id\\" t-att-data-category-name=\\"category.name\\" t-attf-class=\\"d-flex flex-column gap-2                                     {{_header_has_content and 'pt-4 pb-3' or opt_wsale_design_grid and 'py-3'}}                                     {{category and 'o_wsale_products_header_is_category' or 'o_wsale_products_header_is_shop'}}                                     {{opt_wsale_show_category_title and 'o_wsale_products_header_show_category_title'}}                                     {{opt_wsale_show_category_description and 'o_wsale_products_header_show_category_description'}}                                     {{opt_wsale_category_align and 'o_wsale_products_header_category_center_content'}}                                     {{opt_wsale_show_shop_title and 'o_wsale_products_header_show_shop_title'}}                                     {{opt_wsale_shop_title_align and 'o_wsale_products_header_shop_center_content'}}\\">\\n                                <t t-if=\\"category and not search\\" t-call=\\"website_sale.products_breadcrumb\\">\\n                                    <t t-set=\\"_classes\\" t-valuef=\\"w-100 p-0 mb-0 small {{not opt_wsale_show_category_title and 'mb-2 mb-lg-0'}}\\"/>\\n                                </t>\\n                                <h1 t-if=\\"category or search\\" t-attf-class=\\"o_wsale_category_title d-flex gap-1 align-items-center mb-0 lh-lg {{search and bool(category) and 'mb-2'}} {{search and 'o_wsale_category_title_is_search base-fs font-sans-serif' or 'fs-3'}}\\">\\n                                    <t t-if=\\"search and category\\">\\n                                        <span class=\\"text-muted\\">Buscando</span>\\n                                        <span class=\\"badge text-bg-info fw-normal base-fs\\">\\n                                            <t t-out=\\"search\\"/>\\n                                            <a title=\\"Borrar la búsqueda de esta categoría\\" t-att-href=\\"keep(search=0)\\" class=\\"link-info\\">\\n                                                <i class=\\"oi oi-close\\" role=\\"img\\"/>\\n                                            </a>\\n                                        </span>\\n                                        <span class=\\"text-muted\\">en</span>\\n                                        <span class=\\"badge text-bg-primary fw-normal base-fs\\">\\n                                            <t t-out=\\"category.name\\"/>\\n                                            <a title=\\"Buscar de forma general\\" t-att-href=\\"keep(shop_path, search=search)\\">\\n                                                <i class=\\"oi oi-close\\" role=\\"img\\"/>\\n                                            </a>\\n                                        </span>\\n                                    </t>\\n                                    <span t-elif=\\"search\\">\\n                                        <span class=\\"text-muted\\">Resultados de búsqueda de </span>'<strong t-out=\\"search\\"/>' <small t-if=\\"search_count\\" class=\\"text-muted\\"> (<t t-out=\\"search_count\\"/>)</small>\\n                                    </span>\\n                                    <t t-elif=\\"category\\">\\n                                        <span t-field=\\"category.name\\"/>\\n                                    </t>\\n                                </h1>\\n                                <h1 class=\\"o_wsale_shop_title h4-fs\\" t-if=\\"not category and not search\\">\\n                                    Todos los productos\\n                                </h1>\\n                                <t t-if=\\"category\\">\\n                                    <t t-set=\\"editor_msg\\">\\n                                        Arrastra los bloques de creación aquí para personalizar el encabezado para\\n                                        \\"<t t-out=\\"category.name\\"/>\\" como categoría.\\n                                    </t>\\n                                    <div id=\\"category_header\\" class=\\"o_wsale_category_description\\" t-att-data-editor-message=\\"editor_msg\\" t-field=\\"category.website_description\\"/>\\n                                </t>\\n                                <t t-else=\\"\\">\\n                                    <t t-set=\\"editor_msg\\">\\n                                        Arrastra los bloques de creación aquí para personalizar el encabezado de la página de la tienda.\\n                                    </t>\\n                                    <div id=\\"oe_structure_products_header_shop\\" class=\\"oe_structure oe_empty\\" t-att-data-editor-message=\\"editor_msg\\"/>\\n                                </t>\\n                                <t t-if=\\"opt_wsale_categories_top and category_entries\\" t-call=\\"website_sale.filmstrip_categories\\" entries=\\"category_entries\\"/>\\n                                <div t-if=\\"not opt_wsale_floating_bar\\" class=\\"products_header btn-toolbar flex-nowrap align-items-center justify-content-between gap-1 gap-lg-2 gap-xl-3\\">\\n                                    <t t-if=\\"is_view_active('website_sale.search')\\">\\n                                        <t t-set=\\"_has_all_sibligns\\" t-value=\\"hasPricelistDropdown and is_view_active('website_sale.sort') and wsale_has_filters_btn\\"/>\\n                                        <!-- Desktop Search button -->\\n                                        <div t-attf-class=\\"o_wsale_products_header_search_form_container {{ _has_all_sibligns and 'd-none d-sm-inline-block'}} col-xl-5 me-auto {{not hasLeftColumn and 'col-xl-6'}}\\">\\n                                            <t t-set=\\"search_term\\">Buscar en</t>\\n                                            <t t-if=\\"category\\" t-set=\\"placeholder\\" t-valuef=\\"{{ search_term }} {{ category.name }}\\"/>\\n                                            <t t-call=\\"website_sale.search\\" placeholder=\\"placeholder\\" search=\\"original_search or search\\"/>\\n                                        </div>\\n                                        <!-- Mobile Search button -->\\n                                        <a t-attf-class=\\"btn o_not_editable {{_has_all_sibligns and 'd-inline-block d-sm-none' or 'd-none'}} me-auto btn-{{navClass}}\\" data-bs-target=\\"#o_wsale_search_modal\\" data-bs-toggle=\\"modal\\" role=\\"button\\" title=\\"Buscar productos\\" href=\\"#\\">\\n                                            <i class=\\"oi oi-search\\" role=\\"img\\"/>\\n                                        </a>\\n                                    </t>\\n                                    <t t-if=\\"hasPricelistDropdown\\" t-call=\\"website_sale.pricelist_list\\"/>\\n                                    <t t-if=\\"is_view_active('website_sale.sort')\\" t-call=\\"website_sale.sort\\"/>\\n                                    <button t-if=\\"wsale_has_filters_btn\\" t-attf-class=\\"btn btn-{{navClass}} position-relative {{not wsale_has_filters_btn_lg and 'd-lg-none'}} {{not is_view_active('website_sale.search') and 'ms-auto'}} text-nowrap\\" title=\\"Filtros\\" data-bs-toggle=\\"offcanvas\\" data-bs-target=\\"#o_wsale_offcanvas\\">\\n                                        <i class=\\"oi oi-settings-adjust\\" role=\\"img\\"/>\\n                                        <small t-attf-class=\\"ms-1 {{(hasPricelistDropdown and is_view_active('website_sale.search') and is_view_active('website_sale.sort')) and 'd-none d-md-inline-block'}}\\">Filtros</small>\\n                                        <span t-if=\\"isFilteringByPrice or attrib_set or tags\\" t-attf-class=\\"position-absolute top-0 start-100 translate-middle border border-{{navClass}} rounded-circle bg-danger p-1\\">\\n                                            <span class=\\"visually-hidden\\">filtros activos</span>\\n                                        </span>\\n                                    </button>\\n                                </div>\\n                                <div t-if=\\"original_search and products\\" class=\\"alert alert-warning mt8\\">\\n                                    No se han encontrado resultados para \\"<span t-out=\\"original_search\\"/>\\". Mostrando resultados para \\"<span t-out=\\"search\\"/>'.\\n                                </div>\\n                            </header>\\n\\n                            <div t-if=\\"products\\" class=\\"o_wsale_products_grid_table_wrapper\\">\\n                                <t t-set=\\"grid_md_allow_custom_cols\\" t-value=\\"hasLeftColumn\\"/>\\n                                <t t-set=\\"grid_md_use_3col\\" t-value=\\"(not hasLeftColumn and ppr == 4) or (opt_wsale_fullwidth and ppr &gt; 3)\\"/>\\n\\n                                <section id=\\"o_wsale_products_grid\\" t-attf-class=\\"o_wsale_products_grid_table grid                                         {{grid_md_allow_custom_cols and 'o_wsale_products_grid_table_md'}}                                         {{website.shop_opt_products_design_classes}}\\" t-attf-style=\\"--o-wsale-ppr: {{ppr}}; --o-wsale-ppg: {{ppg}}; --o-wsale-products-grid-gap: {{gap}};\\" t-att-data-name=\\"grid_block_name\\">\\n                                    <t t-foreach=\\"bins\\" t-as=\\"tr_product\\">\\n                                        <t t-foreach=\\"tr_product\\" t-as=\\"td_product\\">\\n                                            <t t-if=\\"td_product\\">\\n                                                <t t-set=\\"col_height\\" t-value=\\"td_product['y']\\"/>\\n                                                <t t-set=\\"col_width\\" t-value=\\"12 // ppr * td_product['x']\\"/>\\n                                                <t t-set=\\"col_class\\" t-valuef=\\"g-col-6\\"/>\\n                                                <t t-set=\\"col_class_lg\\" t-value=\\"'g-col-lg-' + str(col_width)\\"/>\\n                                                <t t-set=\\"col_class_md\\" t-value=\\"grid_md_allow_custom_cols and ('g-col-md-' + str(col_width)) or grid_md_use_3col and 'g-col-md-4' or 'g-col-md-6'\\"/>\\n                                                <t t-set=\\"col_is_stretched\\" t-value=\\"(td_product['x'] &gt;= td_product['y'] * 2)\\"/>\\n                                                <t t-set=\\"col_is_custom_portrait\\" t-value=\\"not col_is_stretched and (col_height &gt; td_product['x'])\\"/>\\n                                                <t t-set=\\"product\\" t-value=\\"td_product['product']\\"/>\\n                                                <t t-set=\\"template_price_vals\\" t-value=\\"get_product_prices(product)\\"/>\\n                                                <t t-set=\\"ribbon\\" t-value=\\"product._get_ribbon(                                                         price_vals=template_price_vals,                                                         auto_assign_ribbons=auto_assign_ribbons,                                                         variant=product_variants[product],                                                     )\\"/>\\n                                                <div t-attf-class=\\"oe_product {{col_is_custom_portrait and 'oe_product_custom_portrait'}} {{col_class}} {{col_class_md}} {{col_class_lg}} {{col_is_stretched and 'oe_product_size_stretch'}}\\" t-attf-style=\\"--o-wsale-products-grid-product-col-height: {{col_height}};\\" t-att-data-colspan=\\"td_product['x'] != 1 and td_product['x']\\" t-att-data-rowspan=\\"td_product['y'] != 1 and td_product['y']\\" t-att-data-name=\\"product_block_name\\">\\n                                                    <div t-attf-class=\\"o_wsale_product_grid_wrapper position-relative h-100 o_wsale_product_grid_wrapper_#{td_product['x']}_#{td_product['y']}\\">\\n                                                        <t t-call=\\"website_sale.products_item\\">\\n                                                            <t t-set=\\"design_field\\" t-value=\\"website.shop_opt_products_design_classes\\"/>\\n                                                            <t t-set=\\"product_href\\" t-value=\\"product._get_product_url(category, product_query_params, grouped_attributes_values)\\"/>\\n                                                        </t>\\n                                                    </div>\\n                                                </div>\\n                                            </t>\\n                                        </t>\\n                                    </t>\\n                                </section>\\n                            </div>\\n                            <div t-else=\\"\\" class=\\"text-center text-muted mt128 mb256\\">\\n                                <t t-if=\\"not search\\">\\n                                    <div class=\\"mt-5 mb-3\\"><t t-call=\\"website.empty_search_svg\\"/></div>\\n                                    <h3 class=\\"mt8\\" style=\\"text-align: center;\\">\\n                                        Ningún producto definido\\n                                    </h3>\\n                                    <p t-if=\\"category\\" style=\\"text-align: center;\\">\\n                                        No hay productos definidos en esta categoría.\\n                                    </p>\\n                                </t>\\n                                <t t-else=\\"\\">\\n                                    <div class=\\"mt-5 mb-3\\"><t t-call=\\"website.empty_search_svg\\"/></div>\\n                                    <h3 class=\\"mt8\\" style=\\"text-align: center;\\">No hay resultados</h3>\\n                                    <p style=\\"text-align: center;\\">\\n                                        No hay resultados para \\"<strong t-out=\\"search\\"/>\\"<t t-if=\\"category\\"> en la categoría \\"<strong t-out=\\"category.display_name\\"/>\\"</t>.\\n                                    </p>\\n                                    <p style=\\"text-align: center;\\">\\n                                        <a t-if=\\"category\\" t-att-href=\\"keep(shop_path, search=search)\\" t-attf-title=\\"Buscar {{search}} de forma general\\" class=\\"d-block pb-5\\">\\n                                            Buscar de forma general\\n                                        </a>\\n                                    </p>\\n                                </t>\\n                                <div t-ignore=\\"true\\" groups=\\"sales_team.group_sale_manager\\" class=\\"alert alert-info d-inline-block mx-auto text-center\\">\\n                                    Haz clic en <i>«Nuevo»</i> en la esquina superior derecha para crear tu primer producto.\\n                                </div>\\n                            </div>\\n                            <div id=\\"o_wsale_pager\\" t-attf-class=\\"products_pager d-flex justify-content-center {{opt_wsale_design_grid and 'py-4' or 'py-5 pb-4'}}\\">\\n                                <t t-call=\\"website.pager\\"/>\\n                            </div>\\n                            <t t-if=\\"category\\">\\n                                <t t-set=\\"footer_editor_message\\">\\n                                    Arrastra bloques de creación aquí para personalizar el pie de página para\\n                                    \\"<t t-out=\\"category.name\\"/>\\" como categoría.\\n                                </t>\\n                                <div class=\\"mb16\\" id=\\"category_footer\\" t-att-data-editor-message=\\"footer_editor_message\\" t-field=\\"category.website_footer\\"/>\\n                            </t>\\n                        </div>\\n                    </div>\\n\\n                    <t t-call=\\"website_sale.o_wsale_offcanvas\\"/>\\n                </div>\\n                <div class=\\"oe_structure oe_empty oe_structure_not_nearest\\" id=\\"oe_structure_website_sale_products_2\\"/>\\n            </div>\\n            <div t-if=\\"is_view_active('website_sale.search')\\" id=\\"o_wsale_search_modal\\" class=\\"modal fade css_editable_mode_hidden\\" aria-hidden=\\"true\\" tabindex=\\"-1\\">\\n                <div class=\\"modal-dialog modal-lg pt-5\\">\\n                    <div class=\\"modal-content mt-5 bg-transparent border-0\\">\\n                        <div class=\\"o_container_small\\">\\n                            <t t-call=\\"website.website_search_box_input\\">\\n                                <t t-set=\\"default_style\\" t-valuef=\\"true\\"/>\\n                                <t t-set=\\"search_type\\" t-valuef=\\"products\\"/>\\n                                <t t-set=\\"_classes\\" t-valuef=\\"input-group rounded o_cc o_cc1 mb-1\\"/>\\n                                <t t-set=\\"_input_classes\\" t-valuef=\\"border-0 p-3\\"/>\\n                                <t t-set=\\"_submit_classes\\" t-valuef=\\"px-4\\"/>\\n                                <t t-set=\\"search_term\\">Buscar en</t>\\n                                <t t-if=\\"category\\" t-set=\\"placeholder\\" t-valuef=\\"{{ search_term }} {{ category.name }}\\"/>\\n                            </t>\\n                        </div>\\n                    </div>\\n                </div>\\n            </div>\\n        </t>\\n    </t>"}	<?xml version="1.0"?>\n<t name="Products" t-name="website_sale.products">\n        <t t-call="website.layout">\n            <t t-set="additional_title" t-value="category.name"/>\n            <t t-set="grid_block_name">Grid</t>\n            <t t-set="product_block_name">Product</t>\n\n            <!-- Qweb variable defining the class suffix for navbar items.\n                 Change accordingly to the derired visual result (eg. `primary`, `dark`...)-->\n            <t t-set="navClass" t-valuef="light"/>\n\n            <!-- Check for active options: the stored value may be used in sub-templates too  -->\n            <t t-set="opt_wsale_fullwidth" t-value="website.shop_page_container == 'fluid'"/>\n            <t t-set="opt_wsale_categories" t-value="is_view_active('website_sale.products_categories')"/>\n            <t t-set="opt_wsale_attributes" t-value="is_view_active('website_sale.products_attributes')"/>\n            <t t-set="opt_wsale_filter_price" t-value="is_view_active('website_sale.filter_products_price')"/>\n            <t t-set="opt_wsale_filter_tags" t-value="is_view_active('website_sale.filter_products_tags')"/>\n            <t t-set="opt_wsale_design_grid" t-value="'o_wsale_products_opt_design_grid' in website.shop_opt_products_design_classes"/>\n\n            <t t-set="opt_wsale_categories_top" t-value="is_view_active('website_sale.products_categories_top')"/>\n            <t t-set="opt_wsale_attributes_top" t-value="is_view_active('website_sale.products_attributes_top')"/>\n            <t t-set="opt_wsale_floating_bar" t-value="is_view_active('website_sale.floating_bar')"/>\n\n            <t t-set="opt_wsale_show_shop_title" t-value="is_view_active('website_sale.products_shop_title')"/>\n            <t t-set="opt_wsale_shop_title_align" t-value="is_view_active('website_sale.products_shop_title_align')"/>\n\n            <t t-set="opt_wsale_show_category_title" t-value="bool(category) and category.show_category_title"/>\n            <t t-set="opt_wsale_show_category_description" t-value="bool(category) and category.show_category_description"/>\n            <t t-set="opt_wsale_category_align" t-value="bool(category) and category.align_category_content"/>\n\n            <t t-set="website_sale_pricelists" t-value="website.get_pricelist_available(show_visible=True)"/>\n            <t t-set="website_sale_sortable" t-value="website._get_product_sort_mapping()"/>\n\n            <t t-set="hasLeftColumn" t-value="opt_wsale_categories or opt_wsale_attributes"/>\n\n            <t t-set="isFilteringByPrice" t-if="opt_wsale_filter_price" t-value="float_round(available_min_price, 2) != float_round(min_price, 2) or float_round(available_max_price, 2) != float_round(max_price, 2)"/>\n            <t t-set="hasPricelistDropdown" t-value="website_sale_pricelists and len(website_sale_pricelists)&gt;1"/>\n            <t t-set="isSortingBy" t-value="[sort for sort in website_sale_sortable if sort[0]==request.params.get('order', '')]"/>\n\n            <t t-set="wsale_has_filters_btn" t-value="opt_wsale_categories or opt_wsale_attributes or opt_wsale_attributes_top"/>\n            <t t-set="wsale_has_filters_btn_lg" t-value="opt_wsale_attributes_top"/>\n\n            <div id="wrap" class="js_sale o_wsale_products_page">\n                <div class="oe_structure oe_empty oe_structure_not_nearest" id="oe_structure_website_sale_products_1"/>\n                <div id="o_wsale_container" t-attf-class="oe_website_sale                         {{opt_wsale_fullwidth and 'container-fluid o_wsale_page_fluid' or 'o_wsale_page_contained container'}}                         {{opt_wsale_categories_top and 'o_wsale_has_filmstrip'}}                         {{opt_wsale_floating_bar and 'o_wsale_has_floating_bar'}}                         {{hasLeftColumn and 'o_wsale_has_sidebar'}}                         {{editionPreviews and 'o_wsale_edit_preview_enabled'}}                         {{opt_wsale_design_grid and 'o_wsale_uses_grid_design'}}" t-att-data-ppg="ppg" t-att-data-ppr="ppr" t-att-data-default-sort="website.shop_default_sort">\n                    <div class="row o_wsale_products_main_row flex-nowrap">\n                        <aside t-if="hasLeftColumn" id="products_grid_before" class="d-none d-lg-block position-sticky align-self-start col clearfix pt-2">\n                            <t t-call="website_sale.sidebar_dropzone_at_top"/>\n                            <div class="o_wsale_products_grid_before_rail vh-100 ms-n2 px-lg-2 ps-2 overflow-y-scroll">\n                                <t t-set="is_sidebar_collapsible" t-value="is_view_active('website_sale.products_categories_list_collapsible')"/>\n                                <div t-if="opt_wsale_categories" t-att-class="'products_categories'                                                 + (' accordion accordion-flush' if is_sidebar_collapsible else ' mb-3')">\n                                    <t t-call="website_sale.products_categories_list"/>\n                                </div>\n                                <t t-set="show_price_filter" t-value="opt_wsale_filter_price and opt_wsale_attributes"/>\n                                <div t-if="attrib_values or tags or (                                         show_price_filter and isFilteringByPrice                                     )" class="py-3 border-bottom">\n                                    <a t-att-href="keep(attribute_values=0, tags=0, min_price=0, max_price=0)" t-attf-class="btn btn-{{navClass}} d-flex align-items-center py-1" title="Clear Filters">\n                                        <small class="mx-auto"><b>Clear Filters</b></small>\n                                        <i class="oi oi-close" role="presentation"/>\n                                    </a>\n                                </div>\n                                <div t-attf-class="products_attributes_filters d-empty-none {{opt_wsale_categories and 'border-top'}} {{'pt-3' if not is_sidebar_collapsible else ''}}"/>\n                                <t t-if="show_price_filter" t-call="website_sale.filter_products_price">\n                                    <t t-set="_classes" t-valuef="{{is_sidebar_collapsible and 'accordion accordion-flush'}} {{is_sidebar_collapsible and (opt_wsale_categories or len(attributes) &gt; 0) and 'border-top'}}"/>\n                                </t>\n                                <t t-call="website_sale.sidebar_dropzone_at_bottom"/>\n                            </div>\n                        </aside>\n                        <div id="products_grid" class="col">\n                            <t t-set="_header_has_content" t-value="category or opt_wsale_categories_top or (not opt_wsale_floating_bar and (opt_wsale_attributes_top or is_view_active('website_sale.search') or is_view_active('website_sale.sort') or hasPricelistDropdown))"/>\n\n                            <header id="o_wsale_products_header" t-att-data-category-id="category.id" t-att-data-category-name="category.name" t-attf-class="d-flex flex-column gap-2                                     {{_header_has_content and 'pt-4 pb-3' or opt_wsale_design_grid and 'py-3'}}                                     {{category and 'o_wsale_products_header_is_category' or 'o_wsale_products_header_is_shop'}}                                     {{opt_wsale_show_category_title and 'o_wsale_products_header_show_category_title'}}                                     {{opt_wsale_show_category_description and 'o_wsale_products_header_show_category_description'}}                                     {{opt_wsale_category_align and 'o_wsale_products_header_category_center_content'}}                                     {{opt_wsale_show_shop_title and 'o_wsale_products_header_show_shop_title'}}                                     {{opt_wsale_shop_title_align and 'o_wsale_products_header_shop_center_content'}}">\n                                <t t-if="category and not search" t-call="website_sale.products_breadcrumb">\n                                    <t t-set="_classes" t-valuef="w-100 p-0 mb-0 small {{not opt_wsale_show_category_title and 'mb-2 mb-lg-0'}}"/>\n                                </t>\n                                <h1 t-if="category or search" t-attf-class="o_wsale_category_title d-flex gap-1 align-items-center mb-0 lh-lg {{search and bool(category) and 'mb-2'}} {{search and 'o_wsale_category_title_is_search base-fs font-sans-serif' or 'fs-3'}}">\n                                    <t t-if="search and category">\n                                        <span class="text-muted">Searching</span>\n                                        <span class="badge text-bg-info fw-normal base-fs">\n                                            <t t-out="search"/>\n                                            <a title="Clear search for this category" t-att-href="keep(search=0)" class="link-info">\n                                                <i class="oi oi-close" role="img"/>\n                                            </a>\n                                        </span>\n                                        <span class="text-muted">in</span>\n                                        <span class="badge text-bg-primary fw-normal base-fs">\n                                            <t t-out="category.name"/>\n                                            <a title="Search globally" t-att-href="keep(shop_path, search=search)">\n                                                <i class="oi oi-close" role="img"/>\n                                            </a>\n                                        </span>\n                                    </t>\n                                    <span t-elif="search">\n                                        <span class="text-muted">Search results for </span>'<strong t-out="search"/>' <small t-if="search_count" class="text-muted"> (<t t-out="search_count"/>)</small>\n                                    </span>\n                                    <t t-elif="category">\n                                        <span t-field="category.name"/>\n                                    </t>\n                                </h1>\n                                <h1 class="o_wsale_shop_title h4-fs" t-if="not category and not search">\n                                    All products\n                                </h1>\n                                <t t-if="category">\n                                    <t t-set="editor_msg">\n                                        Drag building blocks here to customize the header for\n                                        "<t t-out="category.name"/>" category.\n                                    </t>\n                                    <div id="category_header" class="o_wsale_category_description" t-att-data-editor-message="editor_msg" t-field="category.website_description"/>\n                                </t>\n                                <t t-else="">\n                                    <t t-set="editor_msg">\n                                        Drag building blocks here to customize the header for the shop page.\n                                    </t>\n                                    <div id="oe_structure_products_header_shop" class="oe_structure oe_empty" t-att-data-editor-message="editor_msg"/>\n                                </t>\n                                <t t-if="opt_wsale_categories_top and category_entries" t-call="website_sale.filmstrip_categories" entries="category_entries"/>\n                                <div t-if="not opt_wsale_floating_bar" class="products_header btn-toolbar flex-nowrap align-items-center justify-content-between gap-1 gap-lg-2 gap-xl-3">\n                                    <t t-if="is_view_active('website_sale.search')">\n                                        <t t-set="_has_all_sibligns" t-value="hasPricelistDropdown and is_view_active('website_sale.sort') and wsale_has_filters_btn"/>\n                                        <!-- Desktop Search button -->\n                                        <div t-attf-class="o_wsale_products_header_search_form_container {{ _has_all_sibligns and 'd-none d-sm-inline-block'}} col-xl-5 me-auto {{not hasLeftColumn and 'col-xl-6'}}">\n                                            <t t-set="search_term">Search in</t>\n                                            <t t-if="category" t-set="placeholder" t-valuef="{{ search_term }} {{ category.name }}"/>\n                                            <t t-call="website_sale.search" placeholder="placeholder" search="original_search or search"/>\n                                        </div>\n                                        <!-- Mobile Search button -->\n                                        <a t-attf-class="btn o_not_editable {{_has_all_sibligns and 'd-inline-block d-sm-none' or 'd-none'}} me-auto btn-{{navClass}}" data-bs-target="#o_wsale_search_modal" data-bs-toggle="modal" role="button" title="Search Products" href="#">\n                                            <i class="oi oi-search" role="img"/>\n                                        </a>\n                                    </t>\n                                    <t t-if="hasPricelistDropdown" t-call="website_sale.pricelist_list"/>\n                                    <t t-if="is_view_active('website_sale.sort')" t-call="website_sale.sort"/>\n                                    <button t-if="wsale_has_filters_btn" t-attf-class="btn btn-{{navClass}} position-relative {{not wsale_has_filters_btn_lg and 'd-lg-none'}} {{not is_view_active('website_sale.search') and 'ms-auto'}} text-nowrap" title="Filters" data-bs-toggle="offcanvas" data-bs-target="#o_wsale_offcanvas">\n                                        <i class="oi oi-settings-adjust" role="img"/>\n                                        <small t-attf-class="ms-1 {{(hasPricelistDropdown and is_view_active('website_sale.search') and is_view_active('website_sale.sort')) and 'd-none d-md-inline-block'}}">Filters</small>\n                                        <span t-if="isFilteringByPrice or attrib_set or tags" t-attf-class="position-absolute top-0 start-100 translate-middle border border-{{navClass}} rounded-circle bg-danger p-1">\n                                            <span class="visually-hidden">filters active</span>\n                                        </span>\n                                    </button>\n                                </div>\n                                <div t-if="original_search and products" class="alert alert-warning mt8">\n                                    No results found for '<span t-out="original_search"/>'. Showing results for '<span t-out="search"/>'.\n                                </div>\n                            </header>\n\n                            <div t-if="products" class="o_wsale_products_grid_table_wrapper">\n                                <t t-set="grid_md_allow_custom_cols" t-value="hasLeftColumn"/>\n                                <t t-set="grid_md_use_3col" t-value="(not hasLeftColumn and ppr == 4) or (opt_wsale_fullwidth and ppr &gt; 3)"/>\n\n                                <section id="o_wsale_products_grid" t-attf-class="o_wsale_products_grid_table grid                                         {{grid_md_allow_custom_cols and 'o_wsale_products_grid_table_md'}}                                         {{website.shop_opt_products_design_classes}}" t-attf-style="--o-wsale-ppr: {{ppr}}; --o-wsale-ppg: {{ppg}}; --o-wsale-products-grid-gap: {{gap}};" t-att-data-name="grid_block_name">\n                                    <t t-foreach="bins" t-as="tr_product">\n                                        <t t-foreach="tr_product" t-as="td_product">\n                                            <t t-if="td_product">\n                                                <t t-set="col_height" t-value="td_product['y']"/>\n                                                <t t-set="col_width" t-value="12 // ppr * td_product['x']"/>\n                                                <t t-set="col_class" t-valuef="g-col-6"/>\n                                                <t t-set="col_class_lg" t-value="'g-col-lg-' + str(col_width)"/>\n                                                <t t-set="col_class_md" t-value="grid_md_allow_custom_cols and ('g-col-md-' + str(col_width)) or grid_md_use_3col and 'g-col-md-4' or 'g-col-md-6'"/>\n                                                <t t-set="col_is_stretched" t-value="(td_product['x'] &gt;= td_product['y'] * 2)"/>\n                                                <t t-set="col_is_custom_portrait" t-value="not col_is_stretched and (col_height &gt; td_product['x'])"/>\n                                                <t t-set="product" t-value="td_product['product']"/>\n                                                <t t-set="template_price_vals" t-value="get_product_prices(product)"/>\n                                                <t t-set="ribbon" t-value="product._get_ribbon(                                                         price_vals=template_price_vals,                                                         auto_assign_ribbons=auto_assign_ribbons,                                                         variant=product_variants[product],                                                     )"/>\n                                                <div t-attf-class="oe_product {{col_is_custom_portrait and 'oe_product_custom_portrait'}} {{col_class}} {{col_class_md}} {{col_class_lg}} {{col_is_stretched and 'oe_product_size_stretch'}}" t-attf-style="--o-wsale-products-grid-product-col-height: {{col_height}};" t-att-data-colspan="td_product['x'] != 1 and td_product['x']" t-att-data-rowspan="td_product['y'] != 1 and td_product['y']" t-att-data-name="product_block_name">\n                                                    <div t-attf-class="o_wsale_product_grid_wrapper position-relative h-100 o_wsale_product_grid_wrapper_#{td_product['x']}_#{td_product['y']}">\n                                                        <t t-call="website_sale.products_item">\n                                                            <t t-set="design_field" t-value="website.shop_opt_products_design_classes"/>\n                                                            <t t-set="product_href" t-value="product._get_product_url(category, product_query_params, grouped_attributes_values)"/>\n                                                        </t>\n                                                    </div>\n                                                </div>\n                                            </t>\n                                        </t>\n                                    </t>\n                                </section>\n                            </div>\n                            <div t-else="" class="text-center text-muted mt128 mb256">\n                                <t t-if="not search">\n                                    <div class="mt-5 mb-3"><t t-call="website.empty_search_svg"/></div>\n                                    <h3 class="mt8" style="text-align: center;">\n                                        No product defined\n                                    </h3>\n                                    <p t-if="category" style="text-align: center;">\n                                        No product defined in this category.\n                                    </p>\n                                </t>\n                                <t t-else="">\n                                    <div class="mt-5 mb-3"><t t-call="website.empty_search_svg"/></div>\n                                    <h3 class="mt8" style="text-align: center;">No results</h3>\n                                    <p style="text-align: center;">\n                                        No results for "<strong t-out="search"/>"<t t-if="category"> in category "<strong t-out="category.display_name"/>"</t>.\n                                    </p>\n                                    <p style="text-align: center;">\n                                        <a t-if="category" t-att-href="keep(shop_path, search=search)" t-attf-title="Search {{search}} globally" class="d-block pb-5">\n                                            Search globally\n                                        </a>\n                                    </p>\n                                </t>\n                                <div t-ignore="true" groups="sales_team.group_sale_manager" class="al