stomer_note\\" readonly=\\"1\\"/>\\n                    </page>\\n                </notebook>\\n            </sheet>\\n            <chatter groups=\\"point_of_sale.group_pos_manager\\"/>\\n            </form>"}	<?xml version="1.0"?>\n<form string="Point of Sale Orders" create="0">\n                <header>\n                    <button name="529" string="Payment" class="oe_highlight" type="action" invisible="state != 'draft'"/>\n                    <button name="action_pos_order_invoice" string="Invoice" type="object" invisible="state not in ['paid', 'done'] or account_move"/>\n                    <button name="refund" string="Return Products" type="object" invisible="state == 'draft' or not has_refundable_lines"/>\n                    <field name="state" widget="statusbar" invisible="state == 'cancel'" statusbar_visible="draft,paid,done"/>\n                    <field name="state" widget="statusbar" invisible="state != 'cancel'" statusbar_visible="draft,cancel"/>\n                    <field name="has_refundable_lines" invisible="1"/>\n                </header>\n                <sheet>\n                <field name="failed_pickings" invisible="1"/>\n                <div class="oe_button_box" name="button_box">\n                    <button name="action_stock_picking" type="object" class="oe_stat_button" icon="fa-truck" invisible="picking_count == 0">\n                        <field name="picking_count" widget="statinfo" string="Pickings" invisible="failed_pickings"/>\n                        <field name="picking_count" widget="statinfo" string="Pickings" class="text-danger" invisible="not failed_pickings"/>\n                    </button>\n                    <button name="action_view_invoice" string="Invoice" type="object" class="oe_stat_button" icon="fa-pencil-square-o" invisible="not account_move">\n                    </button>\n                    <button name="action_view_refund_orders" type="object" class="oe_stat_button" icon="fa-undo" invisible="refund_orders_co