        'widget': 'barcode',                             'width': 600,                             'height': 100,                             'img_style': 'width:100%;height:50px;'                         }"/>\n                    <div t-if="product.barcode" t-field="product.barcode" class="pb-2">Product barcode</div>\n                </th>\n                <th name="th_product" class="text-center" style="width: 30%;">\n                    <span t-field="product.display_name"/>\n                </th>\n                <th name="th_quantity" class="text-end" style="width: 20%;">\n                    <span t-out="product_qty">12.0</span>\n                    <span t-field="product.uom_id.name" groups="uom.group_uom">Units</span>\n                </th>\n                <th name="th_content_barcode" class="text-center" style="width: 20%;">\n                    <div t-if="len(aggregate_barcodes) == 1" t-out="aggregate_barcodes[0]" class="my-3" t-options="{                             'widget': 'barcode',                             'symbology': 'QR',                             'img_style': 'width: 24mm; height: 24mm',                         }"/>\n                    <div t-if="len(aggregate_barcodes) == 1" class="pb-2">Content</div>\n                </th>\n            </tr></thead>\n            <!-- Quant's details.  -->\n            <tbody t-if="display_content_details or len(aggregate_barcodes) &gt; 1">\n                <!-- Lot/Serial numbers, displayed 4 by 4.  -->\n                <tr t-if="display_content_details" style="font-size: 0.8em;" t-foreach="product_quants[i:i+4] for i in range(0, len(product_quants), 4)" t-as="quants">\n                    <td colspan="4">\n                        <div t-foreach="quants" t-as="quant" class="d-inline-block w-25 text-end" style="height: 18mm;">\n                            <div class="d-inline-block p-2 text-end align-top">\n                                <div t-field="quant.lot_id.name" class="mt-2">54326786758</div>\n                                <div class="mt-1">\n                                    <span t-field="quant.quantity">3.00</span>\n                                    <span t-field="quant.product_id.uom_id.name" groups="uom.group_uom">Units</span>\n                                </div>\n                            </div>\n                            <div class="d-inline-block py-2 text-center">\n                                <t t-set="quant_barcode" t-value="quant.lot_id.name"/>\n                                <t groups="stock.group_stock_lot_print_gs1" t-set="quant_barcode" t-value="quant._get_gs1_barcode(gs1_uom_patterns) or quant_barcode"/>\n                                <span t-out="quant_barcode" t-options="{                                         'widget': 'barcode',                                         'symbology': 'QR',                                         'img_style': 'width: 14mm; height: 14mm',                                     }"/>\n                            </div>\n                        </div>\n                    </td>\n                </tr>\n                <!-- Content's Barcodes -->\n                <tr t-if="len(aggregate_barcodes) &gt; 1" style="border-bottom-color: black">\n                    <td colspan="4" name="quant_qr_codes" class="py-4">\n                        <t t-foreach="aggregate_barcodes[i:i+3] for i in range(0, len(aggregate_barcodes), 3)" t-as="batch_aggregate_barcodes">\n                            <div class="w-100 p-0 py-5">\n                                <div t-foreach="batch_aggregate_barcodes" t-as="barcode" t-out="barcode" class="d-inline-block text-center" style="width: 33%;" t-options="{                                         'widget': 'barcode',                                         'symbology': 'QR',                                         'img_style': 'width: 48mm; height: 48mm',                                         'width': 800,                                         'height': 800,                                     }"/>\n                            </div>\n                        </t>\n                    </td>\n                </tr>\n            </tbody>\n        </table>\n    </t>\n</t>\n\n	f	t	2026-11-17 08:00:00.870439	2026-11-20 12:35:53.984544	f	\N	\N	\N	\N	\N	\N	\N	\N	\N	f	\N
