         </div>\\n\\n                                    <div class=\\"o_wsale_product_details_content_section o_wsale_product_details_content_section_contact mb-4\\">\\n                                        <div id=\\"contact_us_wrapper\\" t-attf-class=\\"d-flex oe_structure oe_structure_solo #{_div_classes} {{'d-flex' if combination_info['prevent_zero_price_sale'] else 'd-none'}}\\">\\n                                            <section class=\\"s_text_block\\" data-snippet=\\"s_text_block\\" data-name=\\"Text\\">\\n                                                <div class=\\"container\\">\\n                                                    <a t-att-href=\\"website.contact_us_button_url\\" t-att-data-url=\\"website.contact_us_button_url\\" class=\\"btn btn-primary btn_cta\\">\\n                                                        Contacta con nosotros\\n                                                    </a>\\n                                                </div>\\n                                            </section>\\n                                        </div>\\n                                    </div>\\n                                    <t t-set=\\"single_value_attributes\\" t-value=\\"product.valid_product_template_attribute_line_ids._prepare_single_value_for_display()\\"/>\\n                                    <div id=\\"product_attributes_simple\\" t-if=\\"single_value_attributes\\" class=\\"o_wsale_product_details_content_section o_wsale_product_details_content_section_specs mb-4\\">\\n                                        <table t-attf-class=\\"table table-sm text-muted {{'' if single_value_attributes else 'd-none'}}\\">\\n                                            <t t-foreach=\\"single_value_attributes\\" t-as=\\"attribute\\">\\n                                                <tr>\\n                                                    <td>\\n                                                        <span t-field=\\"attribute.name\\"/>:\\n                                                        <t t-foreach=\\"single_value_attributes[attribute]\\" t-as=\\"ptal\\">\\n                                                            <span t-field=\\"ptal.product_template_value_ids._only_active().name\\"/>\\n                                                            <t t-if=\\"not ptal_last\\">, </t>\\n                                                        </t>\\n                                                    </td>\\n                                                </tr>\\n                                            </t>\\n                                        </table>\\n                                    </div>\\n                                    <t t-set=\\"product_documents\\" t-value=\\"product.sudo().product_document_ids.filtered(lambda doc: doc.shown_on_product_page)\\"/>\\n                                    <div id=\\"product_documents\\" class=\\"o_wsale_product_details_content_section o_wsale_product_details_content_section_documents mb-4\\" t-if=\\"product_documents\\">\\n                                        <strong>Documentos</strong>\\n                                        <div class=\\"list-group\\">\\n                                            <t t-foreach=\\"product_documents\\" t-as=\\"document_sudo\\">\\n                                                <t t-set=\\"attachment_sudo\\" t-value=\\"document_sudo.ir_attachment_id\\"/>\\n                                                <t t-set=\\"target\\" t-value=\\"attachment_sudo.type == 'url' and '_blank' or '_self'\\"/>\\n                                                <t t-set=\\"icon\\" t-value=\\"attachment_sudo.type == 'url' and 'fa-link' or 'fa-download'\\"/>\\n                                                <a class=\\"list-group-item list-group-item-action\\" t-att-href=\\"'/shop/' + slug(product) + '/document/' + str(document_sudo.id)\\" t-att-target=\\"target\\">\\n                                                   