ombination_name\\" class=\\"h6 text-muted mb-1\\" t-out=\\"combination_name\\"/>\\n                                            <span t-if=\\"line.product_template_id._has_multiple_uoms()\\" class=\\"badge bg-light mb-1\\" t-out=\\"line.product_uom_id.name\\"/>\\n                                        </div>\\n                                    </div>\\n                                    <div t-attf-class=\\"{{'d-block d-md-none' if not is_combo else ''}}\\"><t t-call=\\"website_sale.cart_lines_price\\"/></div>\\n                                </div>\\n                                <t t-call=\\"website_sale.cart_line_description_following_lines\\"/>\\n                                <ul t-if=\\"is_combo\\" class=\\"list-group\\">\\n                                    <t t-foreach=\\"line.linked_line_ids.filtered('combo_item_id')\\" t-as=\\"combo_item_line\\">\\n                                        <t t-call=\\"website_sale.cart_combo_item_line\\"/>\\n                                    </t>\\n                                </ul>\\n                                <div name=\\"o_wsale_cart_line_button_container\\" t-attf-class=\\"d-none d-md-flex align-items-center gap-2 mt-2 {{'justify-content-between' if is_combo else ''}}\\">\\n                                    <a href=\\"#\\" class=\\"js_delete_product small\\" aria-label=\\"Remove from cart\\" title=\\"Remove from cart\\">\\n                                        Remove\\n                                    </a>\\n                                    <div t-if=\\"is_combo\\" class=\\"d-none d-md-block ms-auto\\"><t t-call=\\"website_sale.cart_lines_quantity\\"/></div>\\n                                </div>\\n                            </div>\\n                            <div t-if=\\"not is_combo\\" class=\\"d-none d-md-block\\">\\n                                <t t-call=\\"website_sale.cart_lines_price\\"/>\\n                                <div class=\\"d-none d-md-block mt-2\\"><t t-call=\\"web