heckout\\"/>\\n                        </div>\\n                        <!-- Checkout Page Content | Left Column -->\\n                        <div t-attf-class=\\"oe_clear_stucture oe_cart col-12 #{'col-lg-7' if website_sale_order and website_sale_order.website_order_line else ''}\\">\\n                            <t t-out=\\"0\\"/>\\n                        </div>\\n\\n                        <!-- Short Checkout Summary displayed on /cart | Right Column -->\\n                        <div t-if=\\"show_shorter_cart_summary\\" class=\\"o_wsale_shorter_cart_summary offset-xxl-1 col-lg-5 col-xxl-4\\">\\n                            <!-- Parent element needed for proper JS side rendering -->\\n                            <t t-call=\\"website_sale.shorter_cart_summary\\"/>\\n                        </div>\\n                        <!-- Full Checkout Summary displayed on all checkout pages | Right Column -->\\n                        <div t-else=\\"\\" class=\\"d-none d-lg-block offset-xxl-1 col-12 col-lg-5 col-xxl-4 rounded\\">\\n                            <div class=\\"o_total_card card sticky-lg-top o_wsale_sticky_object mb-3 mb-lg-0\\">\\n                                <div class=\\"card-body p-lg-4 pt-lg-3\\">\\n                                    <div class=\\"d-none d-lg-block\\">\\n                                        <t t-call=\\"website_sale.cart_summary_content\\"/>\\n                                        <t t-call=\\"website_sale.total\\">\\n                                            <t t-set=\\"_cart_total_classes\\" t-valuef=\\"border-top pt-2\\"/>\\n                                        </t>\\n                                    </div>\\n                                    <div t-if=\\"show_navigation_button\\" class=\\"o_cta_navigation_container px-0\\">\\n                                        <t t-call=\\"website_sale.navigation_buttons\\"/>\\n                                    </div>\\n                                </div>\\n                