                   <t t-call=\\"website_sale.total\\">\\n                                    <t t-set=\\"hide_promotions\\" t-value=\\"True\\"/>\\n                                    <t t-set=\\"_cart_total_classes\\" t-valuef=\\"border-top px-3 pt-2 mx-n3\\"/>\\n                                </t>\\n                                <button class=\\"btn btn-light w-100\\" type=\\"button\\" data-bs-dismiss=\\"offcanvas\\" aria-label=\\"Cerrar\\">\\n                                    Cerrar\\n                                </button>\\n                            </div>\\n                        </div>\\n                    </t>\\n                </div>\\n                <!-- This is the drag-and-drop area for website building blocs at the end of each\\n                     checkout page. The templates created in the database to store blocs are hooked\\n                     using XPath on the `oe_struture` element ID. Therefore, we can't use dynamic\\n                     IDs (like with t-att-id) and each template needs to define a div element. -->\\n                <t t-out=\\"oe_structure\\"/>\\n            </div>\\n        </t>\\n    </t>"}	<?xml version="1.0"?>\n<t name="Checkout layout page" t-name="website_sale.checkout_layout">\n        <!-- Layout customization parameters:\n            - show_footer: Whether to show the website footer; default: `False`.\n            - show_navigation_button: Whether to show the navigation buttons; default: `True`.\n            - show_wizard_checkout: Whether to show the wizard checkout; default: `True`.\n            - show_shorter_cart_summary: Whether to show the shorter cart_summary (without items\n                                         summary and with express checkout buttons) or the full;\n                                         default: `None`.\n            - show_mobile_cart_summary: Whether to show the mobile offcanvas cart_summary;\n                                        default: `True`.\n            - oe_structure: The structure element to append at the bottom of the page;\n                            default: `None`.\n        -->\n        <!-- Checkout context (non exhaustive):\n            - redirect: The route to redirect to when a customer enters a coupon; default: `None`.\n            - website_sale_order: The current order.\n        -->\n        <t t-call="website.layout">\n            <t t-set="no_footer" t-value="True if show_footer is None else not show_footer"/>\n            <t t-set="show_navigation_button" t-value="True if show_navigation_button is None else show_navigation_button"/>\n            <t t-set="expand_order_summary" t-value="not show_navigation_button"/>\n            <t t-set="show_wizard_checkout" t-value="True if show_wizard_checkout is None else show_wizard_checkout"/>\n            <t t-set="show_mobile_cart_summary" t-value="True if show_mobile_cart_summary is None else show_mobile_cart_summary"/>\n            <t t-set="body_classname" t-value="'o_website_sale_checkout'"/>\n            <div id="wrap" class="d-flex flex-column flex-grow-1">\n                <div class="oe_website_sale o_website_sale_checkout_container container d-flex flex-column flex-grow-1 py-lg-2">\n                    <div t-attf-class="row #{not show_wizard_checkout and 'mt32'} mb32">\n                        <div t-if="show_wizard_checkout" class="col-12">\n                            <t t-call="website_sale.wizard_checkout"/>\n                        </div>\n                        <!-- Checkout Page Content | Left Column -->\n                        <div t-attf-class="oe_clear_stucture oe_cart col-12 #{'col-lg-7' if website_sale_order and website_sale_order.website_order_line else ''}">\n                            <t t-out="0"/>\n                        </div>\n\n                        <!-- Short Checkout Summary displayed on /cart | Right Column -->\n                        <div t-if="show_shorter_cart_summary" class="o_wsale_shorter_cart_summary offset-xxl-1 col-lg-5 col-xxl-4">\n                            <!-- Parent element needed for proper JS side rendering -->\n                            <t t-call="website_sale.shorter_cart_summary"/>\n                        </div>\n                        <!-- Full Checkout Summary displayed on all checkout pages | Right Column -->\n                        <div t-else="" class="d-none d-lg-block offset-xxl-1 col-12 col-lg-5 col-xxl-4 rounded">\n                            <div class="o_total_card card sticky-lg-top o_wsale_sticky_object mb-3 mb-lg-0">\n                                <div class="card-body p-lg-4 pt-lg-3">\n                                    <div class="d-none d-lg-block">\n                                        <t t-call="website_sale.cart_summary_content"/>\n                                        <t t-call="website_sale.total">\n                                            <t t-set="_cart_total_classes" t-valuef="border-top pt-2"/>\n                                        </t>\n                                    </div>\n                                    <div t-if="show_navigation_button" class="o_cta_navigation_container px-0">\n                                        <t t-call="website_sale.navigation_buttons"/>\n                                    </div>\n                                </div>\n                            </div>\n                        </div>\n                    </div>\n                    <!-- Mobile Order Summary | Bottom of page and Offcanvas -->\n                    <t t-if="not show_shorter_cart_summary and show_mobile_cart_summary">\n                        <div class="o_mobile_summary d-lg-none sticky-bottom mt-auto bg-body">\n                            <button class="btn btn-light d-flex justify-content-between align-items-center gap-2 w-100 mb-2" data-bs-toggle="offcanvas" href="#o_cart_summary_offcanvas" aria-controls="o_cart_summary_offcanvas">\n                                Order\n                                <span id="amount_total_summary" class="monetary_field ms-auto" t-field="website_sale_order.amount_total" t-options="{&quot;widget&quot;: &quot;monetary&quot;, &quot;display_currency&quot;: website_sale_order.currency_id}"/>\n                                <span class="o_cart_item_count badge ms-1 top-0 bg-primary" t-out="str(website_sale_order.cart_quantity)"/>\n                                <i class="fa fa-angle-right ms-2" role="img"/>\n                            </button>\n                            <t t-if="show_navigation_button" t-call="website_sale.navigation_buttons"/>\n                        </div>\n                        <div id="o_cart_summary_offcanvas" class="offcanvas offcanvas-end" tabindex="-1" aria-labelledby="o_cart_summary_offcanvas">\n                            <div class="offcanvas-body">\n                                <t t-call="website_sale.cart_summary_content"/>\n                            </div>\n                            <div class="offcanvas-footer p-3">\n                                <a href="/shop/cart" class="btn btn-link w-100">\n                                    Coupon, Gift card, Promo-code?\n                                </a>\n                                <t t-call="website_sale.total">\n                                    <t t-set="hide_promotions" t-value="True"/>\n                                    <t t-set="_cart_total_classes" t-valuef="border-top px-3 pt-2 mx-n3"/>\n                                </t>\n                                <button class="btn btn-light w-100" type="button" data-bs-dismiss="offcanvas" aria-label="Close">\n                                    Close\n                                </button>\n                            </div>\n                        </div>\n                    </t>\n                </div>\n                <!-- This is the drag-and-drop area for website building blocs at the end of each\n                     checkout page. The templates created in the database to store blocs are hooked\n                     using XPath on the `oe_struture` element ID. Therefore, we can't use dynamic\n                     IDs (like with t-att-id) and each template needs to define a div element. -->\n                <t t-out="oe_structure"/>\n            </div>\n        </t>\n    </t>\n\n    	f	t	2026-11-20 12:39:46.036801	2026-11-20 12:39:46.036801	f	\N	\N	\N	\N	\N	\N	\N	\N	\N	f	f
2642	16	\N	1	1	website_sale.cart_summary_content	\N	website_sale.cart_summary_content	qweb	website_sale/views/templates.xml	primary	{"en_US": "<t t-name=\\"website_sale.cart_summary_content\\">\\n        <div t-if=\\"not website_sale_order or not website_sale_order.website_order_line\\" name=\\"cart_summary_info\\" class=\\"alert alert-info\\">\\n            Your cart is empty!\\n        </div>\\n        <div>\\n            <div t-att-class=\\"len(website_sale_order.website_order_line) &gt; 3 and 'o_wsale_scrollable_table'\\">\\n                <table t-if=\\"website_sale_order and website_sale_order.website_order_line\\" class=\\"o_cart_products_table table mb-0\\">\\n                    <tbody>\\n                        <tr t-foreach=\\"website_sale_order.website_order_line\\" t-as=\\"line\\" t-att-class=\\"line_last and 'border-transparent'\\">\\n                            <td class=\\"td-img ps-0 pt-3\\">\\n                                <div class=\\"o_cart_product_image position-relative\\">\\n                                    <span t-if=\\"not line._is_sellable() and line.product_id.image_128\\">\\n                                        <img t-att-src=\\"image_data_uri(line.product_id.image_128)\\" class=\\"img rounded\\" t-att-alt=\\"line.name_short\\"/>\\n                                    </span>\\n                                    <span t-else=\\"\\" t-field=\\"line.product_id.image_128\\" t-options=\\"{'widget': 'image', 'qweb_img_responsive': False, 'class': 'rounded'}\\"/>\\n                                    <span class=\\"o_cart_item_count badge bg-secondary position-absolute top-0 start-100 translate-middle\\">\\n                                        <t t-out=\\"int(line.product_uom_qty)\\"/>\\n                                        <i t-if=\\"line._get_shop_warning(clear=False)\\" class=\\"fa fa-warning\\" role=\\"img\\" t-att-title=\\"line._get_shop_warning()\\" aria-label=\\"Warning\\"/>\\n                                    </span>\\