ead>\n                            <tr>\n                                <th>Description</th>\n                                <th>Scope</th>\n                                <th>Added On</th>\n                                <th>Expiration Date</th>\n                                <th/>\n                            </tr>\n                        </thead>\n                        <tbody>\n                            <t t-foreach="request.env.user.api_key_ids" t-as="key">\n                                <tr>\n                                    <td><span t-field="key.name"/></td>\n                                    <td><span t-field="key.scope"/></td>\n                                    <td><span t-field="key.create_date"/></td>\n                                    <td><span t-field="key.expiration_date"/></td>\n                                    <td>\n                                        <i class="fa fa-trash text-danger o_portal_remove_api_key" type="button" t-att-id="key.id"/>\n                                    </td>\n                                </tr>\n                            </t>\n                        </tbody>\n                    </table>\n                </div>\n                <div>\n                    <button type="submit" class="btn btn-light o_portal_new_api_key">New API Key</button>\n                </div>\n            </section>\n            <section name="portal_deactivate_account" groups="base.group_portal">\n                <h4>Delete Account</h4>\n                <t t-set="deactivate_error" t-value="get_error(errors, 'deactivate')"/>\n                <button class="btn btn-light" data-bs-toggle="modal" data-bs-target="#portal_deactivate_account_modal">\n                    Delete Account\n                </button>\n                <div t-attf-class="modal #{'show d-block' if open_deactivate_modal else ''}" id="portal_deactivate_account_modal" tabindex="-1" role="dialog">\n                    <div class="modal-dialog" role="documen