ting>\\n                <setting id=\\"pricelists_setting\\" help=\\"Aplica precios o monedas específicas por país, cliente, productos, etc.\\" documentation=\\"/applications/sales/sales/products_prices/prices/pricing.html\\">\\n                    <field name=\\"group_product_pricelist\\"/>\\n                    <button string=\\"Listas de precios\\" type=\\"action\\" name=\\"172\\" groups=\\"product.group_product_pricelist\\" invisible=\\"not group_product_pricelist\\" class=\\"btn-link\\" icon=\\"oi-arrow-right\\"/>\\n                </setting>\\n                <setting id=\\"hide_add_to_cart_setting\\" help=\\"Si el precio del producto es igual a 0, sustituye «Añadir a la cesta» por «Contacta con nosotros».\\">\\n                    <field name=\\"website_sale_prevent_zero_price_sale\\"/>\\n                    <div class=\\"content-group\\" invisible=\\"not website_sale_prevent_zero_price_sale\\">\\n                        <div class=\\"row mt16\\">\\n                            <label string=\\"URL del botón\\" for=\\"website_sale_contact_us_button_url\\" class=\\"o_light_label col-lg-3\\"/>\\n                            <field name=\\"website_sale_contact_us_button_url\\"/>\\n                        </div>\\n                    </div>\\n                </setting>\\n                <setting string=\\"Confirmación del pedido\\" id=\\"order_confirmation_setting\\">\\n                    <div class=\\"content-group\\">\\n                        <div class=\\"row mt16\\">\\n                            <label string=\\"Correo electrónico\\" for=\\"confirmation_email_template_id\\" class=\\"o_light_label col-lg-3\\"/>\\n                            <field name=\\"confirmation_email_template_id\\"/>\\n                        </div>\\n                    </div>\\n                </setting>\\n                <setting string=\\"Seguimiento de cestas abandonadas\\" id=\\"abandoned_carts_setting\\" help=\\"Automatizar los correos electrónicos de cestas abandonadas\\" documentation=\\"/applications/websites/ecommerce/ecommerce_management/order_handling.html#abandoned-cart\\">\\n                    <field name=\\"send_abandoned_cart_email\\"/>\\n                    <div invisible=\\"not send_abandoned_cart_email\\" class=\\"content-group\\">\\n                        <div class=\\"row mt16\\">\\n                            <div class=\\"col-12\\">\\n                                <label string=\\"Enviar después\\" for=\\"cart_abandoned_delay\\" class=\\"o_light_label\\"/>\\n                                <field name=\\"cart_abandoned_delay\\" widget=\\"float_time\\" class=\\"ms-1\\" style=\\"width: 50px;\\"/> horas.\\n                            </div>\\n                        </div>\\n                    </div>\\n                    <div invisible=\\"not send_abandoned_cart_email\\" class=\\"mt8\\">\\n                        <button type=\\"object\\" name=\\"action_open_abandoned_cart_mail_template\\" string=\\"Personalizar plantilla de correo electrónico abandonada\\" class=\\"btn-link\\" icon=\\"oi-arrow-right\\"/>\\n                    </div>\\n                </setting>\\n                <setting string=\\"Asignación de pedidos\\" help=\\"Asignación de pedidos en línea\\">\\n                    <div class=\\"content-group\\">\\n                        <div class=\\"row mt16\\">\\n                            <label string=\\"Equipo de ventas\\" for=\\"salesteam_id\\" class=\\"o_light_label col-lg-3\\"/>\\n                            <field name=\\"salesteam_id\\" context=\\"{'kanban_view_ref': 'sales_team.crm_team_view_kanban'}\\"/>\\n                        </div>\\n                        <div class=\\"row\\">\\n                            <label for=\\"salesperson_id\\" class=\\"o_light_label col-lg-3\\"/>\\n                            <field name=\\"salesperson_id\\"/>\\n                        </div>\\n                    </div>\\n                </setting>\\n                <setting id=\\"click_and_collect_setting\\" help=