ing="Configure Methods" type="action" name="602" class="btn btn-primary"/>\n                    <button string="Find a Delivery Provider" type="object" name="action_view_delivery_provider_modules" class="btn btn-link" icon="oi-arrow-right"/>\n                </setting>\n                <setting string="Display Product Prices" id="website_tax_inclusion_setting">\n                    <field name="show_line_subtotals_tax_selection" widget="radio" class="o_light_label"/>\n                </setting>\n                <setting id="ecommerce_access_setting" title="Shop, products, cart and wishlist visibility">\n                    <field name="ecommerce_access" widget="radio" class="o_light_label"/>\n                </setting>\n                <setting string="Sign in/up at checkout" id="checkout_registration_setting" title="To send invitations in B2B mode, open a contact or select several ones                            in list view and click on 'Portal Access Management' option in the                            dropdown menu *Action*.">\n                    <field name="account_on_checkout" widget="radio"/>\n                </setting>\n                <setting string="Add to Cart" id="cart_redirect_setting" help="What should be done on &quot;Add to Cart&quot;?">\n                    <field name="add_to_cart_action" widget="radio"/>\n                </setting>\n                <setting string="Invoicing Policy" id="invoicing_policy_setting" title="The mode selected here applies as invoicing policy of any new product                            created but not of products already existing." info="This setting is common to all websites.">\n                    <field name="default_invoice_policy" widget="radio" class="o_light_label"/>\n                </setting>\n                <setting id="automatic_invoice_generation_setting" help="Invoice automatically on payment." invisible="default_invoice_policy == 'delivery'">\n                    <field name="automatic_invoice"/>\n   