io\\" t-attf-class=\\"js_variant_change cursor-pointer #{attribute.create_variant}\\" t-att-checked=\\"ptav in combination\\" t-att-name=\\"'ptal-%s' % ptal.id\\" t-att-value=\\"ptav.id\\" t-att-title=\\"ptav.name\\" t-att-data-attribute-value-id=\\"ptav.product_attribute_value_id.id\\" t-att-data-value-id=\\"ptav.id\\" t-att-data-value-name=\\"ptav.name\\" t-att-data-attribute-name=\\"attribute.name\\" t-att-data-is-custom=\\"ptav.is_custom\\"/>\\n                                </label>\\n                            </li>\\n                        </ul>\\n                    </t>\\n\\n                    <t t-elif=\\"attribute.display_type == 'image'\\">\\n                        <ul t-att-data-attribute-id=\\"attribute.id\\" t-attf-class=\\"list-inline o_wsale_product_attribute #{'d-none' if single_and_custom else ''}\\">\\n                            <li t-foreach=\\"ptavs\\" t-as=\\"ptav\\" class=\\"list-inline-item me-2 mb-2\\">\\n                                <label name=\\"o_wsale_attribute_image_selector\\" t-attf-style=\\"#{'background-image: url(/web/image/product.template.attribute.value/%s/image); background-size:cover;' % ptav.id if ptav.image else ''}\\" t-attf-class=\\"css_attribute_image oe_img_bg o_bg_img_center position-relative d-inline-block rounded-3 bg-body text-center cursor-pointer #{'active' if ptav in combination else ''} #{'custom_value' if ptav.is_custom else ''} #{'transparent' if (not ptav.is_custom and not ptav.html_color) else ''}\\">\\n                                    <input type=\\"radio\\" t-attf-class=\\"js_variant_change w-100 h-100 opacity-0 cursor-pointer #{attribute.create_variant}\\" t-att-checked=\\"ptav in combination\\" t-att-name=\\"'ptal-%s' % ptal.id\\" t-att-value=\\"ptav.id\\" t-att-title=\\"ptav.name\\" t-att-data-attribute-value-id=\\"ptav.product_attribute_value_id.id\\" t-att-data-value-id=\\"ptav.id\\" t-att-data-value-name=\\"ptav.name\\" t-att-data-attribute-name=\\"attribute.name\\" t-att-data-is-custom=