\\"/>\\n                    <t t-set=\\"btn_text\\" t-value=\\"step.button_text\\"/>\\n                    <t t-set=\\"done_text\\" t-value=\\"step.done_text\\"/>\\n                    <t t-set=\\"image\\" t-value=\\"'/web/image/onboarding.onboarding.step/'+str(step.id)+'/step_image'\\"/>\\n                    <t t-set=\\"alt\\" t-value=\\"step.step_image_alt\\"/>\\n                    <!-- Model/method used by JS implementation of banners for each step-->\\n                    <t t-set=\\"method\\" t-value=\\"step.panel_step_open_action_name\\"/>\\n                    <t t-set=\\"model\\">onboarding.onboarding.step</t>\\n                    <!-- to mimic first implementation of onboarding, the 'state' queried holds\\n                    a rendering state for all steps. See _get_and_update_onboarding_state -->\\n                    <t t-set=\\"state\\" t-value=\\"state.get(step.id)\\"/>\\n                </t>\\n            </t>\\n        </t>\\n    </t>"}	<?xml version="1.0"?>\n<t t-name="onboarding.onboarding_panel">\n        <t t-call="onboarding.onboarding_container">\n            <t t-foreach="steps" t-as="step">\n                <t t-call="onboarding.onboarding_step">\n                    <t t-set="title" t-value="step.title"/>\n                    <t t-set="description" t-value="step.description"/>\n                    <t t-set="done_icon" t-value="step.done_icon"/>\n                    <t t-set="btn_text" t-value="step.button_text"/>\n                    <t t-set="done_text" t-value="step.done_text"/>\n                    <t t-set="image" t-value="'/web/image/onboarding.onboarding.step/'+str(step.id)+'/step_image'"/>\n                    <t t-set="alt" t-value="step.step_image_alt"/>\n                    <!-- Model/method used by JS implementation of banners for each step-->\n                    <t t-set="method" t-value="step.panel_step_open_action_name"/>\n                    <t t-set="model">onboarding.onboarding.step</t>\n                    <!-- to mimic