4 class=\\"mb-0\\">Resumen del pedido</h4>\\n                    <div class=\\"ms-3 border-start ps-2\\"><t t-call=\\"website_sale.quick_reorder_button\\"/></div>\\n                </div>\\n                <div t-if=\\"abandoned_proceed or access_token\\" class=\\"alert alert-info mt8 mb8\\" role=\\"alert\\"> <!-- abandoned cart choices -->\\n                    <t t-if=\\"abandoned_proceed\\">\\n                        <p>Se ha completado su cesta anterior.</p>\\n                        <p t-if=\\"website_sale_order\\">Continúe con su cesta actual.</p>\\n                    </t>\\n                    <t t-if=\\"access_token\\">\\n                        <p>Este es su cesta actual.</p>\\n                        <p>\\n                            <strong>\\n                                <a class=\\"o_translate_inline\\" t-attf-href=\\"/shop/cart/?id={{id}}&amp;access_token={{access_token}}&amp;revive_method=squash\\">Haga clic aquí</a>\\n                            </strong> si desea recuperar su carro anterior. Su carro actual será sustituido por el anterior.\\n                        </p>\\n                        <p>\\n                            <strong>\\n                                <a class=\\"o_translate_inline\\" t-attf-href=\\"/shop/cart/?id={{id}}&amp;access_token={{access_token}}&amp;revive_method=merge\\">Haga clic aquí</a>\\n                            </strong> si desea combinar su carro anterior con el actual.\\n                        </p>\\n                    </t>\\n                </div>\\n                <t t-call=\\"website_sale.cart_lines\\"/>\\n                <div class=\\"clearfix\\"/>\\n                <div class=\\"oe_structure\\" id=\\"oe_structure_website_sale_cart_1\\"/>\\n            </div>\\n        </t>\\n    </t>"}	<?xml version="1.0"?>\n<t name="Shopping Cart" t-name="website_sale.cart">\n        <t t-call="website_sale.checkout_layout">\n            <t t-set="show_shorter_cart_summary" t-value="True"/>\n            <t t-set="s