_location_data\\" t-value=\\"(is_selected and order.pickup_location_data) or {}\\"/>\\n            <div name=\\"o_pickup_location_details\\" t-attf-class=\\"d-flex justify-items-between align-items-center gap-3 w-100 border p-3 rounded {{'' if pickup_location_data else 'd-none'}}\\">\\n                <span>\\n                    <b name=\\"o_pickup_location_name\\" t-out=\\"pickup_location_data.get('name', '')\\"/>\\n                    <br/>\\n                    <span name=\\"o_pickup_location_address\\" class=\\"text-muted\\" t-out=\\"(pickup_location_data.get('street', ) or '')                                + ' '                                + (pickup_location_data.get('zip_code') or '')                                + ' '                                + (pickup_location_data.get('city') or '')\\"/>\\n                </span>\\n                <span name=\\"o_pickup_location_selector\\" class=\\"btn btn-light fa fa-pencil ms-auto p-3\\" title=\\"Change location\\" aria-label=\\"Change location\\" t-att-data-location-id=\\"pickup_location_data.get('id')\\" t-att-data-zip-code=\\"pickup_location_data.get('zip_code')\\" t-att-data-pickup-location-data=\\"json.dumps(pickup_location_data)\\"/>\\n            </div>\\n            <button t-if=\\"not pickup_location_data\\" name=\\"o_pickup_location_selector\\" type=\\"button\\" class=\\"btn btn-primary ms-4\\" t-att-data-zip-code=\\"order.partner_shipping_id.zip\\">\\n                Select a location\\n            </button>\\n        </div>\\n        <div t-if=\\"dm.website_description\\" t-field=\\"dm.website_description\\" class=\\"text-muted mt-1\\"/>\\n    </t>", "es_ES": "<t t-name=\\"website_sale.delivery_method\\">\\n        <!-- Parameters description:\\n            - dm: The delivery method to display, as a `delivery.carrier` recordset.\\n            - is_selected: Whether the radio button of the delivery method should be checked.\\n        -->\\n        <t t-set=\\"delivery_type\\" t-value=\\"dm.deliver