2646	16	\N	1	1	payment_confirmation_status	\N	website_sale.payment_confirmation_status	qweb	website_sale/views/templates.xml	primary	{"en_US": "<t t-name=\\"website_sale.payment_confirmation_status\\">\\n        <div name=\\"order_confirmation\\" class=\\"mt-3\\" t-att-data-order-id=\\"order.id\\" t-att-data-order-tracking-info=\\"json.dumps(order_tracking_info)\\">\\n            <t t-set=\\"tx_sudo\\" t-value=\\"order.get_portal_last_transaction()\\"/>\\n            <div t-if=\\"tx_sudo\\" t-attf-class=\\"alert px-3 pb-0 pt-3 #{                     (tx_sudo.state == 'pending' and 'alert-info') or                     (tx_sudo.state == 'done' and order.amount_total == tx_sudo.amount and 'alert-success') or                     (tx_sudo.state == 'done' and order.amount_total != tx_sudo.amount and 'alert-warning') or                     (tx_sudo.state == 'authorized' and 'alert-success') or                     'alert-danger'}\\" role=\\"alert\\">\\n                <a title=\\"Edit\\" class=\\"btn btn-sm btn-link text-dark float-end\\" role=\\"button\\" groups=\\"base.group_system\\" target=\\"_blank\\" aria-label=\\"Edit\\" t-attf-href=\\"/odoo/action-payment.action_payment_provider/{{tx_sudo.provider_id.id}}\\">\\n                    <i class=\\"fa fa-pencil\\"/>\\n                </a>\\n                <div>\\n                    <t t-if=\\"tx_sudo.state == 'pending'\\">\\n                        <t t-out=\\"tx_sudo.provider_id.sudo().pending_msg\\"/>\\n                    </t>\\n                    <t t-if=\\"tx_sudo.state == 'done'\\">\\n                        <span t-if=\\"tx_sudo.provider_id.sudo().done_msg\\" t-out=\\"tx_sudo.provider_id.sudo().done_msg\\"/>\\n                    </t>\\n                    <t t-if=\\"tx_sudo.state == 'done' and order.amount_total != tx_sudo.amount\\">\\n                        <span>Unfortunately your order can not be confirmed as the amount of your payment does not match the amount of your cart.\\n                        Please