ase.group_no_one\\"/>\\n                    <filter name=\\"not_secured\\" string=\\"Not Secured\\" domain=\\"[('secured', '=', False), ('state', '=', 'posted')]\\" groups=\\"account.group_account_secured,base.group_no_one\\"/>\\n                    <separator/>\\n                    <filter name=\\"not_sent\\" string=\\"Not Sent\\" domain=\\"[('is_move_sent', '=', False)]\\" invisible=\\"context.get('default_move_type') in ('in_invoice', 'in_refund', 'in_receipt')\\"/>\\n                    <separator/>\\n                    <filter name=\\"out_invoice\\" string=\\"Invoices\\" domain=\\"[('move_type', '=', 'out_invoice')]\\"/>\\n                    <filter name=\\"out_receipt\\" string=\\"Receipts\\" domain=\\"[('move_type', '=', 'out_receipt')]\\"/>\\n                    <filter name=\\"out_refund\\" string=\\"Credit Notes\\" domain=\\"[('move_type', '=', 'out_refund')]\\"/>\\n                    <separator/>\\n                    <filter string=\\"To Review\\" name=\\"to_check\\" domain=\\"[('checked', '=', False), ('state', '!=', 'draft')]\\"/>\\n                    <separator/>\\n                    <!-- not_paid & partial -->\\n                    <filter name=\\"open\\" string=\\"To pay\\" domain=\\"[('state', '!=', 'cancel'), ('payment_state', 'in', ('not_paid', 'partial')), ('move_type', '!=', 'entry')]\\"/>\\n                    <!-- in_payment & paid -->\\n                    <filter name=\\"in_payment\\" string=\\"In payment\\" domain=\\"[('state', '=', 'posted'), ('payment_state', '=', 'in_payment')]\\"/>\\n                    <!-- overdue -->\\n                    <filter name=\\"late\\" string=\\"Overdue\\" domain=\\"[                         ('invoice_date_due', '&lt;', 'today'),                         ('state', '=', 'posted'),                         ('payment_state', 'in', ('not_paid', 'partial')),                         ('move_type', '!=', 'entry')                     ]\\" help=\\"Overdue invoices, maturity date passed\\"/>\\n                   