tal_invoice_success"/>\n\n                    <div class="o_portal_html_view position-relative bg-white shadow overflow-hidden">\n                        <div class="o_portal_html_loader text-center">\n                            <i class="fa fa-circle-o-notch fa-spin fa-2x fa-fw text-black-50"/>\n                        </div>\n                        <iframe id="invoice_html" class="position-relative d-block" width="100%" height="100%" frameborder="0" scrolling="no" t-att-src="invoice.get_portal_url(report_type='html')"/>\n                    </div>\n                    <!-- chatter -->\n                    <div id="invoice_communication" class="mt-4">\n                        <h3>Communication history</h3>\n                        <t t-call="portal.message_thread"/>\n                    </div>\n                </div>\n            </div>\n        </xpath>\n    <xpath expr="." position="attributes"><attribute name="t-name">account.portal_invoice_page</attribute></xpath></data>\n\n    	f	t	2026-11-17 08:42:28.455657	2026-11-20 12:35:53.984544	f	\N	\N	\N	\N	\N	\N	\N	\N	\N	f	\N
