2765	16	\N	1	1	Wishlist Page	\N	website_sale_wishlist.product_wishlist	qweb	website_sale_wishlist/views/website_sale_wishlist_template.xml	primary	{"en_US": "<t name=\\"Wishlist Page\\" t-name=\\"website_sale_wishlist.product_wishlist\\">\\n        <t t-call=\\"website.layout\\">\\n            <t t-set=\\"additional_title\\">Shop Wishlist</t>\\n            <div id=\\"wrap\\" class=\\"js_sale\\">\\n                <div class=\\"oe_structure\\" id=\\"oe_structure_website_sale_wishlist_product_wishlist_1\\"/>\\n                <div class=\\"container oe_website_sale\\">\\n                    <section class=\\"container wishlist-section pb-5\\">\\n                        <div class=\\"o_wishlist_products_header pt-4 pb-3\\">\\n                            <h1 class=\\"h4-fs mb-0\\">My Wishlist</h1>\\n                        </div>\\n                        <div id=\\"empty-wishlist-message\\" t-attf-class=\\"w-100 #{'d-none' if wishes else ''}\\">\\n                            <div class=\\"mt-5 mb-3\\">\\n                                <t t-call=\\"website_sale_wishlist.empty_wishlist_svg\\"/>\\n                            </div>\\n                            <h5 class=\\"mb-3\\" style=\\"text-align: center;\\">\\n                                Your wishlist is empty!\\n                            </h5>\\n                            <p style=\\"text-align: center;\\">\\n                                <a href=\\"/shop\\" class=\\"btn btn-primary\\">\\n                                    Shop\\n                                </a>\\n                            </p>\\n                        </div>\\n\\n                        <div id=\\"o_comparelist_table\\" t-att-data-wishlist-grid-columns=\\"website.wishlist_grid_columns\\" t-att-data-wishlist-mobile-columns=\\"website.wishlist_mobile_columns\\" t-attf-style=\\"--o-wsale-wishlist-grid-gap: {{website.wishlist_gap}};\\" t-attf-class=\\"o_wishlist_table grid table-comparator mb-5 {{website.wishlist_opt_products_design_classes}}\\">\\n                            <t t-foreach=\\"wishes\\" t-as=\\"wish\\">\\n                                <t t-set=\\"product_variant\\" t-value=\\"wish.product_id\\"/>\\n                                <t t-set=\\"product\\" t-value=\\"product_variant.product_tmpl_id\\"/>\\n                                <t t-set=\\"product_href\\" t-value=\\"product_variant.website_url\\"/>\\n                                <t t-set=\\"combination_info\\" t-value=\\"product_variant._get_combination_info_variant()\\"/>\\n                                <article class=\\"o_wishlist_item\\" t-att-data-wish-id=\\"wish.id\\" t-att-data-product-id=\\"product_variant.id\\">\\n                                    <t t-call=\\"website_sale.products_item\\">\\n                                        <t t-set=\\"show_variations\\" t-value=\\"False\\"/>\\n                                        <t t-set=\\"show_ribbons\\" t-value=\\"False\\"/>\\n                                        <t t-set=\\"product_price\\">\\n                                            <br t-if=\\"combination_info['prevent_zero_price_sale']\\"/>\\n                                            <div t-else=\\"\\" class=\\"align-middle o_wish_price\\">\\n                                                <span aria-label=\\"Sale price\\">\\n                                                    <t t-out=\\"combination_info['price']\\" t-options=\\"{'widget': 'monetary', 'display_currency': website.currency_id}\\"/>\\n                                                </span>\\n                                                <small t-if=\\"combination_info['has_discounted_price']\\" class=\\"cart_product_base_unit_price text-muted\\">\\n                                                    <del aria-label=\\"Original price\\" t-out=\\"combination_info['list_price']\\" class=\\"text-nowrap\\" t-options=\\"{'widget': 'monetary', 'display_currency': website.currency_id}\\" name=\\"product_list_price\\"/>\\n                 