v>\\n                                    </div>\\n                                </setting>\\n                                <setting string=\\"Take out / Delivery / Members\\" help=\\"Define presets to manage taxes &amp; prices for dine in, take out, members...\\">\\n                                    <field name=\\"pos_use_presets\\"/>\\n                                    <div class=\\"content-group\\" invisible=\\"not pos_use_presets\\">\\n                                        <div class=\\"row\\">\\n                                            <label for=\\"pos_available_preset_ids\\" class=\\"col-lg-3\\" string=\\"Available\\"/>\\n                                            <field name=\\"pos_available_preset_ids\\" widget=\\"many2many_tags\\" options=\\"{'no_quick_create': True, 'color_field': 'color'}\\"/>\\n                                        </div>\\n                                        <div class=\\"row\\">\\n                                            <label for=\\"pos_default_preset_id\\" class=\\"col-lg-3\\" string=\\"Default\\"/>\\n                                            <field name=\\"pos_default_preset_id\\" options=\\"{'no_create': True}\\" required=\\"pos_use_presets\\" domain=\\"[('id', 'in', pos_available_preset_ids)]\\"/>\\n                                        </div>\\n                                        <div>\\n                                            <button name=\\"562\\" icon=\\"oi-arrow-right\\" type=\\"action\\" string=\\"Configure Presets\\" class=\\"btn-link\\"/>\\n                                        </div>\\n                                    </div>\\n                                </setting>\\n                            </block>\\n                            <block title=\\"Payment\\" id=\\"pos_payment_section\\">\\n                                <setting id=\\"payment_methods_new\\" string=\\"Payment Methods\\" help=\\"Payment methods available\\" documentation=\\"/applications/sales/point_of_sale/payment_methods.html\\">\\n                                    <field name=\\"pos_payment_method_ids\\" colspan=\\"4\\" widget=\\"many2many_tags\\" readonly=\\"pos_has_active_session\\" required=\\"pos_company_has_template\\" options=\\"{'no_quick_create': True}\\" context=\\"{'default_config_ids': [pos_config_id], 'form_view_ref': 'point_of_sale.action_pos_payment_method_form' }\\"/>\\n                                    <div>\\n                                        <button name=\\"551\\" icon=\\"oi-arrow-right\\" type=\\"action\\" string=\\"Payment Methods\\" class=\\"btn-link\\"/>\\n                                    </div>\\n                                </setting>\\n                                <setting string=\\"Automatically validate order\\" help=\\"Automatically validates orders paid with a payment terminal.\\">\\n                                    <field name=\\"pos_auto_validate_terminal_payment\\"/>\\n                                </setting>\\n                                <setting string=\\"Cash Rounding\\" invisible=\\"is_kiosk_mode\\" documentation=\\"/applications/sales/point_of_sale/pricing/cash_rounding.html\\" help=\\"Define the smallest coinage of the currency used to pay by cash\\">\\n                                    <field name=\\"pos_cash_rounding\\" readonly=\\"pos_has_active_session\\"/>\\n                                    <div class=\\"content-group mt16\\" invisible=\\"not pos_cash_rounding\\">\\n                                        <div class=\\"row mt16\\">\\n                                            <label string=\\"Rounding Method\\" for=\\"pos_rounding_method\\" class=\\"col-lg-3 o_light_label\\"/>\\n                                            <field name=\\"pos_rounding_method\\" required=\\"pos_cash_rounding\\" readonly=\\"pos_has_active_session\\" options=\\"{'no_quick_create': True}\\"/>\\n                                        </div>\\n                                        <div class=\\"row mt16\\">\\n                                            <div class=\\"col\\">\\n                                                <field name=\\"pos_only_round_cash_method\\" readonly=\\"pos_has_active_session\\"/>\\n                                                <label string=\\"Only on cash methods\\" for=\\"pos_only_round_cash_method\\" class=\\"o_light_label\\"/>\\n                                            </div>\\n                                        </div>\\n                                    </div>\\n                                    <div class=\\"mt8\\">\\n                                        <button name=\\"383\\" icon=\\"oi-arrow-right\\" type=\\"action\\" string=\\"Cash Roundings\\" class=\\"btn-link\\" invisible=\\"not group_cash_rounding\\"/>\\n                                    </div>\\n                                </setting>\\n                                <setting title=\\"Online payment, delivery payment, terminal payment, and methods that require customer identification are not supported for fast payment validation.\\" help=\\"Shortcut to skip payment screen\\" invisible=\\"is_kiosk_mode\\">\\n                                    <field name=\\"pos_use_fast_payment\\" string=\\"One-click Payment\\"/>\\n                                    <div class=\\"content-group mt16\\" invisible=\\"not pos_use_fast_payment\\">\\n                                        <label for=\\"pos_fast_payment_method_ids\\" class=\\"fw-bold me-2\\"/>\\n                                        <field name=\\"pos_fast_payment_method_ids\\" widget=\\"many2many_tags\\" string=\\"Payment Methods\\" options=\\"{'no_create': True}\\" required=\\"pos_use_fast_payment\\" domain=\\"[('id', 'in', pos_payment_method_ids), ('use_payment_terminal', '=', False), ('split_transactions', '=', False)]\\"/>\\n                                    </div>\\n                                </setting>\\n                                <setting id=\\"set_maximum_difference\\" help=\\"Set a maximum difference allowed between the expected and counted money during the closing of the session\\">\\n                                    <field name=\\"pos_set_maximum_difference\\"/>\\n                                    <div class=\\"content-group mt16\\" invisible=\\"not pos_set_maximum_difference\\">\\n                                        <label for=\\"pos_amount_authorized_diff\\" string=\\"Authorized Difference\\" class=\\"fw-normal me-1\\"/>\\n                                        <field name=\\"pos_amount_authorized_diff\\"/>\\n                                    </div>\\n                                </setting>\\n                                <setting id=\\"iface_tipproduct\\" title=\\"This product is used as reference on customer receipts.\\" string=\\"Tips\\" help=\\"Accept customer tips or convert their change to a tip\\" documentation=\\"/applications/sales/point_of_sale/restaurant/tips.html\\">\\n                                    <field name=\\"pos_iface_tipproduct\\"/>\\n                                    <div class=\\"content-group\\" invisible=\\"not pos_iface_tipproduct\\">\\n                                        <div class=\\"row mt16\\" id=\\"tip_product\\">\\n                                            <label string=\\"Tip Product\\" for=\\"pos_tip_product_id\\" class=\\"col-lg-3 o_light_label \\"/>\\n                                            <field name=\\"pos_tip_product_id\\"/>\\n                                        </div>\\n                                    </div>\\n                                </setting>\\n                            </block>\\n                            <block title=\\"PoS Interface\\" id=\\"pos_interface_section\\">\\n                                <setting id=\\"multiple_employee_session\\" title=\\"Employees can scan their badge or enter a PIN to log in to a PoS session. These credentials are configurable in the *HR Settings* tab of the employee form.\\" string=\\"Log in with Employees\\" help=\\"Allow to log and switch between selected Employees\\" documentation=\\"/applications/sales/point_of_sale/employee_login.html\\">\\n                                    <field name=\\"pos_module_pos_hr\\"/>\\n                                    <div class=\\"content-group mt16\\" invisible=\\"not pos_module_pos_hr\\">\\n                                        <div class=\\"text-warning\\" id=\\"warning_text_employees\\">\\n                                            Save this page and come back here to set up the feature.\\n                                        </div>\\n                                    </div>\\n                                </setting>\\n                                <setting invisible=\\"is_kiosk_mode\\" help=\\"Improve navigation for imprecise industrial touchscreens\\">\\n                                    <field name=\\"pos_iface_big_scrollbars\\"/>\\n                                </setting>\\n                                <setting string=\\"Share Open Orders\\" help=\\"Allow to access each other's active orders\\" id=\\"is_order_shared\\" invisible=\\"pos_module_pos_restaurant or is_kiosk_mode\\">\\n                                    <div class=\\"content-group\\">\\n                                        <div class=\\"row mt16\\">\\n                                            <label string=\\"Trusted POS\\" for=\\"pos_trusted_config_ids\\" class=\\"col-lg-3 o_light_label\\"/>\\n                                            <field name=\\"pos_trusted_config_ids\\" widget=\\"many2many_tags\\" options=\\"{'no_create':'true'}\\" placeholder=\\"Select PoS to start sharing orders\\"/>\\n                                        </div>\\n                                        <div>\\n                                            <button name=\\"554\\" icon=\\"oi-arrow-right\\" type=\\"action\\" string=\\"Point of Sales\\" class=\\"btn-link\\"/>\\n                                        </div>\\n                                    </div>\\n                                </setting>\\n                                <setting string=\\"Hide pictures in POS\\" help=\\"Self-ordering interfaces are not impacted.\\">\\n                                    <div class=\\"content-group\\">\\n                                        <div>\\n                                            <field name=\\"pos_show_product_images\\"/>\\n                                            <label for=\\"pos_show_product_images\\" string=\\"Show product images\\" class=\\"fw-normal me-1\\"/>\\n                                        </div>\\n                                        <div>\\n                                            <field name=\\"pos_show_category_images\\"/>\\n                                            <label for=\\"pos_show_category_images\\" string=\\"Show category images\\" class=\\"fw-normal me-1\\"/>\\n                                        </div>\\n                                    </div>\\n                                </setting>\\n                                <setting help=\\"Online reservation for Point of Sale\\" invisible=\\"is_kiosk_mode\\">\\n                                    <field name=\\"pos_module_pos_appointment\\" string=\\"Booking\\" widget=\\"upgrade_boolean\\"/>\\n                                    <div class=\\"content-group\\" id=\\"pos_appointment_booking\\" invisible=\\"not pos_module_pos_appointment\\">\\n                                        <div class=\\"text-warning mt16 mb4\\">\\n                                            Save this page and come back here to set up the feature.\\n                                        </div>\\n                                    </div>\\n                                </setting>\\n                                <setting invisible=\\"is_kiosk_mode\\" help=\\"Display products grouped by categories.\\">\\n                                    <field name=\\"pos_iface_group_by_categ\\"/>\\n                                </setting>\\n                            </block>\\n                            <block id=\\"product_and_category_block\\" title=\\"Product &amp; PoS categories\\">\\n                                <setting help=\\"Pick which product PoS categories are available\\">\\n                                    <field name=\\"pos_limit_categories\\"/>\\n                                    <div class=\\"content-group mt16\\" invisible=\\"not pos_limit_categories\\">\\n                                        <field name=\\"pos_iface_available_categ_ids\\" widget=\\"many2many_tags\\"/>\\n                                    </div>\\n                                    <div class=\\"content-group mt16\\" invisible=\\"not pos_limit_categories\\">\\n                                        <button name=\\"544\\" icon=\\"oi-arrow-right\\" type=\\"action\\" string=\\"PoS Product Categories\\" class=\\"btn-link\\"/>\\n                                    </div>\\n                                </setting>\\n                                <setting id=\\"margin_and_cost\\" string=\\"Show margins &amp; costs\\" help=\\"Show margins &amp; costs on product information\\">\\n                                    <field name=\\"pos_is_margins_costs_accessible_to_every_user\\"/>\\n                                </setting>\\n                            </block>\\n                            <block title=\\"Accounting\\" id=\\"pos_accounting_section\\">\\n                                <setting id=\\"default_sales_tax_setting\\" title=\\"This tax is applied to any new product created in the catalog.\\" documentation=\\"/applications/finance/accounting/taxation/taxes/default_taxes.html\\">\\n                                    <label string=\\"Default Sales Tax\\" for=\\"sale_tax_id\\"/>\\n                                    <i class=\\"fa fa-info-circle me-1\\" title=\\"This setting is common to all PoS.\\" pos-data-toggle=\\"tooltip\\"/>\\n                                    <div class=\\"text-muted\\">\\n                                        Default sales tax for products\\n                                    </div>\\n                                    <div class=\\"content-group mt16\\">\\n                                        <field name=\\"sale_tax_id\\" colspan=\\"4\\" nolabel=\\"1\\" domain=\\"[('type_tax_use', 'in', ('sale', 'all'))]\\"/>\\n                                    </div>\\n                                    <div class=\\"mt8\\">\\n                                        <button name=\\"373\\" icon=\\"oi-arrow-right\\" type=\\"action\\" string=\\"Taxes\\" class=\\"btn-link\\"/>\\n                                    </div>\\n                                </setting>\\n                                <setting groups=\\"account.group_account_readonly\\">\\n                                    <label string=\\"Default POS Receivable Account\\" for=\\"account_default_pos_receivable_account_id\\"/>\\n                                    <i class=\\"fa fa-info-circle me-1\\" title=\\"This setting is common to all PoS.\\" pos-data-toggle=\\"tooltip\\"/>\\n                                    <div class=\\"text-muted\\">\\n                                        Intermediary account used for unidentified customers.\\n                                    </div>\\n                                    <field name=\\"account_default_pos_receivable_account_id\\" colspan=\\"4\\" nolabel=\\"1\\" domain=\\"[('reconcile', '=', True), ('account_type', '=', 'asset_receivable')]\\"/>\\n                                </setting>\\n                                <setting id=\\"order_edit_tracking\\" help=\\"Store edited orders in the backend\\">\\n                                    <field name=\\"pos_order_edit_tracking\\"/>\\n                                </setting>\\n                                <setting id=\\"flexible_taxes\\" invisible=\\"pos_use_presets\\" title=\\"Choose a specific fiscal position at the order depending on the kind of customer (tax exempt, onsite vs. takeaway, etc.).\\" string=\\"Flexible Taxes\\" help=\\"Use fiscal positions to get different taxes by order\\" documentation=\\"/applications/sales/point_of_sale/pricing/fiscal_position.html\\">\\n                                    <field name=\\"pos_tax_regime_selection\\"/>\\n                                    <div class=\\"content-group mt16\\" invisible=\\"not pos_tax_regime_selection\\">\\n                                        <div class=\\"row\\">\\n                                            <label string=\\"Default\\" for=\\"pos_default_fiscal_position_id\\" class=\\"col-lg-3 o_light_label\\"/>\\n                                            <field name=\\"pos_default_fiscal_position_id\\"/>\\n                                        </div>\\n                                        <div class=\\"row\\">\\n                                            <label string=\\"Allowed\\" for=\\"pos_fiscal_position_ids\\" class=\\"col-lg-3 o_light_label\\"/>\\n                                            <field name=\\"pos_fiscal_position_ids\\" widget=\\"many2many_tags\\" options=\\"{'no_create': True}\\"/>\\n                                        </div>\\n                                        <div>\\n                                            <button name=\\"388\\" icon=\\"oi-arrow-right\\" type=\\"action\\" string=\\"Fiscal Positions\\" class=\\"btn-link\\"/>\\n                                        </div>\\n                                    </div>\\n                                </setting>\\n                                <setting string=\\"Default Journals\\" id=\\"pos_default_journals\\" help=\\"Default journals for orders and invoices\\">\\n                                    <div class=\\"content-group mt16\\">\\n                                        <div class=\\"row\\" title=\\"Whenever you close a session, one entry is generated in the following accounting journal for all the orders not invoiced. Invoices are recorded in accounting separately.\\">\\n                                            <label string=\\"Orders\\" for=\\"pos_journal_id\\" class=\\"col-lg-3 o_light_label\\" options=\\"{'no_open': True, 'no_create': True}\\"/>\\n                                            <field name=\\"pos_journal_id\\" domain=\\"[('company_id', '=', company_id), ('type', 'in', ('general', 'sale'))]\\" context=\\"{'default_company_id': company_id, 'default_type': 'general'}\\" required=\\"pos_company_has_template\\"/>\\n                                        </div>\\n                                        <div class=\\"row\\">\\n                                            <label string=\\"Invoices\\" for=\\"pos_invoice_journal_id\\" class=\\"col-lg-3 o_light_label\\"/>\\n                                            <field name=\\"pos_invoice_journal_id\\" domain=\\"[('company_id', '=', company_id), ('type', '=', 'sale')]\\" context=\\"{'default_company_id': company_id, 'default_type': 'sale'}\\"/>\\n                                        </div>\\n                                    </div>\\n                                </setting>\\n                                <setting string=\\"Closing Entry by product\\" id=\\"pos_closeing_entry_by_product\\" help=\\"Display the breakdown of sales lines by product in the automatically generated closing entry.\\">\\n                                    <field name=\\"pos_is_closing_entry_by_product\\"/>\\n                                </setting>\\n                                <setting id=\\"pos-avatax\\" help=\\"Use automatic taxes mapping with Avatax\\">\\n                                    <field name=\\"pos_module_pos_avatax\\"/>\\n                                </setting>\\n                            </block>\\n\\n                            <block title=\\"Pricing\\" id=\\"pos_pricing_section\\">\\n                                <setting id=\\"multiple_prices_setting\\" string=\\"Flexible Pricelists\\" help=\\"Set multiple prices per product, automated discounts, etc.\\" documentation=\\"/applications/sales/point_of_sale/pricing/pricelists.html\\">\\n                                    <field name=\\"pos_use_pricelist\\"/>\\n                                    <div class=\\"content-group\\" invisible=\\"not pos_use_pricelist\\">\\n                                        <div class=\\"row mt16\\">\\n                                            <label string=\\"Available\\" for=\\"pos_available_pricelist_ids\\" class=\\"col-lg-3 o_light_label\\"/>\\n                                            <field name=\\"pos_available_pricelist_ids\\" widget=\\"many2many_tags\\" domain=\\"['|',('company_id', '=', company_id),('company_id', '=', False)]\\"/>\\n                                        </div>\\n                                        <div class=\\"row mt16\\">\\n                                            <label string=\\"Default\\" for=\\"pos_pricelist_id\\" class=\\"col-lg-3 o_light_label\\"/>\\n                                            <field name=\\"pos_pricelist_id\\" domain=\\"[('id', 'in', pos_allowed_pricelist_ids)]\\" options=\\"{'no_create': True}\\"/>\\n                                        </div>\\n                                        <div class=\\"mt8\\">\\n                                            <button name=\\"172\\" icon=\\"oi-arrow-right\\" type=\\"action\\" string=\\"Pricelists\\" groups=\\"product.group_product_pricelist\\" class=\\"btn-link\\"/>\\n                                        </div>\\n                                    </div>\\n                                </setting>\\n                                <setting id=\\"price_control\\" class=\\"price_control\\" title=\\"Only users with Manager access rights for PoS app can modify the product prices on orders.\\" string=\\"Price Control\\" help=\\"Restrict price modification to managers\\">\\n                                    <field name=\\"pos_restrict_price_control\\"/>\\n                                </setting>\\n                                <setting id=\\"product_prices\\" string=\\"Product Prices\\" help=\\"Product prices on receipts\\">\\n                                    <field name=\\"pos_iface_tax_included\\" class=\\"o_light_label\\" widget=\\"radio\\"/>\\n                                    <div class=\\"content-group\\">\\n                                        <widget class=\\"oe-link\\" name=\\"documentation_link\\" path=\\"/applications/finance/accounting/taxation/taxes/B2B_B2C.html\\" label=\\"How to manage tax-included prices\\" icon=\\"oi oi-fw oi-arrow-right\\"/>\\n                                    </div>\\n                                </setting>\\n                                <setting id=\\"manual_discount\\" help=\\"Allow cashiers to set a discount per line\\" documentation=\\"/applications/sales/point_of_sale/pricing/discounts.html\\">\\n                                    <field name=\\"pos_manual_discount\\"/>\\n                                </setting>\\n                                <setting id=\\"pos_global_discount\\" help=\\"Adds a button to set a global discount\\" documentation=\\"/applications/sales/point_of_sale/pricing/discounts.html\\">\\n                                    <field name=\\"pos_module_pos_discount\\"/>\\n                                    <div class=\\"content-group mt16\\" invisible=\\"not pos_module_pos_discount\\">\\n                                        <div class=\\"text-warning mb4\\" id=\\"warning_text_pos_discount\\">\\n                                            Save this page and come back here to set up the feature.\\n                                        </div>\\n                                    </div>\\n                                </setting>\\n                                <setting id=\\"pos_pricer\\" string=\\"Pricer\\" title=\\"Pricer tags\\" help=\\"Display and update your products information through electronic price tags\\">\\n                                    <field name=\\"module_pos_pricer\\"/>\\n                                </setting>\\n                                <setting id=\\"pos-loyalty\\" title=\\"Boost your sales with multiple kinds of programs: Coupons, Promotions, Gift Card, Loyalty. Specific conditions can be set (products, customers, minimum purchase amount, period). Rewards can be discounts (% or amount) or free products.\\" string=\\"Promotions, Coupons, Gift Card &amp; Loyalty Program\\" help=\\"Manage promotion that will grant customers discounts or gifts\\" documentation=\\"/applications/sales/point_of_sale/pricing/loyalty.html\\">\\n                                    <field name=\\"module_loyalty\\"/>\\n                                </setting>\\n                            </block>\\n\\n                            <block title=\\"Bills &amp; Receipts\\" id=\\"pos_bills_and_receipts_section\\">\\n                                <setting help=\\"Add a custom message to header and footer\\" documentation=\\"/applications/sales/point_of_sale/receipts_invoices.html\\">\\n                                    <field name=\\"pos_is_header_or_footer\\"/>\\n                                    <div class=\\"content-group mt16\\" invisible=\\"not pos_is_header_or_footer\\">\\n                                        <div>\\n                                            <label string=\\"Header\\" for=\\"pos_receipt_header\\" class=\\"col-lg-2 o_light_label\\"/>\\n                                            <field name=\\"pos_receipt_header\\" placeholder=\\"e.g. Company Address, Website\\"/>\\n                                        </div>\\n                                        <div>\\n                                            <label string=\\"Footer\\" for=\\"pos_receipt_footer\\" class=\\"col-lg-2 o_light_label\\"/>\\n                                            <field name=\\"pos_receipt_footer\\" placeholder=\\"e.g. Return Policy, Thanks for shopping with us!\\"/>\\n                                        </div>\\n                                    </div>\\n                                </setting>\\n                                <setting id=\\"auto_printing\\" help=\\"Print receipts automatically once the payment is registered\\" documentation=\\"/applications/sales/point_of_sale/receipts_invoices.html\\">\\n                                    <field name=\\"pos_iface_print_auto\\"/>\\n                                    <div class=\\"content-group mt16\\" invisible=\\"not pos_iface_print_auto or not pos_is_posbox and not pos_other_devices\\">\\n                                        <div>\\n                                            <field name=\\"pos_iface_print_skip_screen\\" class=\\"oe_inline\\"/><span class=\\"oe_inline\\"><b>Skip Preview Screen</b></span>\\n                                        </div>\\n                                    </div>\\n                                </setting>\\n                                <setting id=\\"pos_sms\\" help=\\"Send Text receipt Using sms\\">\\n                                    <field name=\\"pos_module_pos_sms\\"/>\\n                                    <div class=\\"content-group\\" readonly=\\"pos_has_active_session\\">\\n                                        <div class=\\"content-group mt16\\" invisible=\\"not pos_module_pos_sms\\">\\n                                            <div class=\\"text-warning mb4\\" id=\\"warning_text_pos_sms\\">\\n                                                Save this page and come back here to set up the feature.\\n                                            </div>\\n                                        </div>\\n                                    </div>\\n                                </setting>\\n                                <setting help=\\"Print information on the receipt to allow the customer to easily access the invoice anytime, from Odoo's portal.\\" documentation=\\"/applications/sales/point_of_sale/receipts_invoices.html\\" id=\\"pos_use_ticket_qr_code\\">\\n                                    <field name=\\"point_of_sale_use_ticket_qr_code\\"/>\\n                                    <div class=\\"content-group mt16\\" invisible=\\"not point_of_sale_use_ticket_qr_code\\">\\n                                        <div class=\\"col mt16\\">\\n                                            <div class=\\"content-group row\\">\\n                                                <label for=\\"point_of_sale_ticket_portal_url_display_mode\\" class=\\"col-lg-2\\" string=\\"Print\\"/>\\n                                                <field name=\\"point_of_sale_ticket_portal_url_display_mode\\"/>\\n                                            </div>\\n                                        </div>\\n                                    </div>\\n                                </setting>\\n                                <setting id=\\"basic_receipt\\" help=\\"Print basic ticket without prices. Can be used for gifts.\\">\\n                                    <field name=\\"pos_basic_receipt\\"/>\\n                                </setting>\\n                            </block>\\n\\n                            <block title=\\"Payment Terminals\\" help=\\"Those settings are common to all PoS.\\" id=\\"pos_payment_terminals_section\\">\\n                                <setting id=\\"adyen_payment_terminal_setting\\" title=\\"The transactions are processed by Adyen. Set your Adyen credentials on the related payment method.\\" string=\\"Adyen\\" help=\\"Accept payments with an Adyen payment terminal\\" documentation=\\"/applications/sales/point_of_sale/payment_methods/terminals/adyen.html\\">\\n                                    <field name=\\"module_pos_adyen\\"/>\\n                                    <button name=\\"open_payment_method_form\\" icon=\\"oi-arrow-right\\" type=\\"object\\" string=\\"Payment method\\" class=\\"btn-link\\" context=\\"{'selection': 'adyen', 'config_ids': [pos_config_id], 'provider_name': 'Adyen'}\\" invisible=\\"not module_pos_adyen\\"/>\\n                                </setting>\\n                                <setting id=\\"stripe_payment_terminal_setting\\" title=\\"The transactions are processed by Stripe. Set your Stripe credentials on the related payment method.\\" string=\\"Stripe\\" help=\\"Accept payments with a Stripe payment terminal\\" documentation=\\"/applications/sales/point_of_sale/payment_methods/terminals/stripe.html\\">\\n                                    <field name=\\"module_pos_stripe\\"/>\\n                                    <button name=\\"open_payment_method_form\\" icon=\\"oi-arrow-right\\" type=\\"object\\" string=\\"Payment method\\" class=\\"btn-link\\" context=\\"{'selection': 'stripe', 'config_ids': [pos_config_id], 'provider_name': 'Stripe'}\\" invisible=\\"not module_pos_stripe\\"/>\\n                                </setting>\\n                                <setting title=\\"The transactions are processed by Viva.com on terminal or tap on phone.\\" string=\\"Viva.com\\" help=\\"Accept payments with Viva.com on a terminal or tap on phone\\" documentation=\\"/applications/sales/point_of_sale/payment_methods/terminals/viva_com.html\\">\\n                                    <field name=\\"module_pos_viva_com\\"/>\\n                                    <button name=\\"open_payment_method_form\\" icon=\\"oi-arrow-right\\" type=\\"object\\" string=\\"Payment method\\" class=\\"btn-link\\" context=\\"{'selection': 'viva_com', 'config_ids': [pos_config_id], 'provider_name': 'Viva.com'}\\" invisible=\\"not module_pos_viva_com\\"/>\\n                                </setting>\\n                                <setting id=\\"pos_razorpay_setting\\" title=\\"The transactions are processed by Razorpay. Set your Razorpay credentials on the related payment method.\\" string=\\"Razorpay\\" help=\\"Accept payments with a Razorpay payment terminal\\" documentation=\\"/applications/sales/point_of_sale/payment_methods/terminals/razorpay.html\\">\\n                                    <field name=\\"module_pos_razorpay\\"/>\\n                                    <button name=\\"open_payment_method_form\\" icon=\\"oi-arrow-right\\" type=\\"object\\" string=\\"Payment method\\" class=\\"btn-link\\" context=\\"{'selection': 'razorpay', 'config_ids': [pos_config_id], 'provider_name': 'Razorpay'}\\" invisible=\\"not module_pos_razorpay\\"/>\\n                                </setting>\\n                                <setting title=\\"The transactions are processed by Mercado Pago on terminal\\" string=\\"Mercado Pago\\" help=\\"Accept payments with Mercado Pago on a terminal\\" documentation=\\"/applications/sales/point_of_sale/payment_methods/terminals/mercado_pago.html\\">\\n                                    <field name=\\"module_pos_mercado_pago\\"/>\\n                                    <button name=\\"open_payment_method_form\\" icon=\\"oi-arrow-right\\" type=\\"object\\" string=\\"Payment method\\" class=\\"btn-link\\" context=\\"{'selection': 'mercado_pago', 'config_ids': [pos_config_id], 'provider_name': 'Mercado Pago'}\\" invisible=\\"not module_pos_mercado_pago\\"/>\\n                                </setting>\\n                                <setting title=\\"The transactions are processed by Pine Labs on the terminal.\\" string=\\"Pine Labs\\" help=\\"Accept payments with a Pine Labs payment terminal\\" documentation=\\"/applications/sales/point_of_sale/payment_methods/terminals/pine_labs.html\\">\\n                                    <field name=\\"module_pos_pine_labs\\"/>\\n                                    <button name=\\"open_payment_method_form\\" icon=\\"oi-arrow-right\\" type=\\"object\\" string=\\"Payment method\\" class=\\"btn-link\\" context=\\"{'selection': 'pine_labs', 'config_ids': [pos_config_id], 'provider_name': 'Pine Labs'}\\" invisible=\\"not module_pos_pine_labs\\"/>\\n                                </setting>\\n                                <setting title=\\"The transactions are processed by QFPay on the terminal.\\" string=\\"QFPay\\" help=\\"Accept payments with a QFPay payment terminal\\" documentation=\\"/applications/sales/point_of_sale/payment_methods/terminals/qfpay.html\\">\\n                                    <field name=\\"module_pos_qfpay\\"/>\\n                                    <button name=\\"open_payment_method_form\\" icon=\\"oi-arrow-right\\" type=\\"object\\" string=\\"Payment method\\" class=\\"btn-link\\" context=\\"{'selection': 'qfpay', 'config_ids': [pos_config_id], 'provider_name': 'QFPay'}\\" invisible=\\"not module_pos_qfpay\\"/>\\n                                </setting>\\n                            </block>\\n\\n                            <block title=\\"Connected Devices\\" id=\\"pos_connected_devices_section\\">\\n                                <setting id=\\"pos_other_devices\\" string=\\"ePos Printer\\" help=\\"Connect device to your PoS without an IoT Box\\" documentation=\\"/applications/sales/point_of_sale/configuration/epos_ssc.html\\">\\n                                    <field name=\\"pos_other_devices\\"/>\\n                                    <div class=\\"row\\" invisible=\\"not pos_other_devices\\">\\n                                        <div class=\\"col-lg-6\\">\\n                                            <field name=\\"pos_epson_printer_ip\\" placeholder=\\"Epson Receipt Printer IP Address\\" class=\\"w-100 pt-1\\"/>\\n                                        </div>\\n                                        <div class=\\"col-lg-6\\">\\n                                            <widget name=\\"point_of_sale_test_epos\\"/>\\n                                        </div>\\n                                        <div class=\\"col-12 mt-2\\">\\n                                            <div class=\\"row\\" invisible=\\"pos_epson_printer_ip in [False, '']\\">\\n                                                <label string=\\"Link Cashdrawer\\" for=\\"pos_iface_cashdrawer\\" class=\\"col-lg-4 o_light_label\\"/>\\n                                                <field name=\\"pos_iface_cashdrawer\\" class=\\"col\\"/>\\n                                            </div>\\n                                        </div>\\n                                    </div>\\n                                    <div role=\\"alert\\" class=\\"alert alert-warning\\" invisible=\\"not pos_iface_print_via_proxy or not pos_other_devices or pos_epson_printer_ip in [False, '']\\">\\n                                        The Epson receipt printer will be used instead of the receipt printer connected to the IoT Box.\\n                                    </div>\\n                                </setting>\\n                                <setting id=\\"customer_display\\" string=\\"Customer Display\\" help=\\"Set the background image of your customer display\\" documentation=\\"/applications/sales/point_of_sale/shop/customer_display.html\\">\\n                                    <label for=\\"pos_customer_display_bg_img\\"/>\\n                                    <field name=\\"pos_customer_display_bg_img\\" class=\\"w-100\\" filename=\\"pos_customer_display_bg_img_name\\"/>\\n                                </setting>\\n                                <setting string=\\"IoT Box\\" help=\\"Connect devices using an IoT Box\\">\\n                                    <field name=\\"pos_is_posbox\\"/>\\n                                    <div class=\\"content-group pos_iot_config\\" invisible=\\"not pos_is_posbox\\">\\n                                        <div class=\\"row\\">\\n                                            <label string=\\"IoT Box IP Address\\" for=\\"pos_proxy_ip\\" class=\\"col-lg-4 o_light_label\\"/>\\n                                            <field name=\\"pos_proxy_ip\\"/>\\n                                        </div>\\n                                        <div class=\\"row iot_barcode_scanner\\">\\n                                            <label string=\\"Barcode Scanner/Card Reader\\" for=\\"pos_iface_scan_via_proxy\\" class=\\"col-lg-4 o_light_label\\"/>\\n                                            <field name=\\"pos_iface_scan_via_proxy\\"/>\\n                                        </div>\\n                                        <div class=\\"row\\">\\n                                            <label string=\\"Electronic Scale\\" for=\\"pos_iface_electronic_scale\\" class=\\"col-lg-4 o_light_label\\"/>\\n                                            <field name=\\"pos_iface_electronic_scale\\"/>\\n                                        </div>\\n                                        <div class=\\"row\\">\\n                                            <label string=\\"Receipt Printer\\" for=\\"pos_iface_print_via_proxy\\" class=\\"col-lg-4 o_light_label\\"/>\\n                                            <field name=\\"pos_iface_print_via_proxy\\"/>\\n                                        </div>\\n                                        <div class=\\"row\\" invisible=\\"not pos_iface_print_via_proxy\\">\\n                                            <label string=\\"Cashdrawer\\" for=\\"pos_iface_cashdrawer\\" class=\\"col-lg-4 o_light_label\\"/>\\n                                            <field name=\\"pos_iface_cashdrawer\\"/>\\n                                        </div>\\n                                    </div>\\n                                </setting>\\n                            </block>\\n\\n                            <block title=\\"Preparation\\" id=\\"pos_preparation_section\\">\\n                                <setting string=\\"Preparation Printers\\" help=\\"Print orders at the kitchen, at the bar, etc.\\" id=\\"is_order_printer\\">\\n                                    <field name=\\"pos_is_order_printer\\"/>\\n                                    <div class=\\"content-group\\" invisible=\\"not pos_is_order_printer\\">\\n                                        <div class=\\"mt16 mb-1\\">\\n                                            <label string=\\"Printers\\" for=\\"pos_printer_ids\\" class=\\"o_light_label me-2\\"/>\\n                                            <field name=\\"pos_printer_ids\\" widget=\\"many2many_tags\\"/>\\n                                        </div>\\n                                        <div>\\n                                            <button name=\\"action_pos_printer_dialog\\" context=\\"{'default_pos_config_ids': [pos_config_id]}\\" icon=\\"oi-arrow-right\\" type=\\"object\\" string=\\"Add Printer\\" class=\\"btn-link\\"/>\\n                                        </div>\\n                                        <div>\\n                                            <button name=\\"566\\" icon=\\"oi-arrow-right\\" type=\\"action\\" string=\\"Manage Printers\\" class=\\"btn-link\\"/>\\n                                        </div>\\n                                    </div>\\n                                </setting>\\n                                <setting string=\\"Internal Notes\\" help=\\"Add internal notes on order lines for the kitchen\\" id=\\"iface_orderline_notes\\">\\n                                    <div class=\\"content-group\\">\\n                                        <div class=\\"mt16\\">\\n                                            <label string=\\"Note Models\\" for=\\"pos_note_ids\\" class=\\"o_light_label me-2\\"/>\\n                                            <field name=\\"pos_note_ids\\" widget=\\"many2many_tags\\" readonly=\\"pos_has_active_session\\" placeholder=\\"All notes\\"/>\\n                                        </div>\\n                                        <div>\\n                                            <button name=\\"535\\" icon=\\"oi-arrow-right\\" type=\\"action\\" string=\\"Notes\\" class=\\"btn-link\\"/>\\n                                        </div>\\n                                    </div>\\n                                </setting>\\n                            </block>\\n\\n                            <block title=\\"Inventory\\" id=\\"pos_inventory_section\\">\\n                                <setting title=\\"Operation types show up in the Inventory dashboard.\\" string=\\"Operation Type\\" help=\\"Used to record product pickings. Products are consumed from its default source location.\\">\\n                                    <field name=\\"pos_picking_type_id\\" domain=\\"[('company_id', '=', company_id)]\\" required=\\"pos_config_id\\"/>\\n                                </setting>\\n                                <setting id=\\"ship_later\\" string=\\"Allow Ship Later\\" help=\\"Sell products and deliver them later.\\">\\n                                    <field name=\\"pos_ship_later\\"/>\\n                                    <div class=\\"content-group mt16\\" invisible=\\"not pos_ship_later\\">\\n                                        <div class=\\"row\\">\\n                                            <label for=\\"pos_warehouse_id\\" string=\\"Warehouse\\" class=\\"col-lg-3 o_light_label\\"/>\\n                                            <field name=\\"pos_warehouse_id\\" required=\\"pos_ship_later\\"/>\\n                                        </div>\\n                                        <div groups=\\"stock.group_adv_location\\" class=\\"row\\">\\n                                            <label for=\\"pos_route_id\\" string=\\"Specific route\\" class=\\"col-lg-3 o_light_label\\"/>\\n                                            <field name=\\"pos_route_id\\"/>\\n                                        </div>\\n                                        <div class=\\"row\\">\\n                                            <label for=\\"pos_picking_policy\\" class=\\"col-lg-3 o_light_label\\"/>\\n                                            <field name=\\"pos_picking_policy\\" required=\\"pos_ship_later\\"/>\\n                                        </div>\\n                                    </div>\\n                                </setting>\\n                                <setting id=\\"barcode_scanner\\">\\n                                    <span class=\\"o_form_label\\">Barcodes</span>\\n                                    <i class=\\"fa fa-info-circle me-1\\" title=\\"This setting is common to all PoS.\\" pos-data-toggle=\\"tooltip\\"/>\\n                                    <div class=\\"text-muted\\">\\n                                        Use barcodes to scan products, customer cards, etc.\\n                                    </div>\\n                                    <div class=\\"content-group mt16 row\\">\\n                                        <label for=\\"barcode_nomenclature_id\\" string=\\"Barcode Nomenclature\\" class=\\"col-lg-3 o_light_label\\"/>\\n                                        <field name=\\"barcode_nomenclature_id\\"/>\\n                                    </div>\\n                                    <div class=\\"content-group mt16 row\\">\\n                                        <label for=\\"pos_fallback_nomenclature_id\\" string=\\"Fallback Nomenclature\\" class=\\"col-lg-3 o_light_label\\"/>\\n                                        <field name=\\"pos_fallback_nomenclature_id\\"/>\\n                                    </div>\\n                                </setting>\\n                                <setting id=\\"update_quantities_stock_setting\\" groups=\\"base.group_no_one\\" string=\\"Inventory Management\\" company_dependent=\\"1\\" help=\\"Update quantities in stock\\">\\n                                    <field name=\\"update_stock_quantities\\" colspan=\\"4\\" widget=\\"radio\\"/>\\n                                </setting>\\n                            </block>\\n                        </div>\\n                    </div>\\n                    </div>\\n                </app>\\n            </xpath>", "es_ES": "<xpath expr=\\"//form\\" position=\\"inside\\">\\n                <t groups=\\"point_of_sale.group_pos_manager\\">\\n                    <field name=\\"is_kiosk_mode\\" invisible=\\"1\\"/>\\n                    <field name=\\"pos_selectable_categ_ids\\" invisible=\\"1\\"/>\\n                    <field name=\\"pos_has_active_session\\" invisible=\\"1\\"/>\\n                    <field name=\\"pos_allowed_pricelist_ids\\" invisible=\\"1\\"/>\\n                    <field name=\\"pos_cash_control\\" invisible=\\"1\\"/>\\n                    <field name=\\"pos_iface_print_via_proxy\\" invisible=\\"1\\"/>\\n                    <field name=\\"pos_company_has_template\\" invisible=\\"1\\"/>\\n                    <field name=\\"group_cash_rounding\\" invisible=\\"1\\"/>\\n                </t>\\n\\n                <app data-string=\\"Point of sale\\" string=\\"Punto de venta\\" name=\\"point_of_sale\\" groups=\\"point_of_sale.group_pos_manager\\">\\n                    <div class=\\"pos_res_config_container\\">\\n                    <div class=\\"sticky-top w-100 bg-white\\">\\n                        <setting type=\\"header\\" string=\\"Punto de venta\\" class=\\"bg-warning\\">\\n                            <field name=\\"pos_config_id\\" options=\\"{'no_open': True, 'no_create': True}\\" title=\\"Los ajustes en esta página se aplicarán a este punto de venta.\\"/>\\n                            <button name=\\"action_pos_config_create_new\\" type=\\"object\\" string=\\"+ Nueva tienda\\" class=\\"btn btn-link\\"/>\\n                        </setting>\\n                    </div>\\n\\n                    <div class=\\"pos_config_content\\">\\n                        <div class=\\"o_view_nocontent\\" invisible=\\"pos_config_id\\">\\n                            <div class=\\"o_nocontent_help\\">\\n                                <p class=\\"o_view_nocontent_empty_folder\\">Sin punto de venta seleccionado</p>\\n                                <p>Cree o seleccione un punto de venta para mostrar las opciones de configuración.</p>\\n                            </div>\\n                        </div>\\n                        <div class=\\"o_notification_alert alert alert-warning mt-1 mb-0\\" invisible=\\"not pos_has_active_session\\" role=\\"alert\\">\\n                            Actualmente hay una sesión abierta para este TPV. Algunas configuraciones solo se pueden cambiar después de que se cierra la sesión.\\n                            <button class=\\"btn-link\\" style=\\"padding:0\\" name=\\"pos_close_ui\\" type=\\"object\\" context=\\"{'pos_config_id': pos_config_id}\\">Haga clic aquí para cerrar la sesión</button>\\n                        </div>\\n                        <div class=\\"o_notification_alert alert alert-warning\\" invisible=\\"pos_company_has_template or chart_template\\" role=\\"alert\\">\\n                            No hay un plan contable configurado en la compañía. Vaya a la configuración de facturación para instalar un plan contable.\\n                        </div>\\n                        <div invisible=\\"not pos_config_id\\">\\n                            <block title=\\"Punto de venta\\" id=\\"restaurant_section\\">\\n                                <!-- Wrap the warnings in an o_setting_box so that it doesn't show in the search. -->\\n                                <setting id=\\"is_restaurant\\">\\n                                    <field name=\\"pos_module_pos_restaurant\\" readonly=\\"pos_has_active_session\\"/>\\n                                    <div class=\\"content-group\\" id=\\"warning_text_pos_restaurant\\" invisible=\\"not pos_module_pos_restaurant\\">\\n                                        <div class=\\"text-warning mt16 mb4\\">\\n                                            Guarde esta página y luego regrese para configurar la función.\\n                                        </div>\\n                                    </div>\\n                                </setting>\\n                                <setting string=\\"Para llevar / Entrega / Miembros\\" help=\\"Defina los preajustes para gestionar los impuestos y precios para comer en el restaurante, para llevar, para los miembros etc.\\">\\n                                    <field name=\\"pos_use_presets\\"/>\\n                                    <div class=\\"content-group\\" invisible=\\"not pos_use_presets\\">\\n                                        <div class=\\"row\\">\\n                                            <label for=\\"pos_available_preset_ids\\" class=\\"col-lg-3\\" string=\\"Disponible\\"/>\\n                                            <field name=\\"pos_available_preset_ids\\" widget=\\"many2many_tags\\" options=\\"{'no_quick_create': True, 'color_field': 'color'}\\"/>\\n                                        </div>\\n                                        <div class=\\"row\\">\\n                                            <label for=\\"pos_default_preset_id\\" class=\\"col-lg-3\\" string=\\"Por defecto\\"/>\\n                                            <field name=\\"pos_default_preset_id\\" options=\\"{'no_create': True}\\" required=\\"pos_use_presets\\" domain=\\"[('id', 'in', pos_available_preset_ids)]\\"/>\\n                                        </div>\\n                                        <div>\\n                                            <button name=\\"562\\" icon=\\"oi-arrow-right\\" type=\\"action\\" string=\\"Configurar ajustes preestablecidos\\" class=\\"btn-link\\"/>\\n                                        </div>\\n                                    </div>\\n                                </setting>\\n                            </block>\\n                            <block title=\\"Pago\\" id=\\"pos_payment_section\\">\\n                                <setting id=\\"payment_methods_new\\" string=\\"Métodos de pago\\" help=\\"Métodos de pago disponibles\\" documentation=\\"/applications/sales/point_of_sale/payment_methods.html\\">\\n                                    <field name=\\"pos_payment_method_ids\\" colspan=\\"4\\" widget=\\"many2many_tags\\" readonly=\\"pos_has_active_session\\" required=\\"pos_company_has_template\\" options=\\"{'no_quick_create': True}\\" context=\\"{'default_config_ids': [pos_config_id], 'form_view_ref': 'point_of_sale.action_pos_payment_method_form' }\\"/>\\n                                    <div>\\n                                        <button name=\\"551\\" icon=\\"oi-arrow-right\\" type=\\"action\\" string=\\"Métodos de pago\\" class=\\"btn-link\\"/>\\n                                    </div>\\n                                </setting>\\n                                <setting string=\\"Validar automáticamente el pedido\\" help=\\"Valida automáticamente los pedidos pagados con una terminal de pago.\\">\\n                                    <field name=\\"pos_auto_validate_terminal_payment\\"/>\\n                                </setting>\\n                                <setting string=\\"Redondeo de efectivo\\" invisible=\\"is_kiosk_mode\\" documentation=\\"/applications/sales/point_of_sale/pricing/cash_rounding.html\\" help=\\"Defina la moneda más pequeña de la moneda que se utiliza para pagar en efectivo\\">\\n                                    <field name=\\"pos_cash_rounding\\" readonly=\\"pos_has_active_session\\"/>\\n                                    <div class=\\"content-group mt16\\" invisible=\\"not pos_cash_rounding\\">\\n                                        <div class=\\"row mt16\\">\\n                                            <label string=\\"Método de redondeo\\" for=\\"pos_rounding_method\\" class=\\"col-lg-3 o_light_label\\"/>\\n                                            <field name=\\"pos_rounding_method\\" required=\\"pos_cash_rounding\\" readonly=\\"pos_has_active_session\\" options=\\"{'no_quick_create': True}\\"/>\\n                                        </div>\\n                                        <div class=\\"row mt16\\">\\n                                            <div class=\\"col\\">\\n                                                <field name=\\"pos_only_round_cash_method\\" readonly=\\"pos_has_active_session\\"/>\\n                                                <label string=\\"Solo para métodos de efectivo\\" for=\\"pos_only_round_cash_method\\" class=\\"o_light_label\\"/>\\n                                            </div>\\n                                        </div>\\n                                    </div>\\n                                    <div class=\\"mt8\\">\\n                                        <button name=\\"383\\" icon=\\"oi-arrow-right\\" type=\\"action\\" string=\\"Redondeos de Efectivo\\" class=\\"btn-link\\" invisible=\\"not group_cash_rounding\\"/>\\n                                    </div>\\n                                </setting>\\n                                <setting title=\\"El pago en línea, el pago en el momento de la entrega, el pago en terminal y los métodos que requieren la identificación del cliente no son compatibles con la validación rápida de pagos.\\" help=\\"Atajo para omitir la pantalla de pago\\" invisible=\\"is_kiosk_mode\\">\\n                                    <field name=\\"pos_use_fast_payment\\" string=\\"Pago con un solo clic\\"/>\\n                                    <div class=\\"content-group mt16\\" invisible=\\"not pos_use_fast_payment\\">\\n                                        <label for=\\"pos_fast_payment_method_ids\\" class=\\"fw-bold me-2\\"/>\\n                                        <field name=\\"pos_fast_payment_method_ids\\" widget=\\"many2many_tags\\" string=\\"Métodos de pago\\" options=\\"{'no_create': True}\\" required=\\"pos_use_fast_payment\\" domain=\\"[('id', 'in', pos_payment_method_ids), ('use_payment_terminal', '=', False), ('split_transactions', '=', False)]\\"/>\\n                                    </div>\\n                                </setting>\\n                                <setting id=\\"set_maximum_difference\\" help=\\"Establezca una diferencia máxima permitida entre el dinero esperado y el dinero contado durante el cierre de la sesión\\">\\n                                    <field name=\\"pos_set_maximum_difference\\"/>\\n                                    <div class=\\"content-group mt16\\" invisible=\\"not pos_set_maximum_difference\\">\\n                                        <label for=\\"pos_amount_authorized_diff\\" string=\\"Diferencia autorizada\\" class=\\"fw-normal me-1\\"/>\\n                                        <field name=\\"pos_amount_authorized_diff\\"/>\\n                                    </div>\\n                                </setting>\\n                                <setting id=\\"iface_tipproduct\\" title=\\"Este producto se utiliza como referencia en los recibos del cliente.\\" string=\\"Propinas\\" help=\\"Aceptar propinas de los clientes o convertir el cambio en propina\\" documentation=\\"/applications/sales/point_of_sale/restaurant/tips.html\\">\\n                                    <field name=\\"pos_iface_tipproduct\\"/>\\n                                    <div class=\\"content-group\\" invisible=\\"not pos_iface_tipproduct\\">\\n                                        <div class=\\"row mt16\\" id=\\"tip_product\\">\\n                                            <label string=\\"Producto de propina\\" for=\\"pos_tip_product_id\\" class=\\"col-lg-3 o_light_label \\"/>\\n                                            <field name=\\"pos_tip_product_id\\"/>\\n                                        </div>\\n                                    </div>\\n                                </setting>\\n                            </block>\\n                            <block title=\\"Interfaz TPV\\" id=\\"pos_interface_section\\">\\n                                <setting id=\\"multiple_employee_session\\" title=\\"Los empleados pueden escanear su credencial o ingresar un PIN para iniciar sesión en una sesión de TPV. Estas credenciales se pueden configurar en la pestaña *Configuración de recursos humanos* del formulario del empleado.\\" string=\\"Iniciar sesión como empleado\\" help=\\"Permita registrar y cambiar entre empleados seleccionados\\" documentation=\\"/applications/sales/point_of_sale/employee_login.html\\">\\n                                    <field name=\\"pos_module_pos_hr\\"/>\\n                                    <div class=\\"content-group mt16\\" invisible=\\"not pos_module_pos_hr\\">\\n                                        <div class=\\"text-warning\\" id=\\"warning_text_employees\\">\\n                                            Guarde esta página y luego regrese para configurar la función.\\n                                        </div>\\n                                    </div>\\n                                </setting>\\n                                <setting invisible=\\"is_kiosk_mode\\" help=\\"Mejore la navegación en pantallas táctiles industriales imprecisas\\">\\n                                    <field name=\\"pos_iface_big_scrollbars\\"/>\\n                                </setting>\\n                                <setting string=\\"Compartir pedidos abiertos\\" help=\\"Permita el acceso a los pedidos activos de los demás\\" id=\\"is_order_shared\\" invisible=\\"pos_module_pos_restaurant or is_kiosk_mode\\">\\n                                    <div class=\\"content-group\\">\\n                                        <div class=\\"row mt16\\">\\n                                            <label string=\\"TPV de confianza\\" for=\\"pos_trusted_config_ids\\" class=\\"col-lg-3 o_light_label\\"/>\\n                                            <field name=\\"pos_trusted_config_ids\\" widget=\\"many2many_tags\\" options=\\"{'no_create':'true'}\\" placeholder=\\"Seleccione el TPV para empezar a compartir pedidos\\"/>\\n                                        </div>\\n                                        <div>\\n                                            <button name=\\"554\\" icon=\\"oi-arrow-right\\" type=\\"action\\" string=\\"Punto de venta\\" class=\\"btn-link\\"/>\\n                                        </div>\\n                                    </div>\\n                                </setting>\\n                                <setting string=\\"Ocultar imágenes en el TPV\\" help=\\"Las interfaces de autopedido no se verán afectadas.\\">\\n                                    <div class=\\"content-group\\">\\n                                        <div>\\n                                            <field name=\\"pos_show_product_images\\"/>\\n                                            <label for=\\"pos_show_product_images\\" string=\\"Mostrar imágenes del producto\\" class=\\"fw-normal me-1\\"/>\\n                                        </div>\\n                                        <div>\\n                                            <field name=\\"pos_show_category_images\\"/>\\n                                            <label for=\\"pos_show_category_images\\" string=\\"Mostrar imágenes de la categoría\\" class=\\"fw-normal me-1\\"/>\\n                                        </div>\\n                                    </div>\\n                                </setting>\\n                                <setting help=\\"Reserva en línea para el punto de venta\\" invisible=\\"is_kiosk_mode\\">\\n                                    <field name=\\"pos_module_pos_appointment\\" string=\\"Reserva\\" widget=\\"upgrade_boolean\\"/>\\n                                    <div class=\\"content-group\\" id=\\"pos_appointment_booking\\" invisible=\\"not pos_module_pos_appointment\\">\\n                                        <div class=\\"text-warning mt16 mb4\\">\\n                                            Guarde esta página y luego regrese para configurar la función.\\n                                        </div>\\n                                    </div>\\n                                </setting>\\n                                <setting invisible=\\"is_kiosk_mode\\" help=\\"Mostrar productos agrupados por categorías.\\">\\n                                    <field name=\\"pos_iface_group_by_categ\\"/>\\n                                </setting>\\n                            </block>\\n                            <block id=\\"product_and_category_block\\" title=\\"Categorías de producto y TPV\\">\\n                                <setting help=\\"Selecciona las categorías de punto de venta disponibles para el producto\\">\\n                                    <field name=\\"pos_limit_categories\\"/>\\n                                    <div class=\\"content-group mt16\\" invisible=\\"not pos_limit_categories\\">\\n                                        <field name=\\"pos_iface_available_categ_ids\\" widget=\\"many2many_tags\\"/>\\n                                    </div>\\n                                    <div class=\\"content-group mt16\\" invisible=\\"not pos_limit_categories\\">\\n                                        <button name=\\"544\\" icon=\\"oi-arrow-right\\" type=\\"action\\" string=\\"Categorías de producto TPV\\" class=\\"btn-link\\"/>\\n                                    </div>\\n                                </setting>\\n                                <setting id=\\"margin_and_cost\\" string=\\"Mostrar márgenes y costes\\" help=\\"Muestre márgenes y costes en la información del producto\\">\\n                                    <field name=\\"pos_is_margins_costs_accessible_to_every_user\\"/>\\n                                </setting>\\n                            </block>\\n                            <block title=\\"Contabilidad\\" id=\\"pos_accounting_section\\">\\n                                <setting id=\\"default_sales_tax_setting\\" title=\\"Este impuesto se aplica a todos los productos nuevos creados en el catálogo.\\" documentation=\\"/applications/finance/accounting/taxation/taxes/default_taxes.html\\">\\n                                    <label string=\\"Impuesto de ventas por defecto\\" for=\\"sale_tax_id\\"/>\\n                                    <i class=\\"fa fa-info-circle me-1\\" title=\\"This setting is common to all PoS.\\" pos-data-toggle=\\"tooltip\\"/>\\n                                    <div class=\\"text-muted\\">\\n                                        Impuesto de venta por defecto para productos\\n                                    </div>\\n                                    <div class=\\"content-group mt16\\">\\n                                        <field name=\\"sale_tax_id\\" colspan=\\"4\\" nolabel=\\"1\\" domain=\\"[('type_tax_use', 'in', ('sale', 'all'))]\\"/>\\n                                    </div>\\n                                    <div class=\\"mt8\\">\\n                                        <button name=\\"373\\" icon=\\"oi-arrow-right\\" type=\\"action\\" string=\\"Impuestos\\" class=\\"btn-link\\"/>\\n                                    </div>\\n                                </setting>\\n                                <setting groups=\\"account.group_account_readonly\\">\\n                                    <label string=\\"Cuenta por cobrar por defecto del TPV\\" for=\\"account_default_pos_receivable_account_id\\"/>\\n                                    <i class=\\"fa fa-info-circle me-1\\" title=\\"This setting is common to all PoS.\\" pos-data-toggle=\\"tooltip\\"/>\\n                                    <div class=\\"text-muted\\">\\n                                        Cuenta intermediaria que se utiliza para clientes sin identificar.\\n                                    </div>\\n                                    <field name=\\"account_default_pos_receivable_account_id\\" colspan=\\"4\\" nolabel=\\"1\\" domain=\\"[('reconcile', '=', True), ('account_type', '=', 'asset_receivable')]\\"/>\\n                                </setting>\\n                                <setting id=\\"order_edit_tracking\\" help=\\"Almacene los pedidos editados en el backend\\">\\n                                    <field name=\\"pos_order_edit_tracking\\"/>\\n                                </setting>\\n                                <setting id=\\"flexible_taxes\\" invisible=\\"pos_use_presets\\" title=\\"Elija una posición fiscal específica en el pedido en función del tipo de cliente (exento de impuestos, &quot;en el lugar&quot; vs. &quot;para llevar&quot;, etc.).\\" string=\\"Impuestos flexibles\\" help=\\"Utilizar las posiciones fiscales para usar impuestos distintos por pedido\\" documentation=\\"/applications/sales/point_of_sale/pricing/fiscal_position.html\\">\\n                                    <field name=\\"pos_tax_regime_selection\\"/>\\n                                    <div class=\\"content-group mt16\\" invisible=\\"not pos_tax_regime_selection\\">\\n                                        <div class=\\"row\\">\\n                                            <label string=\\"Por defecto\\" for=\\"pos_default_fiscal_position_id\\" class=\\"col-lg-3 o_light_label\\"/>\\n                                            <field name=\\"pos_default_fiscal_position_id\\"/>\\n                                        </div>\\n                                        <div class=\\"row\\">\\n                                            <label string=\\"Permitido\\" for=\\"pos_fiscal_position_ids\\" class=\\"col-lg-3 o_light_label\\"/>\\n                                            <field name=\\"pos_fiscal_position_ids\\" widget=\\"many2many_tags\\" options=\\"{'no_create': True}\\"/>\\n                                        </div>\\n                                        <div>\\n                                            <button name=\\"388\\" icon=\\"oi-arrow-right\\" type=\\"action\\" string=\\"Posiciones fiscales\\" class=\\"btn-link\\"/>\\n                                        </div>\\n                                    </div>\\n                                </setting>\\n                                <setting string=\\"Diarios por defecto\\" id=\\"pos_default_journals\\" help=\\"Diarios por defecto para pedidos y facturas\\">\\n                                    <div class=\\"content-group mt16\\">\\n                                        <div class=\\"row\\" title=\\"Cada vez que cierre una sesión, se genera una entrada en el siguiente registro contable para todos los pedidos no facturados. Las facturas se registran en la contabilidad por separado.\\">\\n                                            <label string=\\"Pedidos\\" for=\\"pos_journal_id\\" class=\\"col-lg-3 o_light_label\\" options=\\"{'no_open': True, 'no_create': True}\\"/>\\n                                            <field name=\\"pos_journal_id\\" domain=\\"[('company_id', '=', company_id), ('type', 'in', ('general', 'sale'))]\\" context=\\"{'default_company_id': company_id, 'default_type': 'general'}\\" required=\\"pos_company_has_template\\"/>\\n                                        </div>\\n                                        <div class=\\"row\\">\\n                                            <label string=\\"Facturas\\" for=\\"pos_invoice_journal_id\\" class=\\"col-lg-3 o_light_label\\"/>\\n                                            <field name=\\"pos_invoice_journal_id\\" domain=\\"[('company_id', '=', company_id), ('type', '=', 'sale')]\\" context=\\"{'default_company_id': company_id, 'default_type': 'sale'}\\"/>\\n                                        </div>\\n                                    </div>\\n                                </setting>\\n                                <setting string=\\"Asiento de cierre por producto\\" id=\\"pos_closeing_entry_by_product\\" help=\\"Muestre el desglose de las líneas de venta por producto en el asiento de cierre que se genera automáticamente.\\">\\n                                    <field name=\\"pos_is_closing_entry_by_product\\"/>\\n                                </setting>\\n                                <setting id=\\"pos-avatax\\" help=\\"Use el mapeo automático de impuestos con AvaTax\\">\\n                                    <field name=\\"pos_module_pos_avatax\\"/>\\n                                </setting>\\n                            </block>\\n\\n                            <block title=\\"Precios\\" id=\\"pos_pricing_section\\">\\n                                <setting id=\\"multiple_prices_setting\\" string=\\"Listas de precios flexibles\\" help=\\"Define varios precios por producto, descuentos automáticos, etc.\\" documentation=\\"/applications/sales/point_of_sale/pricing/pricelists.html\\">\\n                                    <field name=\\"pos_use_pricelist\\"/>\\n                                    <div class=\\"content-group\\" invisible=\\"not pos_use_pricelist\\">\\n                                        <div class=\\"row mt16\\">\\n                                            <label string=\\"Disponible\\" for=\\"pos_available_pricelist_ids\\" class=\\"col-lg-3 o_light_label\\"/>\\n                                            <field name=\\"pos_available_pricelist_ids\\" widget=\\"many2many_tags\\" domain=\\"['|',('company_id', '=', company_id),('company_id', '=', False)]\\"/>\\n                                        </div>\\n                                        <div class=\\"row mt16\\">\\n                                            <label string=\\"Por defecto\\" for=\\"pos_pricelist_id\\" class=\\"col-lg-3 o_light_label\\"/>\\n                                            <field name=\\"pos_pricelist_id\\" domain=\\"[('id', 'in', pos_allowed_pricelist_ids)]\\" options=\\"{'no_create': True}\\"/>\\n                                        </div>\\n                                        <div class=\\"mt8\\">\\n                                            <button name=\\"172\\" icon=\\"oi-arrow-right\\" type=\\"action\\" string=\\"Listas de precio\\" groups=\\"product.group_product_pricelist\\" class=\\"btn-link\\"/>\\n                                        </div>\\n                                    </div>\\n                                </setting>\\n                                <setting id=\\"price_control\\" class=\\"price_control\\" title=\\"Solo los usuarios con permisos de acceso de gerente en la aplicación Punto de Venta pueden modificar los precios de los productos en los pedidos.\\" string=\\"Control de precios\\" help=\\"Restringir la modificación de los precios a los gerentes\\">\\n                                    <field name=\\"pos_restrict_price_control\\"/>\\n                                </setting>\\n                                <setting id=\\"product_prices\\" string=\\"Precios del producto\\" help=\\"Precios de los productos en los recibos\\">\\n                                    <field name=\\"pos_iface_tax_included\\" class=\\"o_light_label\\" widget=\\"radio\\"/>\\n                                    <div class=\\"content-group\\">\\n                                        <widget class=\\"oe-link\\" name=\\"documentation_link\\" path=\\"/applications/finance/accounting/taxation/taxes/B2B_B2C.html\\" label=\\"Cómo gestionar precios con impuestos incluidos\\" icon=\\"oi oi-fw oi-arrow-right\\"/>\\n                                    </div>\\n                                </setting>\\n                                <setting id=\\"manual_discount\\" help=\\"Permita a los cajeros configurar un descuento por línea\\" documentation=\\"/applications/sales/point_of_sale/pricing/discounts.html\\">\\n                                    <field name=\\"pos_manual_discount\\"/>\\n                                </setting>\\n                                <setting id=\\"pos_global_discount\\" help=\\"Añade un botón para configurar un descuento global\\" documentation=\\"/applications/sales/point_of_sale/pricing/discounts.html\\">\\n                                    <field name=\\"pos_module_pos_discount\\"/>\\n                                    <div class=\\"content-group mt16\\" invisible=\\"not pos_module_pos_discount\\">\\n                                        <div class=\\"text-warning mb4\\" id=\\"warning_text_pos_discount\\">\\n                                            Guarde esta página y luego regrese para configurar la función.\\n                                        </div>\\n                                    </div>\\n                                </setting>\\n                                <setting id=\\"pos_pricer\\" string=\\"Pricer\\" title=\\"Etiquetas de Pricer\\" help=\\"Muestre y actualice la información de sus productos con etiquetas de precio electrónicas\\">\\n                                    <field name=\\"module_pos_pricer\\"/>\\n                                </setting>\\n                                <setting id=\\"pos-loyalty\\" title=\\"Impulsa tus ventas con distintos tipos de programas: cupones, promociones, tarjetas regalo y fidelización. Se pueden definir condiciones específicas (productos, clientes, importe mínimo de compra, período). Las recompensas pueden ser descuentos (% o importe) o productos gratuitos.\\" string=\\"Promociones, cupones, tarjeta de regalo y programa de fidelización\\" help=\\"Gestionar promoción que le otorgará a los clientes descuentos o regalos\\" documentation=\\"/applications/sales/point_of_sale/pricing/loyalty.html\\">\\n                                    <field name=\\"module_loyalty\\"/>\\n                                </setting>\\n                            </block>\\n\\n                            <block title=\\"Facturas y recibos\\" id=\\"pos_bills_and_receipts_section\\">\\n                                <setting help=\\"Añadir un mensaje personalizado en el encabezado y pie de página\\" documentation=\\"/applications/sales/point_of_sale/receipts_invoices.html\\">\\n                                    <field name=\\"pos_is_header_or_footer\\"/>\\n                                    <div class=\\"content-group mt16\\" invisible=\\"not pos_is_header_or_footer\\">\\n                                        <div>\\n                                            <label string=\\"Encabezado\\" for=\\"pos_receipt_header\\" class=\\"col-lg-2 o_light_label\\"/>\\n                                            <field name=\\"pos_receipt_header\\" placeholder=\\"p. ej.: dirección de la empresa, página web\\"/>\\n                                        </div>\\n                                        <div>\\n                                            <label string=\\"Pie de página\\" for=\\"pos_receipt_footer\\" class=\\"col-lg-2 o_light_label\\"/>\\n                                            <field name=\\"pos_receipt_footer\\" placeholder=\\"p. ej.: política de devoluciones, ¡Gracias por comprar con nosotros!\\"/>\\n                                        </div>\\n                                    </div>\\n                                </setting>\\n                                <setting id=\\"auto_printing\\" help=\\"Imprimir tickets automáticamente una vez registrado el pago\\" documentation=\\"/applications/sales/point_of_sale/receipts_invoices.html\\">\\n                                    <field name=\\"pos_iface_print_auto\\"/>\\n                                    <div class=\\"content-group mt16\\" invisible=\\"not pos_iface_print_auto or not pos_is_posbox and not pos_other_devices\\">\\n                                        <div>\\n                                            <field name=\\"pos_iface_print_skip_screen\\" class=\\"oe_inline\\"/><span class=\\"oe_inline\\"><b>Saltar pantalla de vista previa</b></span>\\n                                        </div>\\n                                    </div>\\n                                </setting>\\n                                <setting id=\\"pos_sms\\" help=\\"Enviar ticket por SMS\\">\\n                                    <field name=\\"pos_module_pos_sms\\"/>\\n                                    <div class=\\"content-group\\" readonly=\\"pos_has_active_session\\">\\n                                        <div class=\\"content-group mt16\\" invisible=\\"not pos_module_pos_sms\\">\\n                                            <div class=\\"text-warning mb4\\" id=\\"warning_text_pos_sms\\">\\n                                                Guarde esta página y luego regrese para configurar la función.\\n                                            </div>\\n                                        </div>\\n                                    </div>\\n                                </setting>\\n                                <setting help=\\"Imprima la información en el recibo para que el cliente pueda solicitar su factura desde el portal de Odoo con facilidad en cualquier momento.\\" documentation=\\"/applications/sales/point_of_sale/receipts_invoices.html\\" id=\\"pos_use_ticket_qr_code\\">\\n                                    <field name=\\"point_of_sale_use_ticket_qr_code\\"/>\\n                                    <div class=\\"content-group mt16\\" invisible=\\"not point_of_sale_use_ticket_qr_code\\">\\n                                        <div class=\\"col mt16\\">\\n                                            <div class=\\"content-group row\\">\\n                                                <label for=\\"point_of_sale_ticket_portal_url_display_mode\\" class=\\"col-lg-2\\" string=\\"Imprimir\\"/>\\n                                                <field name=\\"point_of_sale_ticket_portal_url_display_mode\\"/>\\n                                            </div>\\n                                        </div>\\n                                    </div>\\n                                </setting>\\n                                <setting id=\\"basic_receipt\\" help=\\"Imprima un recibo básico sin precios. Es útil para regalos.\\">\\n                                    <field name=\\"pos_basic_receipt\\"/>\\n                                </setting>\\n                            </block>\\n\\n                            <block title=\\"Terminales de pago\\" help=\\"Estos ajustes son comunes a todos los TPV.\\" id=\\"pos_payment_terminals_section\\">\\n                                <setting id=\\"adyen_payment_terminal_setting\\" title=\\"Adyen procesa las transacciones. Establezca sus credenciales de Adyen en el método de pago relacionado.\\" string=\\"Adyen\\" help=\\"Acepte pagos con un terminal de pago Adyen\\" documentation=\\"/applications/sales/point_of_sale/payment_methods/terminals/adyen.html\\">\\n                                    <field name=\\"module_pos_adyen\\"/>\\n                                    <button name=\\"open_payment_method_form\\" icon=\\"oi-arrow-right\\" type=\\"object\\" string=\\"Método de pago\\" class=\\"btn-link\\" context=\\"{'selection': 'adyen', 'config_ids': [pos_config_id], 'provider_name': 'Adyen'}\\" invisible=\\"not module_pos_adyen\\"/>\\n                                </setting>\\n                                <setting id=\\"stripe_payment_terminal_setting\\" title=\\"Stripe procesa las transacciones. Establezca sus credenciales de Stripe en el método de pago relacionado.\\" string=\\"Stripe\\" help=\\"Acepte pagos con un terminal de pago Stripe\\" documentation=\\"/applications/sales/point_of_sale/payment_methods/terminals/stripe.html\\">\\n                                    <field name=\\"module_pos_stripe\\"/>\\n                                    <button name=\\"open_payment_method_form\\" icon=\\"oi-arrow-right\\" type=\\"object\\" string=\\"Método de pago\\" class=\\"btn-link\\" context=\\"{'selection': 'stripe', 'config_ids': [pos_config_id], 'provider_name': 'Stripe'}\\" invisible=\\"not module_pos_stripe\\"/>\\n                                </setting>\\n                                <setting title=\\"Viva.com procesa las transacciones en el terminal o pulsa para pagar en el teléfono.\\" string=\\"Viva.com\\" help=\\"Acepte pagos con Viva.com en un terminal o presione en el teléfono\\" documentation=\\"/applications/sales/point_of_sale/payment_methods/terminals/viva_com.html\\">\\n                                    <field name=\\"module_pos_viva_com\\"/>\\n                                    <button name=\\"open_payment_method_form\\" icon=\\"oi-arrow-right\\" type=\\"object\\" string=\\"Método de pago\\" class=\\"btn-link\\" context=\\"{'selection': 'viva_com', 'config_ids': [pos_config_id], 'provider_name': 'Viva.com'}\\" invisible=\\"not module_pos_viva_com\\"/>\\n                                </setting>\\n                                <setting id=\\"pos_razorpay_setting\\" title=\\"Razorpay procesa las transacciones. Establezca sus credenciales de Razorpay en el método de pago relacionado.\\" string=\\"Razorpay\\" help=\\"Acepte pagos con un terminal de pago Razorpay\\" documentation=\\"/applications/sales/point_of_sale/payment_methods/terminals/razorpay.html\\">\\n                                    <field name=\\"module_pos_razorpay\\"/>\\n                                    <button name=\\"open_payment_method_form\\" icon=\\"oi-arrow-right\\" type=\\"object\\" string=\\"Método de pago\\" class=\\"btn-link\\" context=\\"{'selection': 'razorpay', 'config_ids': [pos_config_id], 'provider_name': 'Razorpay'}\\" invisible=\\"not module_pos_razorpay\\"/>\\n                                </setting>\\n                                <setting title=\\"Las transacciones son procesadas por Mercado Pago en el terminal\\" string=\\"Mercado Pago\\" help=\\"Acepte pagos con Mercado Pago en un terminal\\" documentation=\\"/applications/sales/point_of_sale/payment_methods/terminals/mercado_pago.html\\">\\n                                    <field name=\\"module_pos_mercado_pago\\"/>\\n                                    <button name=\\"open_payment_method_form\\" icon=\\"oi-arrow-right\\" type=\\"object\\" string=\\"Método de pago\\" class=\\"btn-link\\" context=\\"{'selection': 'mercado_pago', 'config_ids': [pos_config_id], 'provider_name': 'Mercado Pago'}\\" invisible=\\"not module_pos_mercado_pago\\"/>\\n                                </setting>\\n                                <setting title=\\"Las transacciones son procesadas por Pine Labs en el terminal.\\" string=\\"Pine Labs\\" help=\\"Acepte pagos con un terminal de pago de Pine Labs\\" documentation=\\"/applications/sales/point_of_sale/payment_methods/terminals/pine_labs.html\\">\\n                                    <field name=\\"module_pos_pine_labs\\"/>\\n                                    <button name=\\"open_payment_method_form\\" icon=\\"oi-arrow-right\\" type=\\"object\\" string=\\"Método de pago\\" class=\\"btn-link\\" context=\\"{'selection': 'pine_labs', 'config_ids': [pos_config_id], 'provider_name': 'Pine Labs'}\\" invisible=\\"not module_pos_pine_labs\\"/>\\n                                </setting>\\n                                <setting title=\\"Las transacciones se procesan en el terminal mediante QFPay.\\" string=\\"QFPay\\" help=\\"Acepta pagos con un terminal de pago QFPay\\" documentation=\\"/applications/sales/point_of_sale/payment_methods/terminals/qfpay.html\\">\\n                                    <field name=\\"module_pos_qfpay\\"/>\\n                                    <button name=\\"open_payment_method_form\\" icon=\\"oi-arrow-right\\" type=\\"object\\" string=\\"Método de pago\\" class=\\"btn-link\\" context=\\"{'selection': 'qfpay', 'config_ids': [pos_config_id], 'provider_name': 'QFPay'}\\" invisible=\\"not module_pos_qfpay\\"/>\\n                                </setting>\\n                            </block>\\n\\n                            <block title=\\"Dispositivos conectados\\" id=\\"pos_connected_devices_section\\">\\n                                <setting id=\\"pos_other_devices\\" string=\\"Impresora ePos\\" help=\\"Conecte el dispositivo a su TPV sin una Caja IoT\\" documentation=\\"/applications/sales/point_of_sale/configuration/epos_ssc.html\\">\\n                                    <field name=\\"pos_other_devices\\"/>\\n                                    <div class=\\"row\\" invisible=\\"not pos_other_devices\\">\\n                                        <div class=\\"col-lg-6\\">\\n                                            <field name=\\"pos_epson_printer_ip\\" placeholder=\\"Dirección IP de la impresora de recibos Epson\\" class=\\"w-100 pt-1\\"/>\\n                                        </div>\\n                                        <div class=\\"col-lg-6\\">\\n                                            <widget name=\\"point_of_sale_test_epos\\"/>\\n                                        </div>\\n                                        <div class=\\"col-12 mt-2\\">\\n                                            <div class=\\"row\\" invisible=\\"pos_epson_printer_ip in [False, '']\\">\\n                                                <label string=\\"Vincular cajón de efectivo\\" for=\\"pos_iface_cashdrawer\\" class=\\"col-lg-4 o_light_label\\"/>\\n                                                <field name=\\"pos_iface_cashdrawer\\" class=\\"col\\"/>\\n                                            </div>\\n                                        </div>\\n                                    </div>\\n                                    <div role=\\"alert\\" class=\\"alert alert-warning\\" invisible=\\"not pos_iface_print_via_proxy or not pos_other_devices or pos_epson_printer_ip in [False, '']\\">\\n                                        Se utilizará la impresora de recibos Epson en lugar de la impresora de recibos conectada a la caja IoT.\\n                                    </div>\\n                                </setting>\\n                                <setting id=\\"customer_display\\" string=\\"Pantalla del cliente\\" help=\\"Establezca la imagen de fondo de la pantalla del cliente\\" documentation=\\"/applications/sales/point_of_sale/shop/customer_display.html\\">\\n                                    <label for=\\"pos_customer_display_bg_img\\"/>\\n                                    <field name=\\"pos_customer_display_bg_img\\" class=\\"w-100\\" filename=\\"pos_customer_display_bg_img_name\\"/>\\n                                </setting>\\n                                <setting string=\\"Caja IoT\\" help=\\"Conecta dispositivos mediante una caja IoT\\">\\n                                    <field name=\\"pos_is_posbox\\"/>\\n                                    <div class=\\"content-group pos_iot_config\\" invisible=\\"not pos_is_posbox\\">\\n                                        <div class=\\"row\\">\\n                                            <label string=\\"Dirección IP de la caja IoT\\" for=\\"pos_proxy_ip\\" class=\\"col-lg-4 o_light_label\\"/>\\n                                            <field name=\\"pos_proxy_ip\\"/>\\n                                        </div>\\n                                        <div class=\\"row iot_barcode_scanner\\">\\n                                            <label string=\\"Lector de código de barras / lector de tarjetas\\" for=\\"pos_iface_scan_via_proxy\\" class=\\"col-lg-4 o_light_label\\"/>\\n                                            <field name=\\"pos_iface_scan_via_proxy\\"/>\\n                                        </div>\\n                                        <div class=\\"row\\">\\n                                            <label string=\\"Báscula electrónica\\" for=\\"pos_iface_electronic_scale\\" class=\\"col-lg-4 o_light_label\\"/>\\n                                            <field name=\\"pos_iface_electronic_scale\\"/>\\n                                        </div>\\n                                        <div class=\\"row\\">\\n                                            <label string=\\"Impresora de recibos\\" for=\\"pos_iface_print_via_proxy\\" class=\\"col-lg-4 o_light_label\\"/>\\n                                            <field name=\\"pos_iface_print_via_proxy\\"/>\\n                                        </div>\\n                                        <div class=\\"row\\" invisible=\\"not pos_iface_print_via_proxy\\">\\n                                            <label string=\\"Cajón portamonedas\\" for=\\"pos_iface_cashdrawer\\" class=\\"col-lg-4 o_light_label\\"/>\\n                                            <field name=\\"pos_iface_cashdrawer\\"/>\\n                                        </div>\\n                                    </div>\\n                                </setting>\\n                            </block>\\n\\n                            <block title=\\"Preparación\\" id=\\"pos_preparation_section\\">\\n                                <setting string=\\"Impresoras de preparación\\" help=\\"Imprima los pedidos en la cocina, en el bar, etc.\\" id=\\"is_order_printer\\">\\n                                    <field name=\\"pos_is_order_printer\\"/>\\n                                    <div class=\\"content-group\\" invisible=\\"not pos_is_order_printer\\">\\n                                        <div class=\\"mt16 mb-1\\">\\n                                            <label string=\\"Impresoras\\" for=\\"pos_printer_ids\\" class=\\"o_light_label me-2\\"/>\\n                                            <field name=\\"pos_printer_ids\\" widget=\\"many2many_tags\\"/>\\n                                        </div>\\n                                        <div>\\n                                            <button name=\\"action_pos_printer_dialog\\" context=\\"{'default_pos_config_ids': [pos_config_id]}\\" icon=\\"oi-arrow-right\\" type=\\"object\\" string=\\"Añadir impresora\\" class=\\"btn-link\\"/>\\n                                        </div>\\n                                        <div>\\n                                            <button name=\\"566\\" icon=\\"oi-arrow-right\\" type=\\"action\\" string=\\"Gestionar impresoras\\" class=\\"btn-link\\"/>\\n                                        </div>\\n                                    </div>\\n                                </setting>\\n                                <setting string=\\"Notas internas\\" help=\\"Añada notas internas en las líneas de pedido para la cocina\\" id=\\"iface_orderline_notes\\">\\n                                    <div class=\\"content-group\\">\\n                                        <div class=\\"mt16\\">\\n                                            <label string=\\"Modelos de nota\\" for=\\"pos_note_ids\\" class=\\"o_light_label me-2\\"/>\\n                                            <field name=\\"pos_note_ids\\" widget=\\"many2many_tags\\" readonly=\\"pos_has_active_session\\" placeholder=\\"Todas las notas\\"/>\\n                                        </div>\\n                                        <div>\\n                                            <button name=\\"535\\" icon=\\"oi-arrow-right\\" type=\\"action\\" string=\\"Notas\\" class=\\"btn-link\\"/>\\n                                        </div>\\n                                    </div>\\n                                </setting>\\n                            </block>\\n\\n                            <block title=\\"Inventario\\" id=\\"pos_inventory_section\\">\\n                                <setting title=\\"Los tipos de operación aparecen en el tablero de Inventario.\\" string=\\"Tipo de operación\\" help=\\"Se utiliza para registrar los movimientos de productos. Los productos se consumen desde su ubicación de origen predeterminada.\\">\\n                                    <field name=\\"pos_picking_type_id\\" domain=\\"[('company_id', '=', company_id)]\\" required=\\"pos_config_id\\"/>\\n                                </setting>\\n                                <setting id=\\"ship_later\\" string=\\"Permitir enviar más tarde\\" help=\\"Venda productos y entréguelos después.\\">\\n                                    <field name=\\"pos_ship_later\\"/>\\n                                    <div class=\\"content-group mt16\\" invisible=\\"not pos_ship_later\\">\\n                                        <div class=\\"row\\">\\n                                            <label for=\\"pos_warehouse_id\\" string=\\"Almacén\\" class=\\"col-lg-3 o_light_label\\"/>\\n                                            <field name=\\"pos_warehouse_id\\" required=\\"pos_ship_later\\"/>\\n                                        </div>\\n                                        <div groups=\\"stock.group_adv_location\\" class=\\"row\\">\\n                                            <label for=\\"pos_route_id\\" string=\\"Ruta específica\\" class=\\"col-lg-3 o_light_label\\"/>\\n                                            <field name=\\"pos_route_id\\"/>\\n                                        </div>\\n                                        <div class=\\"row\\">\\n                                            <label for=\\"pos_picking_policy\\" class=\\"col-lg-3 o_light_label\\"/>\\n                                            <field name=\\"pos_picking_policy\\" required=\\"pos_ship_later\\"/>\\n                                        </div>\\n                                    </div>\\n                                </setting>\\n                                <setting id=\\"barcode_scanner\\">\\n                                    <span class=\\"o_form_label\\">Códigos de barras</span>\\n                                    <i class=\\"fa fa-info-circle me-1\\" title=\\"This setting is common to all PoS.\\" pos-data-toggle=\\"tooltip\\"/>\\n                                    <div class=\\"text-muted\\">\\n                                        Utilice códigos de barras para escanear productos, tarjetas de clientes, etc.\\n                                    </div>\\n                                    <div class=\\"content-group mt16 row\\">\\n                                        <label for=\\"barcode_nomenclature_id\\" string=\\"Nomenclatura de código de barras\\" class=\\"col-lg-3 o_light_label\\"/>\\n                                        <field name=\\"barcode_nomenclature_id\\"/>\\n                                    </div>\\n                                    <div class=\\"content-group mt16 row\\">\\n                                        <label for=\\"pos_fallback_nomenclature_id\\" string=\\"Nomenclatura alternativa\\" class=\\"col-lg-3 o_light_label\\"/>\\n                                        <field name=\\"pos_fallback_nomenclature_id\\"/>\\n                                    </div>\\n                                </setting>\\n                                <setting id=\\"update_quantities_stock_setting\\" groups=\\"base.group_no_one\\" string=\\"Gestión de inventario\\" company_dependent=\\"1\\" help=\\"Actualizar cantidades en stock\\">\\n                                    <field name=\\"update_stock_quantities\\" colspan=\\"4\\" widget=\\"radio\\"/>\\n                                </setting>\\n                            </block>\\n                        </div>\\n                    </div>\\n                    </div>\\n                </app>\\n            </xpath>"}	<?xml version="1.0"?>\n<xpath expr="//form" position="inside">\n                <t groups="point_of_sale.group_pos_manager">\n                    <field name="is_kiosk_mode" invisible="1"/>\n                    <field name="pos_selectable_categ_ids" invisible="1"/>\n                    <field name="pos_has_active_session" invisible="1"/>\n                    <field name="pos_allowed_pricelist_ids" invisible="1"/>\n                    <field name="pos_cash_control" invisible="1"/>\n                    <field name="pos_iface_print_via_proxy" invisible="1"/>\n                    <field name="pos_company_has_template" invisible="1"/>\n                    <field name="group_cash_rounding" invisible="1"/>\n                </t>\n\n                <app data-string="Point of sale" string="Point of Sale" name="point_of_sale" groups="point_of_sale.group_pos_manager">\n                    <div class="pos_res_config_container">\n                    <div class="sticky-top w-100 bg-white">\n                        <setting type="header" string="Point of Sale" class="bg-warning">\n                            <field name="pos_config_id" options="{'no_open': True, 'no_create': True}" title="Settings on this page will apply to this point of sale."/>\n                            <button name="action_pos_config_create_new" type="object" string="+ New Shop" class="btn btn-link"/>\n                        </setting>\n                    </div>\n\n                    <div class="pos_config_content">\n                        <div class="o_view_nocontent" invisible="pos_config_id">\n                            <div class="o_nocontent_help">\n                                <p class="o_view_nocontent_empty_folder">No Point of Sale selected</p>\n                                <p>Please create/select a Point of Sale above to show the configuration options.</p>\n                            </div>\n                        </div>\n                        <div class="o_notification_alert alert alert-warning mt-1 mb-0" invisible="not pos_has_active_session" role="alert">\n                            A session is currently opened for this PoS. Some settings can only be changed after the session is closed.\n                            <button class="btn-link" style="padding:0" name="pos_close_ui" type="object" context="{'pos_config_id': pos_config_id}">Click here to close the session</button>\n                        </div>\n                        <div class="o_notification_alert alert alert-warning" invisible="pos_company_has_template or chart_template" role="alert">\n                            There is no Chart of Accounts configured on the company. Please go to the invoicing settings to install a Chart of Accounts.\n                        </div>\n                        <div invisible="not pos_config_id">\n                            <block title="Point of Sale" id="restaurant_section">\n                                <!-- Wrap the warnings in an o_setting_box so that it doesn't show in the search. -->\n                                <setting id="is_restaurant">\n                                    <field name="pos_module_pos_restaurant" readonly="pos_has_active_session"/>\n                                    <div class="content-group" id="warning_text_pos_restaurant" invisible="not pos_module_pos_restaurant">\n                                        <div class="text-warning mt16 mb4">\n                                            Save this page and come back here to set up the feature.\n                                        </div>\n                                    </div>\n                                </setting>\n                                <setting string="Take out / Delivery / Members" help="Define presets to manage taxes &amp; prices for dine in, take out, members...">\n                                    <field name="pos_use_presets"/>\n                                    <div class="content-group" invisible="not pos_use_presets">\n                                        <div class="row">\n                                            <label for="pos_available_preset_ids" class="col-lg-3" string="Available"/>\n                                            <field name="pos_available_preset_ids" widget="many2many_tags" options="{'no_quick_create': True, 'color_field': 'color'}"/>\n                                        </div>\n                                        <div class="row">\n                                            <label for="pos_default_preset_id" class="col-lg-3" string="Default"/>\n                                            <field name="pos_default_preset_id" options="{'no_create': True}" required="pos_use_presets" domain="[('id', 'in', pos_available_preset_ids)]"/>\n                                        </div>\n                                        <div>\n                                            <button name="562" icon="oi-arrow-right" type="action" string="Configure Presets" class="btn-link"/>\n                                        </div>\n                                    </div>\n                                </setting>\n                            </block>\n                            <block title="Payment" id="pos_payment_section">\n                                <setting id="payment_methods_new" string="Payment Methods" help="Payment methods available" documentation="/applications/sales/point_of_sale/payment_methods.html">\n                                    <field name="pos_payment_method_ids" colspan="4" widget="many2many_tags" readonly="pos_has_active_session" required="pos_company_has_template" options="{'no_quick_create': True}" context="{'default_config_ids': [pos_config_id], 'form_view_ref': 'point_of_sale.action_pos_payment_method_form' }"/>\n                                    <div>\n                                        <button name="551" icon="oi-arrow-right" type="action" string="Payment Methods" class="btn-link"/>\n                                    </div>\n                                </setting>\n                                <setting string="Automatically validate order" help="Automatically validates orders paid with a payment terminal.">\n                                    <field name="pos_auto_validate_terminal_payment"/>\n                                </setting>\n                                <setting string="Cash Rounding" invisible="is_kiosk_mode" documentation="/applications/sales/point_of_sale/pricing/cash_rounding.html" help="Define the smallest coinage of the currency used to pay by cash">\n                                    <field name="pos_cash_rounding" readonly="pos_has_active_session"/>\n                                    <div class="content-group mt16" invisible="not pos_cash_rounding">\n                                        <div class="row mt16">\n                                            <label string="Rounding Method" for="pos_rounding_method" class="col-lg-3 o_light_label"/>\n                                            <field name="pos_rounding_method" required="pos_cash_rounding" readonly="pos_has_active_session" options="{'no_quick_create': True}"/>\n                                        </div>\n                                        <div class="row mt16">\n                                            <div class="col">\n                                                <field name="pos_only_round_cash_method" readonly="pos_has_active_session"/>\n                                                <label string="Only on cash methods" for="pos_only_round_cash_method" class="o_light_label"/>\n                                            </div>\n                                        </div>\n                                    </div>\n                                    <div class="mt8">\n                                        <button name="383" icon="oi-arrow-right" type="action" string="Cash Roundings" class="btn-link" invisible="not group_cash_rounding"/>\n                                    </div>\n                                </setting>\n                                <setting title="Online payment, delivery payment, terminal payment, and methods that require customer identification are not supported for fast payment validation." help="Shortcut to skip payment screen" invisible="is_kiosk_mode">\n                                    <field name="pos_use_fast_payment" string="One-click Payment"/>\n                                    <div class="content-group mt16" invisible="not pos_use_fast_payment">\n                                        <label for="pos_fast_payment_method_ids" class="fw-bold me-2"/>\n                                        <field name="pos_fast_payment_method_ids" widget="many2many_tags" string="Payment Methods" options="{'no_create': True}" required="pos_use_fast_payment" domain="[('id', 'in', pos_payment_method_ids), ('use_payment_terminal', '=', False), ('split_transactions', '=', False)]"/>\n                                    </div>\n                                </setting>\n                                <setting id="set_maximum_difference" help="Set a maximum difference allowed between the expected and counted money during the closing of the session">\n                                    <field name="pos_set_maximum_difference"/>\n                                    <div class="content-group mt16" invisible="not pos_set_maximum_difference">\n                                        <label for="pos_amount_authorized_diff" string="Authorized Difference" class="fw-normal me-1"/>\n                                        <field name="pos_amount_authorized_diff"/>\n                                    </div>\n                                </setting>\n                                <setting id="iface_tipproduct" title="This product is used as reference on customer receipts." string="Tips" help="Accept customer tips or convert their change to a tip" documentation="/applications/sales/point_of_sale/restaurant/tips.html">\n                                    <field name="pos_iface_tipproduct"/>\n                                    <div class="content-group" invisible="not pos_iface_tipproduct">\n                                        <div class="row mt16" id="tip_product">\n                                            <label string="Tip Product" for="pos_tip_product_id" class="col-lg-3 o_light_label "/>\n                                            <field name="pos_tip_product_id"/>\n                                        </div>\n                                    </div>\n                                </setting>\n                            </block>\n                            <block title="PoS Interface" id="pos_interface_section">\n                                <setting id="multiple_employee_session" title="Employees can scan their badge or enter a PIN to log in to a PoS session. These credentials are configurable in the *HR Settings* tab of the employee form." string="Log in with Employees" help="Allow to log and switch between selected Employees" documentation="/applications/sales/point_of_sale/employee_login.html">\n                                    <field name="pos_module_pos_hr"/>\n                                    <div class="content-group mt16" invisible="not pos_module_pos_hr">\n                                        <div class="text-warning" id="warning_text_employees">\n                                            Save this page and come back here to set up the feature.\n                                        </div>\n                                    </div>\n                                </setting>\n                                <setting invisible="is_kiosk_mode" help="Improve navigation for imprecise industrial touchscreens">\n                                    <field name="pos_iface_big_scrollbars"/>\n                                </setting>\n                                <setting string="Share Open Orders" help="Allow to access each other's active orders" id="is_order_shared" invisible="pos_module_pos_restaurant or is_kiosk_mode">\n                                    <div class="content-group">\n                                        <div class="row mt16">\n                                            <label string="Trusted POS" for="pos_trusted_config_ids" class="col-lg-3 o_light_label"/>\n                                            <field name="pos_trusted_config_ids" widget="many2many_tags" options="{'no_create':'true'}" placeholder="Select PoS to start sharing orders"/>\n                                        </div>\n                                        <div>\n                                            <button name="554" icon="oi-arrow-right" type="action" string="Point of Sales" class="btn-link"/>\n                                        </div>\n                                    </div>\n                                </setting>\n                                <setting string="Hide pictures in POS" help="Self-ordering interfaces are not impacted.">\n                                    <div class="content-group">\n                                        <div>\n                                            <field name="pos_show_product_images"/>\n                                            <label for="pos_show_product_images" string="Show product images" class="fw-normal me-1"/>\n                                        </div>\n                                        <div>\n                                            <field name="pos_show_category_images"/>\n                                            <label for="pos_show_category_images" string="Show category images" class="fw-normal me-1"/>\n                                        </div>\n                                    </div>\n                                </setting>\n                                <setting help="Online reservation for Point of Sale" invisible="is_kiosk_mode">\n                                    <field name="pos_module_pos_appointment" string="Booking" widget="upgrade_boolean"/>\n                                    <div class="content-group" id="pos_appointment_booking" invisible="not pos_module_pos_appointment">\n                                        <div class="text-warning mt16 mb4">\n                                            Save this page and come back here to set up the feature.\n                                        </div>\n                                    </div>\n                                </setting>\n                                <setting invisible="is_kiosk_mode" help="Display products grouped by categories.">\n                                    <field name="pos_iface_group_by_categ"/>\n                                </setting>\n                            </block>\n                            <block id="product_and_category_block" title="Product &amp; PoS categories">\n                                <setting help="Pick which product PoS categories are available">\n                                    <field name="pos_limit_categories"/>\n                                    <div class="content-group mt16" invisible="not pos_limit_categories">\n                                        <field name="pos_iface_available_categ_ids" widget="many2many_tags"/>\n                                    </div>\n                                    <div class="content-group mt16" invisible="not pos_limit_categories">\n                                        <button name="544" icon="oi-arrow-right" type="action" string="PoS Product Categories" class="btn-link"/>\n                                    </div>\n                                </setting>\n                                <setting id="margin_and_cost" string="Show margins &amp; costs" help="Show margins &amp; costs on product information">\n                                    <field name="pos_is_margins_costs_accessible_to_every_user"/>\n                                </setting>\n                            </block>\n                            <block title="Accounting" id="pos_accounting_section">\n                                <setting id="default_sales_tax_setting" title="This tax is applied to any new product created in the catalog." documentation="/applications/finance/accounting/taxation/taxes/default_taxes.html">\n                                    <label string="Default Sales Tax" for="sale_tax_id"/>\n                                    <i class="fa fa-info-circle me-1" title="This setting is common to all PoS." pos-data-toggle="tooltip"/>\n                                    <div class="text-muted">\n                                        Default sales tax for products\n                                    </div>\n                                    <div class="content-group mt16">\n                                        <field name="sale_tax_id" colspan="4" nolabel="1" domain="[('type_tax_use', 'in', ('sale', 'all'))]"/>\n                                    </div>\n                                    <div class="mt8">\n                                        <button name="373" icon="oi-arrow-right" type="action" string="Taxes" class="btn-link"/>\n                                    </div>\n                                </setting>\n                                <setting groups="account.group_account_readonly">\n                                    <label string="Default POS Receivable Account" for="account_default_pos_receivable_account_id"/>\n                                    <i class="fa fa-info-circle me-1" title="This setting is common to all PoS." pos-data-toggle="tooltip"/>\n                                    <div class="text-muted">\n                                        Intermediary account used for unidentified customers.\n                                    </div>\n                                    <field name="account_default_pos_receivable_account_id" colspan="4" nolabel="1" domain="[('reconcile', '=', True), ('account_type', '=', 'asset_receivable')]"/>\n                                </setting>\n                                <setting id="order_edit_tracking" help="Store edited orders in the backend">\n                                    <field name="pos_order_edit_tracking"/>\n                                </setting>\n                                <setting id="flexible_taxes" invisible="pos_use_presets" title="Choose a specific fiscal position at the order depending on the kind of customer (tax exempt, onsite vs. takeaway, etc.)." string="Flexible Taxes" help="Use fiscal positions to get different taxes by order" documentation="/applications/sales/point_of_sale/pricing/fiscal_position.html">\n                                    <field name="pos_tax_regime_selection"/>\n                                    <div class="content-group mt16" invisible="not pos_tax_regime_selection">\n                                        <div class="row">\n             