ame=\\"forecast_availability\\" string=\\"\\" column_invisible=\\"parent.state == 'done'\\" widget=\\"forecast_widget\\"/>\\n                                <field name=\\"description_picking\\" string=\\"Description\\" optional=\\"hide\\"/>\\n                                <field name=\\"date\\" optional=\\"hide\\"/>\\n                                <field name=\\"date_deadline\\" optional=\\"hide\\"/>\\n                                <field name=\\"product_uom_qty\\" string=\\"Demand\\" readonly=\\"state in ('done', 'cancel')\\"/>\\n                                <field name=\\"forecast_expected_date\\" column_invisible=\\"True\\"/>\\n                                <field name=\\"product_qty\\" readonly=\\"1\\" column_invisible=\\"True\\"/>\\n                                <field name=\\"quantity\\" string=\\"Quantity\\" readonly=\\"not product_id\\"/>\\n                                <field name=\\"product_uom\\" readonly=\\"state != 'draft' and not additional\\" options=\\"{'no_open': True, 'no_create': True}\\" widget=\\"many2one_uom\\"/>\\n                                <field name=\\"picked\\" string=\\"Picked\\" optional=\\"hide\\"/>\\n                                <field name=\\"lot_ids\\" widget=\\"many2many_tags\\" groups=\\"stock.group_production_lot\\" invisible=\\"not show_details_visible or has_tracking != 'serial'\\" optional=\\"hide\\" context=\\"{'default_product_id': product_id}\\" domain=\\"[('product_id','=',product_id)]\\" readonly=\\"not id\\"/>\\n                                <button name=\\"action_show_details\\" type=\\"object\\" string=\\"Details\\" invisible=\\"not show_details_visible\\" options=\\"{&quot;warn&quot;: true}\\" context=\\"{'default_location_dest_id': location_dest_id}\\"/>\\n                            </list>\\n                        </field>\\n                        <div class=\\"clearfix\\"/>\\n                    </page>\\n                    <page string=\\"Repair Notes\\" name=\\"repair_notes\\">\\n    