uct_uom\\" groups=\\"uom.group_uom\\" widget=\\"many2one_uom\\" readonly=\\"state != 'draft'\\"/>\\n                            </div>\\n                            <field name=\\"picking_id\\" invisible=\\"not picking_id\\" options=\\"{'no_create': True}\\"/>\\n                            <field name=\\"under_warranty\\" readonly=\\"state in ['cancel', 'done']\\"/>\\n                        </group>\\n                        <group>\\n                            <field name=\\"schedule_date\\" readonly=\\"state in ['done', 'cancel']\\"/>\\n                            <field name=\\"user_id\\" domain=\\"[('share', '=', False)]\\"/>\\n                            <field name=\\"company_id\\" groups=\\"base.group_multi_company\\" options=\\"{'no_create': True}\\"/>\\n                            <field name=\\"tag_ids\\" widget=\\"many2many_tags\\" options=\\"{'color_field': 'color', 'no_create_edit': True}\\"/>\\n                            <field name=\\"parts_availability_state\\" invisible=\\"True\\"/>\\n                            <field name=\\"parts_availability\\" invisible=\\"state not in ['confirmed', 'under_repair']\\" decoration-success=\\"parts_availability_state == 'available'\\" decoration-warning=\\"parts_availability_state == 'expected'\\" decoration-danger=\\"parts_availability_state == 'late'\\"/>\\n                            <field name=\\"picking_type_id\\" options=\\"{'no_create': True}\\" readonly=\\"state in ('done', 'cancel')\\" invisible=\\"not picking_type_visible\\"/>\\n                        </group>\\n                        <field name=\\"repair_properties\\" nolabel=\\"1\\" columns=\\"2\\" hideAddButton=\\"1\\"/>\\n                    </group>\\n                <notebook>\\n                    <page string=\\"Piezas\\" name=\\"parts\\">\\n                        <field name=\\"move_ids\\" readonly=\\"state == 'cancel' or state == 'done'\\" context=\\"{'default_repair_id': id, 'default_product_uom_qty': 1, 'default_company_id': company_i