\\"exclude_journal_item\\"/>\\n                        </group>\\n                        <separator string=\\"Options\\" invisible=\\"state not in ('option',)\\"/>\\n                        <group invisible=\\"state not in ('option', 'finished')\\">\\n                            <field name=\\"maximum_group\\" readonly=\\"state == 'finished'\\"/>\\n                        </group>\\n                        <separator string=\\"Merge the following contacts\\" invisible=\\"state in ('option', 'finished')\\"/>\\n                        <group invisible=\\"state in ('option', 'finished')\\" col=\\"1\\">\\n                            <p class=\\"opacity-50\\">\\n                                Selected contacts will be merged together.\\n                                All documents linked to one of these contacts\\n                                will be redirected to the destination contact.\\n                                You can remove contacts from this list to avoid merging them.\\n                            </p>\\n                            <group col=\\"2\\">\\n                                <field name=\\"dst_partner_id\\" domain=\\"[('id', 'in', partner_ids or False)]\\" required=\\"state == 'selection'\\" context=\\"{'partner_show_db_id': True}\\"/>\\n                            </group>\\n                            <field name=\\"partner_ids\\" nolabel=\\"1\\">\\n                                <list string=\\"Partners\\">\\n                                    <field name=\\"id\\"/>\\n                                    <field name=\\"display_name\\"/>\\n                                    <field name=\\"email\\"/>\\n                                    <field name=\\"is_company\\"/>\\n                                    <field name=\\"vat\\"/>\\n                                    <field name=\\"country_id\\"/>\\n                                </list>\\n                            </field>\\n                        </group>\\n                    </sheet>\\n                    <footer>\\n                        <button name=\\"action_merge\\" string=\\"Merge Contacts\\" class=\\"oe_highlight\\" type=\\"object\\" data-hotkey=\\"q\\" invisible=\\"state in ('option', 'finished')\\"/>\\n                        <button name=\\"action_skip\\" string=\\"Skip these contacts\\" type=\\"object\\" invisible=\\"state != 'selection'\\"/>\\n                        <button name=\\"action_start_manual_process\\" string=\\"Merge with Manual Check\\" data-hotkey=\\"w\\" type=\\"object\\" class=\\"oe_highlight\\" invisible=\\"state != 'option'\\"/>\\n                        <button name=\\"action_start_automatic_process\\" string=\\"Merge Automatically\\" data-hotkey=\\"l\\" type=\\"object\\" class=\\"oe_highlight\\" confirm=\\"Are you sure to execute the automatic merge of your contacts?\\" invisible=\\"state != 'option'\\"/>\\n                        <button name=\\"action_update_all_process\\" string=\\"Merge Automatically all process\\" type=\\"object\\" data-hotkey=\\"y\\" confirm=\\"Are you sure to execute the list of automatic merges of your contacts?\\" invisible=\\"state != 'option'\\"/>\\n                        <button special=\\"cancel\\" data-hotkey=\\"x\\" string=\\"Cancel\\" type=\\"object\\" class=\\"btn btn-secondary oe_inline\\" invisible=\\"state == 'finished'\\"/>\\n                        <button special=\\"cancel\\" data-hotkey=\\"x\\" string=\\"Close\\" type=\\"object\\" class=\\"btn btn-secondary oe_inline\\" invisible=\\"state != 'finished'\\"/>\\n                    </footer>\\n                </form>", "es_ES": "<form string=\\"Asistente de fusión automática\\" class=\\"o_partner_merge_wizard\\">\\n                    <sheet>\\n                        <group invisible=\\"state != 'finished'\\">\\n                            <h2 colspan=\\"2\\">No hay más contactos para combinar para esta solicitud</h2>\\n                            <button name=\\"49\\" string=\\"Deduplicar los otros contactos\\" class=\\