     <field name=\\"require_payment\\" class=\\"oe_inline\\"/>\\n                                <span invisible=\\"not require_payment\\">of</span>\\n                                <field name=\\"prepayment_percent\\" invisible=\\"not require_payment\\" widget=\\"percentage\\" class=\\"oe_inline\\"/>\\n                            </div>\\n                        </group>\\n                    </group>\\n                    <notebook name=\\"main_book\\">\\n                        <page string=\\"Lines\\" name=\\"order_lines\\">\\n                        <field name=\\"sale_order_template_line_ids\\" widget=\\"so_template_line_o2m\\" options=\\"{ 'subsections': True }\\">\\n                            <form string=\\"Quotation Template Lines\\">\\n                                <!--\\n                                    We need the sequence field to be here for new lines to be added at the correct position.\\n                                    TODO: at some point we want to fix this in the framework so that an invisible field is not required.\\n                                -->\\n                                <field name=\\"sequence\\" invisible=\\"1\\"/>\\n                                <field name=\\"display_type\\" invisible=\\"1\\"/>\\n                                <group invisible=\\"display_type\\">\\n                                    <group>\\n                                        <field name=\\"product_id\\" required=\\"not display_type\\"/>\\n                                        <label for=\\"product_uom_qty\\"/>\\n                                        <div>\\n                                            <field name=\\"product_uom_qty\\" class=\\"oe_inline\\"/>\\n                                        </div>\\n                                    </group>\\n                                </group>\\n                                <notebook colspan=\\"4\\" name=\\"description\\">\\n                                    <page string=\\"Description\\" name=\\"order_description\\" invisible=\\"display_type\\">\\n                                        <field name=\\"name\\"/>\\n                                    </page>\\n                                    <page string=\\"Section\\" name=\\"order_section\\" invisible=\\"display_type != 'line_section'\\">\\n                                        <field name=\\"name\\"/>\\n                                    </page>\\n                                    <page string=\\"Note\\" name=\\"order_note\\" invisible=\\"display_type != 'line_note'\\">\\n                                        <field name=\\"name\\"/>\\n                                    </page>\\n                                </notebook>\\n                            </form>\\n                            <list string=\\"Quotation Template Lines\\" editable=\\"bottom\\">\\n                                <control>\\n                                    <create name=\\"add_product_control\\" string=\\"Add a product\\"/>\\n                                    <create name=\\"add_section_control\\" string=\\"Add a section\\" context=\\"{'default_display_type': 'line_section'}\\"/>\\n                                    <create name=\\"add_note_control\\" string=\\"Add a note\\" context=\\"{'default_display_type': 'line_note'}\\"/>\\n                                </control>\\n                                <field name=\\"display_type\\" column_invisible=\\"True\\"/>\\n                                <field name=\\"is_optional\\" column_invisible=\\"True\\"/>\\n                                <field name=\\"sequence\\" widget=\\"handle\\"/>\\n                                <field name=\\"product_id\\"/>\\n                                <field name=\\"name\\" widget=\\"section_and_note_text\\"/>\\n                                <field name=\\"product_uom_qty\\"/>\\n                                <field name=\\"product_uom_id\\" groups=\\"uom.group_uom\\" required=\\"not display_type\\"/>\\n                            </list>\\n                        </field>\\n                    </page>\\n                        <page string=\\"Terms &amp; Conditions\\" name=\\"terms_and_conditions\\">\\n                            <field name=\\"note\\" nolabel=\\"1\\" placeholder=\\"The Administrator can set default Terms &amp; Conditions in Sales Settings. Terms set here will show up instead if you select this quotation template.\\"/>\\n                        </page>\\n                    </notebook>\\n                </sheet>\\n            </form>", "es_ES": "<form string=\\"Plantilla de presupuesto\\">\\n                <sheet>\\n                    <div name=\\"button_box\\" class=\\"oe_button_box\\"/>\\n                    <widget name=\\"web_ribbon\\" title=\\"Archivado\\" bg_color=\\"text-bg-danger\\" invisible=\\"active\\"/>\\n                    <div class=\\"oe_title\\" name=\\"sale_order_template_title\\">\\n                        <label for=\\"name\\" id=\\"sale_order_template_title\\"/>\\n                        <h1>\\n                            <field name=\\"name\\" placeholder=\\"p. ej. paquete estándar de consultoría\\" class=\\"d-block\\"/>\\n                        </h1>\\n                    </div>\\n                    <group>\\n                        <group name=\\"sale_info\\">\\n                            <field name=\\"active\\" invisible=\\"1\\"/>\\n                            <label for=\\"number_of_days\\" string=\\"Validez del presupuesto\\"/>\\n                            <div id=\\"number_of_days\\">\\n                                <field name=\\"number_of_days\\" style=\\"width: 3rem;\\"/>\\n                                <div class=\\"d-inline-block\\">días</div>\\n                            </div>\\n                            <field name=\\"mail_template_id\\" context=\\"{'default_model': 'sale.order'}\\"/>\\n                            <field name=\\"company_id\\" options=\\"{'no_create': True}\\" groups=\\"base.group_multi_company\\" placeholder=\\"Visible para todos\\"/>\\n                            <field name=\\"journal_id\\"/>\\n                        </group>\\n                        <group name=\\"so_confirmation\\">\\n                            <field name=\\"require_signature\\"/>\\n                            <label for=\\"require_payment\\"/>\\n                            <div id=\\"require_payment\\" class=\\"o_row\\">\\n                                <field name=\\"require_payment\\" class=\\"oe_inline\\"/>\\n                                <span invisible=\\"not require_payment\\">de</span>\\n                                <field name=\\"prepayment_percent\\" invisible=\\"not require_payment\\" widget=\\"percentage\\" class=\\"oe_inline\\"/>\\n                            </div>\\n                        </group>\\n                    </group>\\n                    <notebook name=\\"main_book\\">\\n                        <page string=\\"Líneas\\" name=\\"order_lines\\">\\n                        <field name=\\"sale_order_template_line_ids\\" widget=\\"so_template_line_o2m\\" options=\\"{ 'subsections': True }\\">\\n                            <form string=\\"Líneas de plantilla de presupuesto\\">\\n                                <!--\\n                                    We need the sequence field to be here for new lines to be added at the correct position.\\n                                    TODO: at some point we want to fix this in the framework so that an invisible field is not required.\\n                                -->\\n                                <field name=\\"sequence\\" invisible=\\"1\\"/>\\n                                <field name=\\"display_type\\" invisible=\\"1\\"/>\\n                                <group invisible=\\"display_type\\">\\n                                    <group>\\n                                        <field name=\\"product_id\\" required=\\"not display_type\\"/>\\n                                        <label for=\