_attachment_preview" invisible="move_type not in ('out_invoice', 'out_refund', 'in_invoice', 'in_refund') or state != 'draft'"/>\n                    <!-- Chatter -->\n                    <chatter reload_on_attachment="True"/>\n                </form>\n            	f	t	2026-11-17 08:42:28.455657	2026-11-20 12:35:53.984544	f	\N	\N	\N	\N	\N	\N	\N	\N	\N	f	\N
