1643	16	1642	1	1	Header Brand Logo	\N	website.option_header_brand_logo	qweb	website/views/website_templates.xml	extension	{"en_US": "<data inherit_id=\\"website.placeholder_header_brand\\" name=\\"Header Brand Logo\\" active=\\"True\\">\\n    <xpath expr=\\"//*[@id='o_fake_navbar_brand']\\" position=\\"replace\\">\\n        <a data-name=\\"Navbar Logo\\" href=\\"/\\" t-attf-class=\\"navbar-brand logo #{_link_class}\\">\\n            <!--\\n            Note: setting width *and* height attributes allows to reserve some\\n            space to avoid layout shift during page loading. Of course, CSS\\n            rules set the height the user chose, while the width is set to\\n            'auto'. But while the image is loading, it is best to already\\n            reserve some width to reduce layout shift (like making the menu move\\n            or even re-render itself into a \\"+\\" menu).\\n\\n            The chosen values for the space reservation are the ones of the\\n            default logo and theme, but it does not really matter as long as\\n            they are coherent. While the image is being loaded, the chosen user\\n            height is still applied and the 'auto' width rule induces a width\\n            that respects the aspect ratio set by the width and height\\n            attributes. That could be a problem if the real logo has a larger\\n            height than width, in which case the layout shift would be increased\\n            because of the arbitrary values set as width and height, but in most\\n            cases, this should reduce it.\\n\\n            This also allows to gain some page speed scoring.\\n            -->\\n            <t t-set=\\"base_options\\" t-value=\\"{'widget': 'image'}\\"/>\\n            <span t-field=\\"website.logo\\" t-options=\\"base_options if editable else dict(base_options, width=95, height=40)\\" role=\\"img\\" t-att-aria-label=\\"'Logo of %s' % website.name\\" t-att-title=\\"website.name\\"/>\\n        </a>\\n    </xpath>\\n</data>"}	<?xml version="1.0"?>\n<data inherit_id="website.placeholder_header_brand" name="Header Brand Logo" active="True">\n    <xpath expr="//*[@id='o_fake_navbar_brand']" position="replace">\n        <a data-name="Navbar Logo" href="/" t-attf-class="navbar-brand logo #{_link_class}">\n            <!--\n            Note: setting width *and* height attributes allows to reserve some\n            space to avoid layout shift during page loading. Of course, CSS\n            rules set the height the user chose, while the width is set to\n            'auto'. But while the image is loading, it is best to already\n            reserve some width to reduce layout shift (like making the menu move\n            or even re-render itself into a "+" menu).\n\n            The chosen values for the space reservation are the ones of the\n            default logo and theme, but it does not really matter as long as\n            they are coherent. While the image is being loaded, the chosen user\n            height is still applied and the 'auto' width rule induces a width\n            that respects the aspect ratio set by the width and height\n            attributes. That could be a problem if the real logo has a larger\n            height than width, in which case the layout shift would be increased\n            because of the arbitrary values set as width and height, but in most\n            cases, this should reduce it.\n\n            This also allows to gain some page speed scoring.\n            -->\n            <t t-set="base_options" t-value="{'widget': 'image'}"/>\n            <span t-field="website.logo" t-options="base_options if editable else dict(base_options, width=95, height=40)" role="img" t-att-aria-label="'Logo of %s' % website.name" t-att-title="website.name"/>\n        </a>\n    </xpath>\n</data>\n\n	f	t	2026-11-20 12:35:53.984544	2026-11-20 12:35:53.984544	f	\N	\N	\N	\N	\N	\N	\N	\N	\N	f	f
