l-md-3 mt16\\">\\n                                    <input type=\\"text\\" id=\\"page-name\\" class=\\"form-control\\" required=\\"required\\" placeholder=\\"sí\\"/>\\n                                </div>\\n                            </div>\\n                        </main>\\n                        <footer class=\\"modal-footer\\">\\n                            <button type=\\"button\\" class=\\"btn\\" data-bs-dismiss=\\"modal\\" aria-label=\\"Cancelar\\">Cancelar</button>\\n                            <input type=\\"submit\\" value=\\"Confirm\\" class=\\"btn btn-primary\\"/>\\n                        </footer>\\n                    </div>\\n                </form>\\n            </div>\\n        </div>\\n    </xpath>\\n    <xpath expr=\\"//div[@id='error_message']\\" position=\\"after\\">\\n        <div class=\\"container\\" t-if=\\"view and editable\\">\\n            <div class=\\"alert alert-danger\\" role=\\"alert\\">\\n                <h4>Alternativa a la plantilla</h4>\\n                <p>Ocurrió un error al visualizar la plantilla <code t-out=\\"qweb_exception.template\\"/>.</p>\\n                <p>Si este error es causado por un cambio suyo en las plantillas, tiene la posibilidad de restablecer la plantilla a su <strong>configuración de fábrica</strong>.</p>\\n                <form action=\\"#\\" method=\\"post\\" id=\\"reset_templates_form\\">\\n                    <ul>\\n                        <li>\\n                            <label>\\n                                <t t-out=\\"view.name\\"/>\\n                            </label>\\n                        </li>\\n                    </ul>\\n                    <input type=\\"hidden\\" name=\\"redirect\\" t-att-value=\\"request.httprequest.path\\"/>\\n                    <input type=\\"hidden\\" id=\\"reset_templates_view_id\\" name=\\"view_id\\" t-att-value=\\"view.id\\"/>\\n                    <input type=\\"hidden\\" id=\\"reset_templates_mode\\" name=\\"mode\\"/>\\n                    <butto