                 <field name=\\"website_default_lang_id\\" options=\\"{'no_open': True, 'no_create': True}\\" required=\\"website_id\\"/>\\n                            </div>\\n                            <div class=\\"mt8\\">\\n                                <button type=\\"action\\" name=\\"44\\" string=\\"Install new languages\\" class=\\"btn-link\\" icon=\\"oi-arrow-right\\"/>\\n                            </div>\\n                        </setting>\\n                        <setting string=\\"Website Identification\\" help=\\"Set your website's name and favicon, displayed in the browser tab next to the page title.\\">\\n                            <div class=\\"content-group\\">\\n                                <div class=\\"row mt8\\">\\n                                    <label class=\\"col-lg-3\\" string=\\"Name\\" for=\\"website_name\\"/>\\n                                    <field name=\\"website_name\\" required=\\"website_id\\"/>\\n                                </div>\\n                                <div class=\\"row mt8\\">\\n                                    <label class=\\"col-lg-3\\" string=\\"Favicon\\" for=\\"favicon\\"/>\\n                                    <field name=\\"favicon\\" widget=\\"image\\" class=\\"float-start o_avatar bg-view\\"/>\\n                                </div>\\n                            </div>\\n                        </setting>\\n                        <setting string=\\"Company\\" title=\\"The company this website is linked to\\" groups=\\"base.group_multi_company\\">\\n                            <field name=\\"website_company_id\\" required=\\"website_id\\"/>\\n                        </setting>\\n                        <setting id=\\"shared_user_account_setting\\" help=\\"Accounts created on this website are usable across all other websites\\" groups=\\"website.group_multi_website\\">\\n                            <field name=\\"shared_user_account\\"/>\\n                        </setting>\\n                        <setting id=\\"website_login_documents\\" title=\\" To send invitations in B2B mode, open a contact or select several ones in list view and click on 'Portal Access Management' option in the dropdown menu *Action*.\\" help=\\"Let your customers log in to see their documents\\">\\n                            <field name=\\"auth_signup_uninvited\\" class=\\"o_light_label\\" widget=\\"radio\\" options=\\"{'horizontal': true}\\" required=\\"True\\"/>\\n                            <div class=\\"content-group\\" invisible=\\"auth_signup_uninvited == 'b2b'\\">\\n                                <div class=\\"mt8\\">\\n                                    <button type=\\"object\\" name=\\"action_open_template_user\\" string=\\"Default Access Rights\\" icon=\\"oi-arrow-right\\" class=\\"btn-link\\"/>\\n                                </div>\\n                            </div>\\n                        </setting>\\n                        <setting id=\\"livechat\\" string=\\"Livechat\\" help=\\"Allows your visitors to chat with you\\">\\n                            <field name=\\"module_website_livechat\\"/>\\n                        </setting>\\n                    </block>\\n                    <block title=\\"Tracking &amp; SEO\\" id=\\"website_settings\\" invisible=\\"not website_id\\">\\n                        <setting id=\\"plausible_setting\\" help=\\"Simple and privacy-friendly Google Analytics alternative\\" documentation=\\"/applications/websites/website/reporting/analytics.html#analytics-plausible\\">\\n                            <field name=\\"has_plausible_shared_key\\"/>\\n                            <div class=\\"content-group\\" invisible=\\"not has_plausible_shared_key\\">\\n                                <div class=\\"row mt16\\">\\n                                    <label class=\\"col-lg-3 o_light_label\\" string=\\"Shared Link Auth\\" for=\\"plausible_shared_key\\"/>\\n                                    <field name=\\"plausible_shared_key\\" required=\\"has_plausible_shared_key\\"/>\\n                                </div>\\n                                <div class=\\"row mt16\\">\\n                                    <label class=\\"col-lg-3 o_light_label\\" string=\\"Site\\" for=\\"plausible_site\\"/>\\n                                    <field name=\\"plausible_site\\" required=\\"has_plausible_shared_key\\"/>\\n                                </div>\\n                            </div>\\n                            <div invisible=\\"not has_plausible_shared_key\\">\\n                                <button type=\\"action\\" name=\\"585\\" string=\\" See Analytics Report\\" class=\\"btn-link fw-normal border-0\\" icon=\\"oi-arrow-right d-inline me-auto\\"/>\\n                            </div>\\n                            <div invisible=\\"not has_plausible_shared_key\\">\\n                                <widget class=\\"oe_link\\" name=\\"documentation_link\\" path=\\"/applications/websites/website/reporting/analytics.html#analytics-plausible\\" label=\\" How to create my Plausible Shared Link\\" icon=\\"oi oi-arrow-right\\"/>\\n                            </div>\\n                        </setting>\\n                        <setting id=\\"google_analytics_setting\\" help=\\"Track visits using Google Analytics or Google Tag Manager\\" documentation=\\"/applications/websites/website/reporting/analytics.html#analytics-google-analytics\\">\\n                            <field name=\\"has_google_analytics\\"/>\\n                            <div class=\\"content-group\\" invisible=\\"not has_google_analytics\\">\\n                                <div class=\\"row mt16\\">\\n                                    <label class=\\"col-lg-3 o_light_label\\" string=\\"Measurement ID or Tag\\" for=\\"google_analytics_key\\"/>\\n                                    <field name=\\"google_analytics_key\\" placeholder=\\"G-XXXXXXXXXX or GTM-XXXXXXX\\" required=\\"has_google_analytics\\"/>\\n                                </div>\\n                            </div>\\n                            <div invisible=\\"not has_google_analytics\\">\\n                                <widget class=\\"oe_link\\" name=\\"documentation_link\\" path=\\"/applications/websites/website/reporting/analytics.html#analytics-google-analytics\\" label=\\" How to get my Measurement ID\\" icon=\\"oi oi-arrow-right\\"/>\\n                            </div>\\n                        </setting>\\n                        <setting id=\\"cdn_setting\\" title=\\"A CDN helps you serve your website’s content with high availability and high performance to any visitor wherever they are located.\\" groups=\\"base.group_no_one\\" help=\\"Use a CDN to optimize the availability of your website's content\\" documentation=\\"/applications/websites/website/configuration/cdn.html\\">\\n                            <field name=\\"cdn_activated\\"/>\\n                            <div class=\\"content-group\\" invisible=\\"not cdn_activated\\">\\n                                <div class=\\"row mt16\\">\\n                                    <label class=\\"col-lg-3 o_light_label\\" for=\\"cdn_url\\"/>\\n                                    <field name=\\"cdn_url\\" required=\\"cdn_activated\\" placeholder=\\"//mycompany.mycdn.com/\\" t-translation=\\"off\\"/>\\n                                </div>\\n                                <div class=\\"row\\">\\n                                    <label class=\\"col-lg-3 o_light_label\\" for=\\"cdn_filters\\"/>\\n                                    <field name=\\"cdn_filters\\" class=\\"oe_inline\\" required=\\"cdn_activated\\"/>\\n                                </div>\\n                            </div>\\n                        </setting>\\n                        <setting id=\\"robots_setting\\" string=\\"Robots.txt\\" help=\\"Robots.txt: This file tells to search engine crawlers which pages or files they can or can't request from your site.\\" groups=\\"base.group_no_one\\">\\n                            <div class=\\"mt4\\">\\n                                <button type=\\"object\\" name=\\"action_open_robots\\" string=\\"Edit robots.txt\\" class=\\"btn-link\\" icon=\\"fa-android\\" noSaveDialog=\\"true\\"/>\\n                            </div>\\n                        </setting>\\n                        <setting id=\\"social_default_image_setting\\" string=\\"Default Social Share Image\\" help=\\"If set, replaces the website logo as the default social share image.\\">\\n                            <field name=\\"has_default_share_image\\"/>\\n                            <field name=\\"social_default_image\\" widget=\\"image\\" class=\\"w-25 mt-2\\" invisible=\\"not has_default_share_image\\"/>\\n                        </setting>\\n                        <setting id=\\"google_console_setting\\" help=\\"Monitor Google Search results data\\" documentation=\\"/applications/websites/website/configuration/google_search_console.html\\">\\n                            <field name=\\"has_google_search_console\\"/>\\n                            <div class=\\"content-group\\" invisible=\\"not has_google_search_console\\">\\n                                <div class=\\"row mt16\\">\\n                                    <label class=\\"col-lg-3 o_light_label\\" string=\\"Code\\" for=\\"google_search_console\\"/>\\n                                    <field name=\\"google_search_console\\" placeholder=\\"google1234567890123456.html\\" required=\\"has_google_search_console\\"/>\\n                                </div>\\n                            </div>\\n                            <div invisible=\\"not has_google_search_console\\">\\n                                <widget class=\\"oe_link\\" name=\\"documentation_link\\" path=\\"/applications/websites/website/configuration/google_search_console.html\\" label=\\" How to?\\" icon=\\"oi oi-arrow-right\\"/>\\n                            </div>\\n                        </setting>\\n                        <setting id=\\"website_cookies_bar_setting\\" help=\\"Display a customizable cookies bar on your website. Please ensure your site is GDPR-compliant (e.g. Google Fonts usage).\\" documentation=\\"/applications/websites/website/configuration/cookies_bar.html\\">\\n                            <field name=\\"website_cookies_bar\\"/>\\n                            <div class=\\"content-group\\" invisible=\\"not website_cookies_bar\\">\\n                                <div>\\n                                    <field name=\\"website_block_third_party_domains\\" required=\\"website_cookies_bar\\"/>\\n                                    <label class=\\"o_light_label\\" string=\\"Block tracking 3rd-party services\\" for=\\"website_block_third_party_domains\\"/>\\n                                </div>\\n                                <div>\\n                                    <small class=\\"text-muted\\">\\n                                        Block 3rd-party services that track users (e.g. YouTube, Google Maps, Facebook...) when the user has not given their consent.\\n                                    </small>\\n                                </div>\\n                                <div class=\\"mt4\\">\\n                                    <button type=\\"object\\" name=\\"action_open_blocked_third_party_domains\\" string=\\"Add domains to the block list\\" class=\\"btn-link\\" icon=\\"fa-ban\\" noSaveDialog=\\"true\\"/>\\n                                </div>\\n                            </div>\\n                        </setting>\\n                    </block>\\n                </app>\\n            </xpath>", "es_ES": "<xpath expr=\\"//form\\" position=\\"inside\\">\\n                <app data-string=\\"Website\\" string=\\"Sitio web\\" name=\\"website\\" groups=\\"website.group_website_designer\\">\\n                    <setting id=\\"website_creation_settings\\" class=\\"bg-secondary\\" type=\\"header\\">\\n                        <field name=\\"website_id\\" options=\\"{'no_open': True, 'no_create': True}\\" title=\\"La configuración de esta página se aplicará a este sitio web\\"/>\\n                        <button name=\\"action_website_create_new\\" type=\\"object\\" string=\\"+ Nuevo sitio web\\" class=\\"btn btn-secondary mx-2 rounded-2\\"/>\\n                    </setting>\\n                    <block title=\\"General\\" id=\\"website_info_settings\\">\\n                        <setting string=\\"Dominio\\" help=\\"Mostrar este sitio web para esta dirección web\\" title=\\"Muestre el sitio web cuando los usuarios visiten este dominio\\" documentation=\\"/applications/websites/website/configuration/domain_names.html#domain-name-website-map\\">\\n                            <field name=\\"website_domain\\" placeholder=\\"https://www.odoo.com\\"/>\\n                        </setting>\\n                        <setting string=\\"Idiomas\\" title=\\"Idiomas disponibles en su sitio web\\" documentation=\\"/applications/websites/website/configuration/translate.html\\">\\n                            <field name=\\"language_ids\\" widget=\\"many2many_tags\\" options=\\"{'no_create': True, 'no_open': True}\\" required=\\"website_id\\"/>\\n                            <div class=\\"row mt8\\" invisible=\\"website_language_count &lt; 2\\">\\n                                <field name=\\"website_language_count\\" invisible=\\"1\\"/>\\n                                <label class=\\"col-lg-3\\" string=\\"Por defecto\\" for=\\"website_default_lang_id\\"/>\\n                                <field name=\\"website_default_lang_id\\" options=\\"{'no_open': True, 'no_create': True}\\" required=\\"website_id\\"/>\\n                            </div>\\n                            <div class=\\"mt8\\">\\n                                <button type=\\"action\\" name=\\"44\\" string=\\"Instalar nuevos idiomas\\" class=\\"btn-link\\" icon=\\"oi-arrow-right\\"/>\\n                            </div>\\n                        </setting>\\n                        <setting string=\\"Identificación del sitio web\\" help=\\"Configure el nombre de su sitio web y favicon, que aparece en la pestaña del navegador junto al título de la página.\\">\\n                            <div class=\\"content-group\\">\\n                                <div class=\\"row mt8\\">\\n                                    <label class=\\"col-lg-3\\" string=\\"Nombre\\" for=\\"website_name\\"/>\\n                                    <field name=\\"website_name\\" required=\\"website_id\\"/>\\n                                </div>\\n                                <div class=\\"row mt8\\">\\n                                    <label class=\\"col-lg-3\\" string=\\"Favicon\\" for=\\"favicon\\"/>\\n                                    <field name=\\"favicon\\" widget=\\"image\\" class=\\"float-start o_avatar bg-view\\"/>\\n                                </div>\\n                            </div>\\n                        </setting>\\n                        <setting string=\\"Compañía\\" title=\\"La compañía a la que está vinculada este sitio web\\" groups=\\"base.group_multi_company\\">\\n                            <field name=\\"website_company_id\\" required=\\"website_id\\"/>\\n                        </setting>\\n                        <setting id=\\"shared_user_account_setting\\" help=\\"Accounts created on this website are usable across all other websites\\" groups=\\"website.group_multi_website\\">\\n                            <field name=\\"shared_user_account\\"/>\\n                        </setting>\\n                        <setting id=\\"website_login_documents\\" title=\\"Para enviar invitaciones en modo B2B, abre un contacto o seleccciona varios en la vista modo lista y haga clic en la opción 'Gestión de acceso al Portal'  del menú desplegable *Acción*.\\" help=\\"Deje que sus clientes inicien sesión para ver sus documentos\\">\\n                            <field name=\\"auth_signup_uninvited\\" class=\\"o_light_label\\" widget=\\"radio\\" options=\\"{'horizontal': true}\\" required=\\"True\\"/>\\n                            <div class=\\"content-group\\" invisible=\\"auth_signup_uninvited == 'b2b'\\">\\n                                <div class=\\"mt8\\">\\n                                    <button type=\\"object\\" name=\\"action_open_template_user\\" string=\\"Permiso de acceso por defecto\\" icon=\\"oi-arrow-right\\" class=\\"btn-link\\"/>\\n                                </div>\\n                            </div>\\n                        </setting>\\n                        <setting id=\\"livechat\\" string=\\"Chat en directo\\" help=\\"Permite que sus visitantes chateen con usted\\">\\n                            <field name=\\"module_website_livechat\\"/>\\n                        </setting>\\n                    </block>\\n                    <block title=\\"Seguimiento y SEO\\" id=\\"website_settings\\" invisible=\\"not website_id\\">\\n                        <setting id=\\"plausible_setting\\" help=\\"Alternativa a Google Analytics sencilla y respetuosa con la privacidad\\" documentation=\\"/applications/websites/website/reporting/analytics.html#analytics-plausible\\">\\n                            <field name=\\"has_plausible_shared_key\\"/>\\n                            <div class=\\"content-group\\" invisible=\\"not has_plausible_shared_key\\">\\n                                <div class=\\"row mt16\\">\\n                                    <label class=\\"col-lg-3 o_light_label\\" string=\\"Autenticación de enlace compartido\\" for=\\"plausible_shared_key\\"/>\\n                                    <field name=\\"plausible_shared_key\\" required=\\"has_plausible_shared_key\\"/>\\n                                </div>\\n                                <div class=\\"row mt16\\">\\n                                    <label class=\\"col-lg-3 o_light_label\\" string=\\"Sitio\\" for=\\"plausible_site\\"/>\\n                                    <field name=\\"plausible_site\\" required=\\"has_plausible_shared_key\\"/>\\n                                </div>\\n                            </div>\\n                            <div invisible=\\"not has_plausible_shared_key\\">\\n                                <button type=\\"action\\" name=\\"585\\" string=\\"Ver el informe de análisis\\" class=\\"btn-link fw-normal border-0\\" icon=\\"oi-arrow-right d-inline me-auto\\"/>\\n                            </div>\\n                            <div invisible=\\"not has_plausible_shared_key\\">\\n                                <widget class=\\"oe_link\\" name=\\"documentation_link\\" path=\\"/applications/websites/website/reporting/analytics.html#analytics-plausible\\" label=\\"Cómo crear mi enlace compartido de Plausible\\" icon=\\"oi oi-arrow-right\\"/>\\n                            </div>\\n                        </setting>\\n                        <setting id=\\"google_analytics_setting\\" help=\\"Realice seguimiento de sus visitas con Google Analytics o Google Tag Manager\\" documentation=\\"/applications/websites/website/reporting/analytics.html#analytics-google-analytics\\">\\n                            <field name=\\"has_google_analytics\\"/>\\n                            <div class=\\"content-group\\" invisible=\\"not has_google_analytics\\">\\n                                <div class=\\"row mt16\\">\\n                                    <label class=\\"col-lg-3 o_light_label\\" string=\\"ID de medición o etiqueta\\" for=\\"google_analytics_key\\"/>\\n                                    <field name=\\"google_analytics_key\\" placeholder=\\"G-XXXXXXXXXX o GTM-XXXXXXX\\" required=\\"has_google_analytics\\"/>\\n                                </div>\\n                            </div>\\n                            <div invisible=\\"not has_google_analytics\\">\\n                                <widget class=\\"oe_link\\" name=\\"documentation_link\\" path=\\"/applications/websites/website/reporting/analytics.html#analytics-google-analytics\\" label=\\"Cómo obtener mi ID de medición\\" icon=\\"oi oi-arrow-right\\"/>\\n                            </div>\\n                        </setting>\\n                        <setting id=\\"cdn_setting\\" title=\\"Un CDN le ayuda a servir el contenido de su sitio web con alta disponibilidad y alto rendimiento a cualquier visitante sea cual sea su ubicación.\\" groups=\\"base.group_no_one\\" help=\\"Utilice una CDN para optimizar la disponibilidad del contenido de su sitio web\\" documentation=\\"/applications/websites/website/configuration/cdn.html\\">\\n                            <field name=\\"cdn_activated\\"/>\\n                            <div class=\\"content-group\\" invisible=\\"not cdn_activated\\">\\n                                <div class=\\"row mt16\\">\\n                                    <label class=\\"col-lg-3 o_light_label\\" for=\\"cdn_url\\"/>\\n                                    <field name=\\"cdn_url\\" required=\\"cdn_activated\\" placeholder=\\"//mycompany.mycdn.com/\\" t-translation=\\"off\\"/>\\n                                </div>\\n                                <div class=\\"row\\">\\n                                    <label class=\\"col-lg-3 o_light_label\\" for=\\"cdn_filters\\"/>\\n                                    <field name=\\"cdn_filters\\" class=\\"oe_inline\\" required=\\"cdn_activated\\"/>\\n                                </div>\\n                            </div>\\n                        </setting>\\n                        <setting id=\\"robots_setting\\" string=\\"Robots.txt\\" help=\\"Robots.txt: este archivo indica a los rastreadores de los motores de búsqueda qué páginas o archivos pueden o no solicitar de su sitio.\\" groups=\\"base.group_no_one\\">\\n                            <div class=\\"mt4\\">\\n                                <button type=\\"object\\" name=\\"action_open_robots\\" string=\\"Editar robots.txt\\" class=\\"btn-link\\" icon=\\"fa-android\\" noSaveDialog=\\"true\\"/>\\n                            </div>\\n                        </setting>\\n                        <setting id=\\"social_default_image_setting\\" string=\\"Imagen por defecto para compartir en redes sociales\\" help=\\"Si se establece, reemplaza el logotipo del sitio web como la imagen por defecto para compartir en redes sociales.\\">\\n                            <field name=\\"has_default_share_image\\"/>\\n                            <field name=\\"social_default_image\\" widget=\\"image\\" class=\\"w-25 mt-2\\" invisible=\\"not has_default_share_image\\"/>\\n                        </setting>\\n                        <setting id=\\"google_console_setting\\" help=\\"Supervisar los datos de los resultados de búsqueda de Google\\" documentation=\\"/applications/websites/website/configuration/google_search_console.html\\">\\n                            <field name=\\"has_google_search_console\\"/>\\n                            <div class=\\"content-group\\" invisible=\\"not has_google_search_console\\">\\n                                <div class=\\"row mt16\\">\\n                                    <label class=\\"col-lg-3 o_light_label\\" string=\\"Código\\" for=\\"google_search_console\\"/>\\n                                    <field name=\\"google_search_console\\" placeholder=\\"google12345689013456.html\\" required=\\"has_google_search_console\\"/>\\n                                </div>\\n                            </div>\\n                            <div invisible=\\"not has_google_search_console\\">\\n                                <widget class=\\"oe_link\\" name=\\"documentation_link\\" path=\\"/applications/websites/website/configuration/google_search_console.html\\" label=\\"¿Cómo?\\" icon=\\"oi oi-arrow-right\\"/>\\n                            </div>\\n                        </setting>\\n                        <setting id=\\"website_cookies_bar_setting\\" help=\\"Muestra una barra de cookies personalizable en tu sitio web. Asegúrate de que tu sitio web cumpla con el RGPD (por ejemplo, el uso de Google Fonts).\\" documentation=\\"/applications/websites/website/configuration/cookies_bar.html\\">\\n                            <field name=\\"website_cookies_bar\\"/>\\n                            <div class=\\"content-group\\" invisible=\\"not website_cookies_bar\\">\\n                                <div>\\n                                    <field name=\\"website_block_third_party_domains\\" required=\\"website_cookies_bar\\"/>\\n                                    <label class=\\"o_light_label\\" string=\\"Bloquear servicios de seguimiento de terceros\\" for=\\"website_block_third_party_domains\\"/>\\n                                </div>\\n                                <div>\\n                                    <small class=\\"text-muted\\">\\n                                        Bloquee los servicios externos que puedan rastrear a los usuarios (como YouTube, Google Maps, Facebook...) cuando estos no han proporcionado su consentimiento.\\n                                    </small>\\n                                </div>\\n                                <div class=\\"mt4\\">\\n                                    <button type=\\"object\\" name=\\"action_open_blocked_third_party_domains\\" string=\\"Añadir dominios a la lista de bloqueo\\" class=\\"btn-link\\" icon=\\"fa-ban\\" noSaveDialog=\\"true\\"/>\\n                                </div>\\n                            </div>\\n                        </setting>\\n                    </block>\\n                </app>\\n            </xpath>"}	<?xml version="1.0"?>\n<xpath expr="//form" position="inside">\n                <app data-string="Website" string="Website" name="website" groups="website.group_website_designer">\n                    <setting id="website_creation_settings" class="bg-secondary" type="header">\n                        <field name="website_id" options="{'no_open': True, 'no_create': True}" title="Settings on this page will apply to this website"/>\n                        <button name="action_website_create_new" type="object" string="+ New Website" class="btn btn-secondary mx-2 rounded-2"/>\n                    </setting>\n                    <block title="General" id="website_info_settings">\n                        <setting string="Domain" help="Display this website for this web address" title="Display this website when users visit this domain" documentation="/applications/websites/website/configuration/domain_names.html#domain-name-website-map">\n                            <field name="website_domain" placeholder="https://www.odoo.com"/>\n                        </setting>\n                        <setting string="Languages" title="Languages available on your website" documentation="/applications/websites/website/configuration/translate.html">\n                            <field name="language_ids" widget="many2many_tags" options="{'no_create': True, 'no_open': True}" required="website_id"/>\n                            <div class="row mt8" invisible="website_language_count &lt; 2">\n                                <field name="website_language_count" invisible="1"/>\n                                <label class="col-lg-3" string="Default" for="website_default_lang_id"/>\n                                <field name="website_default_lang_id" options="{'no_open': True, 'no_create': True}" required="website_id"/>\n                            </div>\n                            <div class="mt8">\n                                <button type="action" name="44" string="Install new languages" class="btn-link" icon="oi-arrow-right"/>\n                            </div>\n                        </setting>\n                        <setting string="Website Identification" help="Set your website's name and favicon, displayed in the browser tab next to the page title.">\n                            <div class="content-group">\n                                <div class="row mt8">\n                                    <label class="col-lg-3" string="Name" for="website_name"/>\n                                    <field name="website_name" required="website_id"/>\n                                </div>\n                                <div class="row mt8">\n                                    <label class="col-lg-3" string="Favicon" for="favicon"/>\n                                    <field name="favicon" widget="image" class="float-start o_avatar bg-view"/>\n                                </div>\n                            </div>\n                        </setting>\n                        <setting string="Company" title="The company this website is linked to" groups="base.group_multi_company">\n                            <field name="website_company_id" required="website_id"/>\n                        </setting>\n                        <setting id="shared_user_account_setting" help="Accounts created on this website are usable across all other websites" groups="website.group_multi_website">\n                            <field name="shared_user_account"/>\n                        </setting>\n                        <setting id="website_login_documents" title=" To send invitations in B2B mode, open a contact or select several ones in list view and click on 'Portal Access Management' option in the dropdown menu *Action*." help="Let your customers log in to see their documents">\n                            <field name="auth_signup_uninvited" class="o_light_label" widget="radio" options="{'horizontal': true}" required="True"/>\n                            <div class="content-group" invisible="auth_signup_uninvited == 'b2b'">\n                                <div class="mt8">\n                                    <button type="object" name="action_open_template_user" string="Default Access Rights" icon="oi-arrow-right" class="btn-link"/>\n                                </div>\n                            </div>\n          